(window.GIM_TS=window.GIM_TS||{})["Chullin.0"]={"from":0,"a":[["\u0003הכל שוחטין ושחיטתן כשרה, חוץ מחרש שוטה וקטן\u0004 שאינם שוחטים, \u0003שמא יקלקלו את שחיטתן,\u0004 שהרי אינם בני דעת. \u0003וכולן ששחטו ואחרים רואין אותן\u0004 ששחטו כדין — \u0003שחיטתן כשרה.\u0004","ושואלים: אם מדייקים בלשון המשנה נמצא שיש בה סתירה, שמתחילה התנא שונה: \u0003\"הכל שוחטין\"\u0004 — משמע שהכל ראויים לשחוט \u0003לכתחלה,\u0004 ואחר כך שנה: \u0003\"ושחיטתן כשרה\",\u0004 כלומר, רק ב\u0003דיעבד!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי\u0004 \u0003ו\u0004כי \u0003כל\u0004 מקום ששנינו \u0003\"הכל\u0004 (עושים כך וכך)\" רק לשון \u0003לכתחלה הוא,\u0004 ולא דיעבד? \u0003אלא מעתה,\u0004 מה ששנינו: \u0003הכל ממירין,\u0004 כלומר, עושים תמורה בקדשים, שאומר על בהמת חולין שתהיה תמורת בהמת קדשים מסויימת, \u0003אחד האנשים ואחד הנשים, הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003לכתחלה הוא\u0004 שממירים? \u0003והא כתיב\u0004 \u0005[והרי נאמר\u0006 בתורה\u0005]\u0006 במפורש: \u0003\"לא יחליפנו ולא ימיר אותו טוב ברע או רע בטוב\"\u0004 (ויקרא כז, י)!","ומשיבים: \u0003התם\u0004 \u0005[שם\u0006 יש מובן אחר לדבר\u0005],\u0006 \u0003כדקתני טעמא\u0004 \u0005[כמו שהוא שונה\u0006 באותה משנה \u0005את הטעם]:\u0006 \u0003לא שהאדם רשאי להמיר, אלא שאם המיר\u0004 — \u0003מומר,\u0004 שהקדושה חלה גם על מה שהמיר בו, \u0003וסופג\u0004 (לוקה) \u0003את הארבעים\u0004 מלקות מן התורה, שעבר על האיסור של \"לא ימיר אותו\".","ועוד הקשה רב אחא, \u0003אלא\u0004 לפי זה, מה ששנינו: \u0003הכל מעריכין,\u0004 כלומר, נודרים למקדש ערכו של אדם (הקצוב בתורה לפי גילו ומינו), \u0003ונערכין,\u0004 שניתן לנדור בערכו של כל אדם, וכן הכל \u0003נודרין\u0004 למקדש דמיו (שוויו בשוק) של אדם, \u0003ונידרין\u0004 שאפשר לנדור דמיו של כל אדם, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שהכוונה היא ש\u0003לכתחלה\u0004 מעריכים ונודרים? \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וכי תחדל לנדור לא יהיה בך חטא\"\u0004 (דברים כג, כג), ומשמע מכאן שראוי שלא לנדור;","\u0003וכתיב\u0004 \u0005[ונאמר]\u0006 עוד בפסוק אחר: \u0003\"טוב אשר לא תדור משתדור ולא תשלם\"\u0004 (קהלת ה, ד), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 על כתוב זה: \u0003טוב מזה ומזה\u0004 — מי \u0003שאינו נודר כל עיקר,\u0004 אלו \u0003דברי ר' מאיר, ר' יהודה אומר: טוב מזה ומזה\u0004 — מי ש\u0003נודר ומשלם. ואפילו ר' יהודה\u0004 שאמר שטוב להיות נודר ומשלם, \u0003לא קאמר\u0004 \u0005[אינו אומר]\u0006 דברים אלה \u0003אלא באומר\u0004 \u0003\"הרי זו\",\u0004 שנודר בהמה מסויימת לקרבן, שאין חשש שיעבור על נדרו, שאף אם אירעה תקלה ונגנבה הבהמה או אבדה — אינו חייב להביא אחרת במקומה."],["\u0003אבל\u0004 אם \u0003אמר \"הרי עלי\u0004 עולה\" שקיבל על עצמו חובה להביא בהמה לקרבן, ולא בהמה מסויימת, גם לדעת ר' יהודה \u0003לא\u0004 יעשה כן לכתחילה. הרי שמה ששנינו ש\"הכל מעריכין\" ו\"הכל נודרין\" אינו לכתחילה. ויש לפרש כן גם את \"הכל שוחטין\" ולא תיקשה לך לשון משנתנו! השיב רב אשי:","\u0003ו\u0004אלא תאמר כי \u0003כל\u0004 מקום שכתוב \u0003\"הכל\" לאו\u0004 \u0005[לא]\u0006 \u0003לכתחלה הוא? אלא\u0004 לפי זה, מה ששנינו: \u0003הכל חייבים בסוכה,\u0004 וכן \u0003הכל חייבין בציצית, הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר \u0003דלאו\u0004 \u0005[שאין]\u0006 כוונתו \u0003לכתחלה?\u0004","השיב רב אחא: במקום שנאמר \u0003\"הכל\u0004 \u0003חייבין\" לא קאמינא\u0004 \u0005[אין אני אומר],\u0006 ששם ברור שהכוונה היא לכתחילה. הוסיף וטען רב אשי: לדבריך אם כן כאשר לא נאמר \"הכל חייבין\" אין זה לכתחילה, ו\u0003אלא מעתה,\u0004 מה ששנינו: \u0003הכל סומכין\u0004 (על הקרבנות הטעונים סמיכה), \u0003אחד האנשים ואחד הנשים, הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר \u0003דלאו\u0004 \u0005[שאינו]\u0006 \u0003לכתחלה? והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וסמך ידו... ונרצה\u0004 לו לכפר עליו\" (ויקרא א, ד)!","השיב רב אחא: \u0003אין\u0004 \u0005[כן],\u0006 באמת, \u0003איכא\u0004 \u0005[יש]\u0006 פעמים \u0003ש\u0004\u0003\"הכל\"\u0004 כוונתו \u0003לכתחלה, ואיכא\u0004 \u0005[ויש]\u0006 פעמים ש\u0003\"הכל\"\u0004 כוונתו אף \u0003דיעבד.\u0004 \u0003אלא \"הכל\u0004 שוחטין\" \u0003דהכא\u0004 \u0005[של כאן]\u0006 \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 אתה יודע \u0003ש\u0004\u0003לכתחלה הוא, דתקשי\u0004 \u0005[שיקשה]\u0006 \u0003לך\u0004 הדבר? \u0003דלמא\u0004 \u0005[שמא]\u0006 ב\u0003דיעבד הוא, ולא תקשי\u0004 \u0005[תקשה]\u0006 \u0003לך,\u0004 שאין כאן סתירה, אלא \"הכל שוחטים ושחיטתן כשרה\" כולו בדיעבד!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי לרב אחא: עיקר שאלתי אינה ממשמעות לשון \"הכל\", אלא \u0003אנא\u0004 \u0005[אני]\u0006 הביטוי \u0003\"שחיטתן כשרה\"\u0004 \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003לי,\u0004 שכן \u0003מדקתני\u0004 \u0005[ממה שהוא שונה]\u0006 \u0003\"שחיטתן כשרה\"\u0004 שמשמעו ב\u0003דיעבד, מכלל\u0004 הדברים אתה מבין שמה שנאמר מתחילה \u0003\"הכל\u0004 שוחטים\" — \u0003לכתחלה הוא, דאי\u0004 \u0005[שאם]\u0006 תאמר שגם זה ב\u0003דיעבד, תרתי\u0004 \u0005[פעמיים]\u0006 ב\u0003דיעבד למה לי?\u0004 אלא ודאי ראשיתה לכתחילה וסופה דיעבד, ואם כן הדברים סותרים.","כדי ליישב את הסתירה מביאים כמה אופנים להסביר את המשנה. \u0003אמר רבה בר עולא, הכי קתני\u0004 \u0005[כך הוא שונה],\u0006 כך יש להסביר: \u0003הכל שוחטין\u0004 — \u0003ואפילו\u0004 ה\u0003טמא\u0004 שוחט לכתחילה \u0003בחולין.\u0004 ותחילה תוהים: \u0003טמא בחולין מאי למימרא\u0004 \u0005[מה לומר,\u0006 מה החידוש בזה\u0005],\u0006 שהרי אין איסור לטמא דברי חולין! ומשיבים: מדובר \u0003בחולין שנעשו על טהרת הקדש,\u0004 שנזהר בהם שיהיו בטהרה כאילו היו קדשים, \u0003וקסבר\u0004 \u0005[וסבור הוא]\u0006 תנא זה כי \u0003חולין שנעשו על טהרת הקדש כקדש דמו\u0004 \u0005[נחשבים],\u0006 שדנים בהם בהרחקה מן הטומאה כאילו היו ממש קדשים.","ולפיכך, הטמא שרוצה לשחוט בהמת חולין בטהרה \u0003כיצד הוא עושה? מביא סכין ארוכה ושוחט בה,\u0004 \u0003כדי שלא יגע\u0004 הטמא בגופו \u0003בבשר.\u0004","וממשיכים לפי שיטה זו את הסבר המשנה: \u0003ובמוקדשים לא ישחוט\u0004 לכתחילה אף בסכין ארוכה, \u0003שמא יגע בבשר,\u0004 \u0003ו\u0004מכל מקום \u0003אם שחט ואומר \"ברי\u0004 (ברור) \u0003לי שלא נגעתי\"\u0004 — הרי \u0003שחיטתו כשרה\u0004 (והוא מה ששנינו במשנה \"ושחיטתן כשרה\").","וממשיכה המשנה: \u0003חוץ מחרש שוטה וקטן,\u0004 ש\u0003אפילו בחולין גרידי\u0004 \u0005[בלבד],\u0006 שאינם עשויים על טהרת הקודש, \u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא,\u0004 אין שחיטתם כשרה, ומדוע? \u0003שמא ישהו\u0004 ויפסיקו באמצע פעולת השחיטה, ויפסלו אותה, או \u0003שמא ידרסו\u0004 ידחקו את הסכין על הקנה והוושט, וכך ישחטו (ולא על ידי הולכה והבאה), \u0003ו\u0004כן \u0003שמא יחלידו\u0004 יתחבו את הסכין בין הקנה לוושט ויחתכו, שבכל אלה השחיטה פסולה.","ושואלים: אם כן, מה שנאמר מיד אחר כך: \u0003וכולן ששחטו\u0004 ואחרים רואים אותם — שחיטתם כשרה, \u0003אהייא\u0004 \u0005[על מה]\u0006 נאמר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהוא מדבר על \u0003חרש שוטה וקטן,\u0004 מדוע הוא שונה בלשון זו? והרי \u0003עלה קאי\u0004 \u0005[עליה\u0006 על הלכה זו \u0005הוא עומד,\u0006 מתייחס\u0005],\u0006 ששנינו: חוץ מחרש שוטה וקטן — ואם כן \u0003\"ואם שחטו\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אלא\u0004 תאמר כי מה שנאמר \"וכולן\" בא להוסיף על חרש שוטה וקטן גם \u0003טמא\u0004 ששחט \u0003בחולין\u0004 — \u0003הא אמרת\u0004 \u0005[הרי אמרת]\u0006 שטמא בחולין \u0005אפילו\u0006 \u0003לכתחלה נמי שחיט\u0004 \u0005[גם כן שוחט],\u0006 ואינו צריך שאחרים יראו אותו בשחיטתו!","\u0003ואלא\u0004 תאמר שהכוונה היא \u0003ל\u0004\u0003טמא\u0004 ששחט \u0003במוקדשים\u0004 — הלוא \u0003ב\u0004אומר \u0003\"ברי לי\u0004 שלא נגעתי\" \u0003סגי\u0004 \u0005[די\u0006 לו\u0005]\u0006 ואין צריך שיראו אותו! ומשיבים: מדובר כאן בטמא ששחט במוקדשים, אלא \u0003דליתיה קמן דנשייליה\u0004 \u0005[שאינו\u0006 נמצא \u0005לפנינו\u0006 שאפשר יהיה \u0005לשאול אותו]\u0006 אם נגע, ולכן הוצרכה המשנה לומר שאם אחרים ראוהו שוחט כראוי — שחיטתו כשרה.","ושואלים: וכי \u0003האי\u0004 \u0005[\u0006דין \u0005זה]\u0006 לגבי \u0003טמא במוקדשים\u0004 שאם שחט שחיטתו כשרה, \u0003מהכא נפקא\u0004 \u0005[מכאן יוצא,\u0006 נלמד\u0005]?\u0006 מדיוקה של משנתנו? והלוא \u0003מהתם נפקא\u0004 \u0005[משם,\u0006 ממסכת זבחים הוא \u0005יוצא],\u0006 ששנינו במפורש: \u0003כל הפסולין\u0004 לעבודת הקרבנות \u0003ששחטו\u0004 קרבן — \u0003שחיטתן כשרה,\u0004 לפי \u0003שהשחיטה כשרה בזרים\u0004 (שאינם כהנים), \u0003בנשים, ובעבדים, וב\u0004כהנים \u0003טמאים, ואפילו בקדשי קדשים, ובלבד שלא יהיו טמאין נוגעין בבשר!\u0004","ומשיבים: \u0003הכא\u0004 \u0005[כאן]\u0006 הלכה זו שלפנינו היא \u0003עיקר\u0004 הדין. \u0003התם\u0004 \u0005[שם],\u0006 \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 \u0003שאר פסולין\u0004 — \u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003טמא במוקדשים. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 הוא \u0003עיקר\u0004 הדין, שהרי \u0003בקדשים קאי\u0004 \u0005[הוא עומד,\u0006 עוסק\u0005].\u0006 \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 דין של \u0003טמא בחולין\u0004 שנעשו על טהרת הקודש — \u0003תני נמי\u0004 \u0005[שנה גם כן]\u0006 דין \u0003טמא במוקדשים.\u0004","לגופם של הדברים שואלים: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003טמא\u0004 שעוסקים בו במשנה, \u0003דאיטמא במאי\u0004 \u0005[שנטמא במה]?\u0006 \u0003אילימא דאיטמי\u0004 \u0005[אם תאמר שנטמא]\u0006 \u0003במת,\u0004 מה יועיל שישחט בסכין ארוכה? הלוא \"וכל אשר יגע על פני השדה \u0003בחלל חרב\"\u0004 (במדבר יט, טז) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006"],["ללמדנו ש\u0003חרב הרי הוא כחלל,\u0004 כלומר, שכלי מתכת הנוגע במת הריהו מטמא כמת עצמו. וכיוצא בזה, אם נגע הכלי באדם שנטמא במת, שהוא אב הטומאה — הריהו טמא כמוהו. ואם כן, הטמא ש\u0003אב הטומאה הוא,\u0004 כשהוא שוחט בסכין — \u0003לטמייה\u0004 \u0005[שיטמא]\u0006 את ה\u0003סכין, ואזל\u0004 \u0005[ותלך]\u0006 ה\u0003סכין וטמיתיה\u0004 \u0005[ותטמא]\u0006 את ה\u0003בשר!\u0004","\u0003אלא\u0004 צריך לומר שמדובר באדם \u0003דאיטמי\u0004 \u0005[שנטמא]\u0006 \u0003בשרץ,\u0004 שאינו אלא ראשון לטומאה, ואינו מטמא את הכלים. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 מדובר באדם \u0003דאיטמי\u0004 \u0005[שנטמא]\u0006 \u0003ב\u0004טומאת \u0003מת,\u0004 ומכל מקום אין הבשר נטמא. \u0003וכגון שבדק קרומית\u0004 (חתיכת קנה חתוך) \u0003של קנה,\u0004 לוודא שאין בה פגימות, \u0003ושחט בה,\u0004 שכיון שהיא כלי עץ שאין לו בית קיבול — אינה מקבלת טומאה. ומעירים: וניתן לשחוט גם בכלי כזה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003בכל שוחטים: בין בצור\u0004 (אבן), \u0003בין בזכוכית\u0004 ששבריה חדים מאד, \u0003בין בקרומית של קנה.\u0004","\u0003אביי אמר\u0004 תירוץ אחר ליישב את הסתירה בלשון המשנה. \u0003הכי קתני\u0004 \u0005[כך הוא שונה]:\u0006 \u0003הכל שוחטין\u0004 לכתחילה — \u0003ואפילו כותי\u0004 (שומרוני). \u0003במה דברים אמורים? כשישראל עומד על גביו\u0004 ומשגיח שהוא שוחט כראוי, \u0003אבל\u0004 אם ישראל רק \u0003יוצא ונכנס\u0004 ולא נמצא איתו כל הזמן — \u0003לא ישחוט.\u0004","\u0003ואם שחט\u0004 בלא השגחה — \u0003חותך\u0004 הישראל \u0003כזית בשר\u0004 מאותה בהמה \u0003ונותן לו\u0004 לכותי לאכול ממנו, \u0003אם\u0004 \u0003אכלו\u0004 הכותי — \u0003מותר לאכול משחיטתו,\u0004 שלולא היה שוחט כראוי — לא היה אוכל, לפי שגם הכותים נזהרים לאכול דווקא משחיטה כשרה, אבל אם \u0003לא אכלו\u0004 — יש לחשוש כי בהמה זו לא נשחטה כראוי ו\u0003אסור לאכול משחיטתו.\u0004","וממשיכה המשנה: \u0003חוץ מחרש שוטה וקטן\u0004 ש\u0003אפילו\u0004 ב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 התירו לאכול משחיטתם, \u0003שמא ישהו, שמא ידרסו, ושמא יחלידו.\u0004","ושואלים: אם כך אתה מפרש, מה שנאמר מיד אחר כך: \u0003\"וכולן ששחטו\", אהייא\u0004 \u0005[על מה]\u0006 נאמר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 על \u0003חרש שוטה וקטן\u0004 — הלוא \u0003עלה קאי\u0004 \u0005[על דבר הוא עומד,\u0006 מתייחס\u0005],\u0006 ולכן \u0003\"ואם שחטו\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003אלא\u0004 תאמר שהוא מוסיף עליהם גם \u0003כותי\u0004 — \u0003הא אמרת\u0004 \u0005[הרי אמרת]:\u0006 \u0003שכשישראל עומד על גביו שחיט\u0004 \u0005[שוחט]\u0006 הכותי \u0003אפילו לכתחלה!\u0004 ואומרים: אכן, דיוק לשון \"וכולן\" \u0003קשיא\u0004 \u0005[קשה]\u0006 לפירוש זה.","ולגופו של הדין \u0003אמר רבא: ו\u0004כאשר ישראל רק \u0003יוצא ונכנס\u0004 בשעה ששוחט הכותי, האם \u0003לכתחלה לא\u0004 ניתן לסמוך על כך ולהתיר את השחיטה? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003המניח גוי בחנותו\u0004 שיש בה יין, \u0003וישראל יוצא ונכנס\u0004 — \u0003מותר\u0004 היין, שאנו מניחים שאז נזהר הגוי ואינו נוגע בו. והוא הדין לענייננו! ודוחים: \u0003התם מי קתני\u0004 \u0005[שם,\u0006 באותה משנה, \u0005האם הוא שונה]\u0006 \u0003\"מניח\u0004 אדם גוי בחנותו\", שרשאי לעשות כך לכתחילה? הרי \u0003\"המניח\" קתני\u0004 \u0005[הוא שונה],\u0006 לומר שרק ב\u0003דיעבד,\u0004 אם הניח את הגוי שם וישראל יוצא ונכנס — היין מותר, אבל אין ללמוד מכאן שלכתחילה מותר לעשות כן!","\u0003אלא מהכא\u0004 \u0005[מכאן]\u0006 יש להקשות, ששנינו: חביות יין של ישראל הנמצאות ברשות הגוי, והופקד עליהן שומר ישראל — \u0003אין השומר צריך להיות יושב ומשמר\u0004 כל הזמן שלא יגע הגוי ביין, \u0003אלא אף על פי שיוצא ונכנס\u0004 — \u0003מותר.\u0004 משמע שכשישראל יוצא ונכנס מותר אפילו לכתחילה, ולא כדברי אביי!","\u0003אלא אמר רבא,\u0004 כעין תירוצו של אביי למשנה, אך בשינוי, \u0003הכי קתני\u0004 \u0005[\u0006שכך \u0005הוא שונה\u0006 במשנה\u0005]:\u0006 \u0003הכל שוחטין\u0004 לכתחילה — \u0003ואפילו כותי. במה דברים אמורים? כשישראל יוצא ונכנס, אבל\u0004 אם לא היה נכנס ויוצא, אלא \u0003בא ומצאו ששחט\u0004 — \u0003חותך כזית בשר\u0004 מן הבהמה \u0003ונותן לו\u0004 לכותי, אם \u0003אכלו\u0004 הכותי — \u0003מותר לאכול משחיטתו, לא אכלו\u0004 — \u0003אסור לאכול משחיטתו.\u0004","וממשיכה המשנה: \u0003חוץ מחרש שוטה וקטן,\u0004 ש\u0003אפילו\u0004 ב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 סומכים על שחיטתם, מפני שאנו חוששים \u0003שמא ישהו, ושמא ידרסו, ושמא יחלידו.\u0004 ושואלים: לפי זה, מה שנאמר מיד אחר כך \u0003\"וכולן ששחטו\" אהייא\u0004 \u0005[על מה]\u0006 נאמר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 על \u0003חרש שוטה וקטן\u0004 — הלוא \u0003עלה קאי\u0004 \u0005[עליה הוא עומד,\u0006 מתייחס\u0005],\u0006 ולכן \u0003\"ואם שחטו\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003אלא\u0004 תאמר שדברי המשנה הללו מוסיפים עליהם גם \u0003כותי\u0004 — \u0003הא אמרת\u0004 \u0005[הרי אמרת]\u0006 כי \u0003אפילו יוצא ונכנס\u0004 הריהו \u0003שחיט\u0004 \u0005[שוחט]\u0006 \u0003לכתחלה!\u0004 ומעירים: אכן, לפירוש זה \u0003קשיא\u0004 \u0005[קשה]\u0006 לשון \"וכולן\".","\u0003רב אשי אמר\u0004 ביישוב הסתירה שבמשנה, \u0003הכי קתני\u0004 \u0005[\u0006ש\u0005כך הוא שונה]:\u0006 \u0003הכל שוחטין\u0004 לכתחילה — \u0003ואפילו ישראל משומד\u0004 (עובר עבירות באופן קבוע). ומסבירים: ב\u0003משומד למאי\u0004 \u0005[למה],\u0006 באיזה משומד מדובר — במשומד \u0003לאכול נבילות\u0004 (בהמות שלא נשחטו כראוי) \u0003לתיאבון,\u0004 שאינו עושה להכעיס, אלא מטעמי נוחות. \u0003ו\u0004אדם כזה שוחט לכתחילה \u0003כ\u0004שיטת \u0003רבא,\u0004 ש\u0003אמר\u0004 \u0003רבא: ישראל משומד\u0004 ש\u0003אוכל נבילות לתיאבון\u0004 —"],["\u0003בודק\u0004 ישראל כשר \u0003סכין\u0004 לוודא שאין בה פגימות, \u0003ונותן לו,\u0004 והמשומד שוחט, \u0003ומותר לאכול משחיטתו.\u0004 וממשיכה המשנה: \u0003אבל לא בדק ונתן לו\u0004 — \u0003לא ישחוט\u0004 המשומד לכתחילה, \u0003ואם שחט\u0004 — \u0003בודק\u0004 הישראל את \u0003סכינו אחריו,\u0004 אם \u0003נמצאת סכינו יפה\u0004 — \u0003מותר\u0004 לישראל \u0003לאכול משחיטתו\u0004 כיון שאינו עושה בכוונה לקלקל (והוא ששנינו במשנה \"ושחיטתן כשרה\" בדיעבד), \u0003ואם לאו\u0004 \u0005[לא]\u0006 שהסכין פגומה — \u0003אסור לאכול משחיטתו.\u0004","וממשיכה המשנה: \u0003חוץ מחרש שוטה וקטן\u0004 ש\u0003אפילו\u0004 ב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 כשרה שחיטתם, ואפילו נבדקה הסכין, שמא יקלקלו את שחיטתם, \u0003שמא ישהו, שמא ידרסו, ושמא יחלידו.\u0004 ומקשים: לפי זה, מה ששנינו בהמשך: \u0003\"וכולן ששחטו\u0004 ואחרים רואים אותם שחיטתם כשרה\", \u0003אהייא\u0004 \u0005[על מה]\u0006 נאמר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 על \u0003חרש שוטה וקטן\u0004 — הלוא \u0003עלה קאי\u0004 \u0005[עליה הוא עומד,\u0006 מתייחס\u0005],\u0006 ולפי זה \u0003\"ואם שחטו\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003אלא\u0004 תאמר שהוא מתייחס גם ל\u0003ישראל משומד,\u0004 ואולם, \u0003אי\u0004 \u0005[אם]\u0006 מדובר במקרה ש\u0003בדק\u0004 תחילה את ה\u0003סכין ונותן לו, הא\u0004 \u0005[הרי]\u0006 \u0003אמרת\u0004 שבמקרה כזה \u0003שוחט\u0004 המשומד אפילו \u0003לכתחלה! אלא\u0004 תאמר שמדובר כש\u0003לא בדק\u0004 — אין אתה יכול לפרש כן, שהרי \u0003אי דאיתיה לסכין\u0004 \u0005[אם הסכין מצוי]\u0006 לפנינו — \u0003ליבדקיה השתא\u0004 \u0005[שיבדוק אותו עכשיו],\u0006 ואם אינו פגום שחיטתו כשרה אפילו לא ראו אותו אחרים! \u0003ואי דליתיה לסכין\u0004 \u0005[ואם הסכין אינו\u0006 מצוי\u0005]\u0006 לפנינו, גם \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אחרים רואין אותו\u0004 שוחט \u0003מאי הוי\u0004 \u0005[מה בכך]?\u0006 מה יועיל הדבר? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003בסכין פגומה שחיט\u0004 \u0005[שחט]!\u0006 ומעירים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003רבינא אמר\u0004 הסבר אחר לישב את הסתירה בלשון המשנה. \u0003הכי קתני\u0004 \u0005[כך הוא שונה],\u0006 כך צריך להבין את הדברים: \u0003הכל שוחטין\u0004 — \u0003הכל,\u0004 כלומר, כל ה\u0003מומחין\u0004 היודעים הלכות שחיטה \u0003שוחטין\u0004 לכתחילה, והדגש הוא: \u0003מומחין\u0004 — \u0003ואף על פי שאין\u0004 הם \u0003מוחזקין\u0004 אצלינו כמורגלים בשחיטה.","וממשיכה המשנה: \u0003במה דברים אמורים?\u0004 כלומר, מי הוא הקרוי מומחה — אדם \u0003שיודעין בו ש\u0004הוא \u0003יודע לומר הלכות שחיטה, אבל\u0004 אדם ש\u0003אין יודעין בו שיודע לומר הלכות שחיטה\u0004 — \u0003לא ישחוט, ואם שחט\u0004 — \u0003בודקין אותו, אם\u0004 מתברר ש\u0003יודע לומר הלכות שחיטה\u0004 — \u0003מותר לאכול משחיטתו\u0004 (והוא מה ששנינו \"ושחיטתן כשרה\" בדיעבד), \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אסור לאכול משחיטתו.\u0004","\u0003חוץ מחרש שוטה וקטן,\u0004 ש\u0003אפילו\u0004 ב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 אוכלים משחיטתם, אפילו יודעים הלכות שחיטה, \u0003שמא ישהו, שמא ידרסו, ושמא יחלידו\u0004 בשחיטתם. ומקשים: לשיטה זו, מה ששנינו במשנה: \u0003\"וכולן ששחטו\u0004 ואחרים רואים אותם שחיטתם כשרה\", \u0003אהייא\u0004 \u0005[על מה]\u0006 הוא מתייחס? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 על \u0003חרש שוטה וקטן\u0004 — הלוא \u0003עלה קאי\u0004 \u0005[עליה הוא עומד,\u0006 מתייחס\u0005],\u0006 ולפי זה \u0003\"ואם שחטו\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003אלא\u0004 תאמר שהוא מוסיף גם אנשים \u0003שאין מומחין,\u0004 שאין אנו יודעים אם הם יודעים הלכות שחיטה, והרי במקרה זה אין צורך שאחרים יראו אותם כדי להכשיר את השחיטה, אלא \u0003בבודקין אותו\u0004 אם הוא יודע הלכות שחיטה \u0003סגי\u0004 \u0005[די]!\u0006 ומשיבים: מדובר במקרה \u0003דליתיה לקמן דליבדקיה\u0004 \u0005[שאינו\u0006 מצוי \u0005לפנינו שיבדקו אותו],\u0006 ולפיכך אנו צריכים להסתמך על כך שאחרים ראו אותו, ורק באופן זה שחיטתו כשרה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 את דברי רבינא בגירסה אחרת: \u0003רבינא אמר, הכי קתני\u0004 \u0005[כך הוא שונה]:\u0006 \u0003הכל שוחטין\u0004 — \u0003הכל,\u0004 כלומר, כל ה\u0003מוחזקין\u0004 שיש להם נסיון בשחיטה, \u0003שוחטין\u0004 לכתחילה, והכוונה: \u0003מוחזקין אף על פי שאין מומחין,\u0004 שאין אנו יודעים אם הם יודעים הלכות שחיטה. וממשיכה המשנה: \u0003במה דברים אמורים?\u0004 מי הם המוחזקים? אלו \u0003ששחטו לפנינו שתים ושלש פעמים ולא נתעלף\u0004 מחמת השחיטה והדם, \u0003אבל לא שחט לפנינו שתים ושלש פעמים\u0004 — \u0003לא ישחוט\u0004 לכתחילה, \u0003שמא יתעלף, ו\u0004מכל מקום \u0003אם שחט ואמר: \"ברי\u0004 (ברור) \u0003לי שלא נתעלפתי\u0004 בתוך השחיטה\" — \u0003שחיטתו כשרה.\u0004","\u0003חוץ מחרש שוטה\u0004 \u0003וקטן,\u0004 ש\u0003אפילו\u0004 ב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 כשרה שחיטתם, ואפילו ברור שלא נתעלפו, \u0003שמא\u0004 \u0003ישהו, שמא ידרסו, ושמא יחלידו.\u0004 ומקשים: לפי פירוש זה, מה ששנינו בהמשך: \u0003\"וכולן ששחטו\" אהייא\u0004 \u0005[על מה]\u0006 הוא מתייחס? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 על \u0003חרש שוטה וקטן\u0004 — הלוא \u0003עלה קאי\u0004 \u0005[עליה הוא עומד,\u0006 מתייחס\u0005],\u0006 ולפי זה \u0003\"ואם שחטו\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003אלא\u0004 תאמר שמדובר כאן על אלה \u0003שאין מוחזקין\u0004 — \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 כי \u0003ב\"ברי לי\" סגי\u0004 \u0005[די],\u0006 שאם אמר השוחט שברור לו שלא התעלף די בכך, גם אם אחרים לא ראו אותו! ומשיבים: מדובר כאן במקרה \u0003דליתיה קמן דלישייליה\u0004 \u0005[שאינו\u0006 מצוי \u0005לפנינו לשאול אותו],\u0006 ולכן אנו צריכים להסתמך על כך שאחרים ראו אותו.","כיון שנאמרו כמה וכמה שיטות פירוש למשנה, מסבירים מדוע לא פירש כל אחד מן החכמים כשיטת האחר. \u0003רבינא ורבה בר עולא, כ\u0004דעת \u0003אביי ורבא\u0004 שפירשוה בכותי \u0003ו\u0004כדעת \u0003רב אשי\u0004 שפירשה במשומד \u0003לא אמרי\u0004 \u0005[אינם אומרים],\u0006 \u0003משום דקשיא להו\u0004 \u0005[שקשה להם]\u0006 מה ששנינו: \u0003\"וכולן\u0004 ששחטו ואחרים רואים אותן\", שלשיטתם אין \"וכולן\" מתיישב כראוי, כפי שהראתה הגמרא לעיל.","\u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003כ\u0004דברי \u0003רבה בר עולא לא אמרי\u0004 \u0005[אינם אומרים],\u0006 שהוא מפרש את \"שחיטתן כשרה\" של משנתנו בטמא ששחט קדשים, מפני שכבר שנינו דין זה במסכת זבחים. כי \u0003להך לישנא דאמרת\u0004 \u0005[לפי אותה לשון\u0006 \u0005שאמרת]\u0006 בתירוץ הדברים: \u0003הכא\u0004 \u0005[כאן,\u0006 במשנה זו\u0005]\u0006 \u0003עיקר\u0004 הדין, ובמסכת זבחים נשנה אגב שאר פסולים — אפשר לטעון: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003התם\u0004 \u0005[שם]\u0006 במסכת זבחים \u0003עיקר\u0004 מקומו, שהרי \u0003בקדשים קאי\u0004 \u0005[הוא עומד,\u0006 עוסק\u0005].\u0006","וכן \u0003להך לישנא דאמרת\u0004 \u0005[לאותה לשון שאמרת]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בזבחים \u0003עיקר\u0004 הדין, \u0003והכא איידי דתנא\u0004 \u0005[וכאן מתוך ששנה]\u0006 מתחילה דין \u0003טמא\u0004 ששחט \u0003בחולין\u0004 שנעשו על טהרת הקודש, כפי שפירש רבה בר עולא לשון \"הכל שוחטין\" של משנתנו — \u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 דין \u0003טמא במוקדשין,\u0004 שהוא כשר בדיעבד — על כך יש להשיב: \u0003טמא בחולין גופיה\u0004 \u0005[עצמו]\u0006 \u0003לא איצטריכא ליה\u0004 \u0005[לא הוצרכה לו]\u0006 לומר ששוחט לכתחילה, כי אנו סבורים ש\u0003חולין שנעשו על טהרת קדש לאו\u0004 \u0005[לא]\u0006 \u0003כקדש דמו\u0004 \u0005[נחשבים],\u0006 ולא היה מקום לאסור את הדבר.","\u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003כרבינא לא אמרי\u0004 \u0005[אומרים],\u0006 \u0003להך לישנא דאמר\u0004 \u0005[לאותה לשון שאמר]\u0006 שאלו שיודעים אנו שהם \u0003מומחין אין\u0004 \u0005[כן]\u0006 שוחטים לכתחילה, אבל \u0003שאין\u0004 אנו יודעים שהם \u0003מומחין\u0004 — \u0003לא,\u0004 יש לומר כי \u0003רוב\u0004 ה\u0003מצויין אצל שחיטה מומחין הן,\u0004 ולכן כל הבא לשחוט — שוחט לכתחילה.","\u0003להך לישנא דאמר\u0004 \u0005[לאותה לשון שאמר]:\u0006 כל ה\u0003מוחזקין\u0004 שאינם מתעלפים בשחיטה — \u0003אין\u0004 \u0005[כן],\u0006 שוחטים לכתחילה, \u0003שאין מוחזקין\u0004 — \u0003לא,\u0004 למרות שהם יודעים הלכות שחיטה, צריך לומר כי \u0003לעלופי לא חיישינן\u0004 \u0005[לעילפון אין אנו חוששים],\u0006 וכל היודע הלכות שחיטה שוחט לכתחילה.","\u0003רבא לא אמר כ\u0004דברי \u0003אביי,\u0004 שכותי שוחט לכתחילה רק כשישראל עומד על גביו, ובדיעבד די בישראל יוצא ונכנס, \u0003כי קושייה\u0004 \u0005[כמו קושייתו]\u0006 שהקשה על אביי, מדין יינו של ישראל המצוי ברשותו של הגוי, שהוא כשר לכתחילה כשישראל יוצא ונכנס. \u0003אביי לא אמר כרבא,\u0004 מפני שלדעתו אין זו ראיה, שכן \u0003התם\u0004 \u0005[שם]\u0006 ביין הרי \u0003לא נגע\u0004 \u0005[אין\u0006 הגוי \u0005נוגע]\u0006 ביין, ודי בשומר שיוצא ונכנס כדי להרתיע אותו מלגעת בו, ואילו \u0003הכא נגע\u0004 \u0005[כאן\u0006 בשחיטה, הכותי \u0005נוגע]\u0006 שוחט בידיו את הבהמה, וכהרף עין יכול לפסול את השחיטה, ולכן יש צורך בהשגחה מתמדת.","\u0003רב אשי לא אמר כתרוייהו\u0004 \u0005[כשניהם]\u0006 כאביי ורבא, ששחיטת כותי כשרה, שכן \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003כותים גרי אריות הן\u0004 ולא גרי אמת, ושחיטתם פסולה כשחיטת הגוי.","\u0003אביי לא אמר כרב אשי,\u0004 שפירש את המשנה בישראל משומד לאכול נבלות לתיאבון, מפני ש\u0003לא סבירא ליה הא\u0004 \u0005[אין הוא סבור\u0006 כהלכה \u0005זו]\u0006 שאמר \u0003רבא,\u0004 שנותנים לישראל משומד לשחוט לכתחילה בסכין בדוקה, ועל פיה פירש רב אשי את המשנה. \u0003אלא רבא\u0004 עצמו \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 ופירש את המשנה \u0003כשמעתיה\u0004 \u0005[כשמועתו]\u0006 שלו, כדברי רב אשי? ומדוע פירש שמדובר בשחיטת כותי?","ומשיבים: מה שפירש רבא — \u0003לדבריו\u0004 של \u0003אביי קאמר\u0004 \u0005[אמר],\u0006 שלפירושו של אביי שמשנתנו עוסקת בכותי, צריך לפרש את המשנה באופן שונה, \u0003וליה לא סבירא ליה\u0004 \u0005[ו\u0006אולם \u0005הוא עצמו אינו סבור כן].\u0006","ובענין שנחלקו בו אביי ורבא מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שחיטת כותי מותרת, במה דברים אמורים? כשישראל עומד על גביו\u0004 ורואה ששוחט כראוי. \u0003אבל\u0004 אם \u0003בא\u0004 הישראל, \u0003ומצאו ש\u0004כבר \u0003שחט\u0004 בהמה — \u0003חותך כזית\u0004 מן הבהמה \u0003ונותן לו\u0004 לאכול, אם \u0003אכלו\u0004 הכותי — ישראל \u0003מותר לאכול משחיטתו, ואם לאו\u0004 \u0005[לא]\u0006 אכלו — \u0003אסור לאכול משחיטתו,\u0004 שמא לא שחט כראוי.","\u0003כיוצא בו,\u0004 אם \u0003מצא בידו\u0004 של כותי"],["\u0003דקוריא\u0004 \u0005[מחרוזת]\u0006 \u0003של צפרים,\u0004 ואינו יודע אם נשחטו כדין או לא — \u0003קוטע ראשו של אחד מהן ונותן לו\u0004 לכותי לאוכלו, אם \u0003אכלו\u0004 הכותי — \u0003מותר לאכול משחיטתו, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אסור לאכול משחיטתו.\u0004","ואומרים: גם אביי וגם רבא דייקו מברייתא זו כשפירשו את משנתנו, אלא ש\u0003אביי דייק מרישא\u0004 \u0005[מראשה],\u0006 ואילו \u0003רבא דייק מסיפא\u0004 \u0005[מסופה].\u0006 ומפרטים, \u0003אביי דייק מרישא\u0004 \u0005[מראשה],\u0006 ששנינו: שחיטת כותי מותרת כשישראל עומד על גביו ורואה ששוחט כראוי, וכך דייק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 להיתר הוא רק משום ש\u0003ישראל עומד על גביו, אבל\u0004 אם היה ישראל רק \u0003יוצא ונכנס\u0004 — \u0003לא,\u0004 אין די בכך.","\u0003רבא דייק מסיפא\u0004 \u0005[מסופה],\u0006 ששנינו: אבל בא ומצאו ששחט חותך כזית ונותן לו, וכך דייק: \u0003טעמא\u0004 \u0005[טעם\u0006 הדבר\u0005]\u0006 שהוצרך לבודקו הוא משום ש\u0003בא ומצאו ששחט,\u0004 ולא היה שם, \u0003אבל יוצא ונכנס\u0004 — \u0003שפיר דמי\u0004 \u0005[טוב הדבר],\u0006 מותר לכתחילה.","ושואלים: \u0003ולאביי קשיא סיפא\u0004 \u0005[קשה סוף\u0006 הברייתא\u0005]!\u0006 ומשיבים, \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 כי \u0003יוצא ונכנס נמי\u0004 \u0005[גם כן]\u0006 \u0003\"בא ומצאו\" קרי ליה\u0004 \u0005[קורא לו]\u0006 התנא, ולכך כוונת הברייתא. ומן הצד האחר שואלים: \u0003ולרבא קשיא רישא\u0004 \u0005[קשה תחילת\u0006 הברייתא\u0005]!\u0006 ומשיבים, \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 רבא: \u0003יוצא ונכנס נמי\u0004 \u0005[גם כן]\u0006 \u0003כעומד על גביו דמי\u0004 \u0005[נחשב].\u0006","ודנים בהמשך הברייתא, ששנינו: \u0003כיוצא בו, מצא בידו דקוריא של צפרין, קוטע ראשו\u0004 של אחד מהן ונותן לו, אכלו — מותר לאכול משחיטתו, לא אכלו — אסור לאכול משחיטתו. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 אפשר לסמוך על כך? \u0003ליחוש דלמא האי הוא דהוה שחיט שפיר\u0004 \u0005[שנחשוש שמא זו,\u0006 אותה ציפור שקטע את ראשה ונתן לו, \u0005היא זו ששחט\u0006 הכותי \u0005כראוי],\u0006 וכל השאר לא נשחטו כראוי!","\u0003אמר רב מנשה:\u0004 מדובר \u0003במכניסן תחת כנפיו,\u0004 שמחביא הישראל את מחרוזת הציפורים מתחת לבגדו, ומושיט לו ראש של אחת מהן, כך שאינו יודע איזו היא, ואם אכל אחת מהן — סימן הוא על כל השאר. ושואלים:","\u0003ודלמא סימנא הוה יהיב ליה בגויה\u0004 \u0005[ושמא סימן היה נתון לו ב\u0006ציפור \u0005זו]\u0006 שיודע שדווקא זו היא הכשרה! \u0003אמר רב משרשיא:\u0004 מדובר \u0003דממסמס ליה מסמוסי\u0004 \u0005[שממעך אותו],\u0006 כך שאין הכותי יכול להכיר ראש של איזה ציפור היה זה.","\u0003ודלמא קסברי\u0004 \u0005[ושמא סבורים]\u0006 ה\u0003כותים\u0004 \u0003ש\u0004\u0003אין\u0004 כלל דין \u0003שחיטה לעוף מן התורה,\u0004 ולכן יכול להיות שיאכל הכותי מן העוף למרות שאינו שחוט כראוי, מפני שסבור שאין צורך לשחוט כלל! ודוחים:","\u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 אם אתה חושש לכך, הלכות \u0003שהייה, דרסה, חלדה, הגרמה, ועיקור,\u0004 שכל אחד מהם פוסל את השחיטה בבהמה, \u0003מי כתיבן\u0004 \u0005[האם כתובות הן\u0006 בתורה\u0005]?\u0006","\u0003אלא כיון דאחזיקו בהו אחזיקו בהו\u0004 \u0005[שהחזיקו בהן\u0006 הכותים \u0005החזיקו בהם],\u0006 ואנו סומכים על כך, שהרי שחיטתו מותרת כשהוא עצמו אוכל ממנה — \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין שחיטת עוף, \u0003כיון דאחזיקו אחזיקו\u0004 \u0005[שהחזיקו\u0006 במצות שחיטה כפי שאנו עושים, \u0005החזיקו].\u0006","\u0003ו\u0004מעירים: השאלה האם \u0003אחזוק ולא אחזוק בדלא כתיבא\u0004 \u0005[הוחזקו או לא הוחזקו\u0006 לגבינו \u0005ב\u0006דברים \u0005שאינם כתובים\u0006 בתורה במפורש\u0005]\u0006 והם מחזיקים בהם, \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מצת כותי מותרת\u0004 בפסח באכילה, \u0003ואדם\u0004 גם \u0003יוצא בה ידי חובתו בפסח\u0004 בלילה הראשון שיש חובה באכילת מצה.","\u0003ר' אלעזר אוסר\u0004 אותה, \u0003לפי\u0004 שהוא סבור \u0003שאין\u0004 הכותים \u0003בקיאין בדקדוקי מצות כישראל,\u0004 ואינם יודעים בדיוק מהו חמץ שאסרה התורה.","\u0003רבן שמעון בן גמליאל אומר: כל מצוה שהחזיקו בה כותים, הרבה מדקדקין בה יותר מישראל,\u0004 ולכן אפשר לסמוך עליהם שעשו את הכל כראוי. ותחילה מבארים את הברייתא.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מצת כותי מותרת, ואדם יוצא בה ידי חובתו ב\u0004ליל \u0003פסח.\u0004 ותמהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 שאם המצה מותרת יוצא בה ידי חובה בפסח! ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003לא בקיאי\u0004 \u0005[אין\u0006 הכותים \u0005בקיאים]\u0006 \u0003ב\u0004מצות \u0003שימור\u0004 המצה לשם מצוה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהם בקיאים. נאמר שם ש\u0003ר' אלעזר אוסר\u0004 מצת כותי באכילה, \u0003לפי שאין בקיאין בדקדוקי מצות.\u0004 ומבארים, \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003לא בקיאי\u0004 \u0005[אין\u0006 הם \u0005בקיאים]\u0006 \u0003בשימור\u0004 המצה שלא תחמיץ.","ועוד שנינו, \u0003רבן שמעון בן גמליאל אומר: כל מצוה שהחזיקו בה כותים, הרבה מדקדקין בה יותר מישראל.\u0004 ויש לשאול: לכאורה \u0003היינו תנא קמא\u0004 \u0005[זוהי\u0006 דעת \u0005התנא הראשון],\u0006 הסבור שמצת כותי מותרת ויוצאים בה ידי חובה, ומה בא לחדש? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לגבי מצוה \u0003דכתיבא ולא אחזיקו\u0004 \u0005[שכתובה\u0006 בתורה \u0005ולא\u0006 ידוע לנו ש\u0005החזיקו]\u0006 \u0003בה\u0004 הכותים, \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003כיון דכתיבא\u0004 \u0005[שכתובה\u0006 בתורה\u0005],\u0006 \u0003אף על גב דלא אחזיקו\u0004 \u0005[אף על פי שאין\u0006 אנו יודעים \u0005שהחזיקו]\u0006 \u0003בה\u0004 — אפשר לסמוך עליהם שעשאוה כראוי. \u0003ורבן שמעון בן גמליאל סבר: אי אחזוק\u0004 \u0005[אם החזיקו בה]\u0006 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אי לא אחזוק\u0004 \u0005[אם לא החזיקו בה]\u0006 אף שהיא כתובה בתורה — \u0003לא.\u0004","ומקשים על פירוש זה: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 לשונו של רבן שמעון בן גמליאל \u0003\"כל מצוה שהחזיקו בה כותים\"\u0004 אינה הלשון הראויה, שהרי הוא בא למעט ממה שאמר התנא הראשון, ואם כן \u0003\"אם החזיקו\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003אלא\u0004 יש לפרש כך, \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 בין תנא קמא ורבן שמעון בן גמליאל הבדל לגבי מצוה \u0003דלא כתיבא ואחזיקו בה\u0004 \u0005[שאינה כתובה\u0006 בתורה \u0005והחזיקו בה],\u0006 וכגון הדברים הפוסלים את השחיטה, \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003כיון דלא כתיבא\u0004 \u0005[שאינה כתובה],\u0006 \u0003אף על גב דאחזיקו בה\u0004 \u0003נמי\u0004 \u0005[אף על פי שהחזיקו בה גם כן]\u0006 \u0003לא\u0004 ניתן לסמוך עליהם. ואילו \u0003רבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]:\u0006 \u0003כיון דאחזוק אחזוק\u0004 \u0005[שהוחזקו הוחזקו].\u0006","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהוזכרה קודם, \u0003אמר רבא: ישראל משומד,\u0004 רגיל להיות \u0003אוכל נבילות\u0004 (בהמות שלא נשחטו כראוי) \u0003לתיאבון\u0004 מתוך תאוות אכילה, ולא להכעיס — \u0003בודק\u0004 אדם \u0003סכין\u0004 לראות שאין בה פגימה הפוסלת את השחיטה, \u0003ונותן לו,\u0004 והמשומד שוחט בינו לבין עצמו, \u0003ומותר לאכול משחיטתו.\u0004","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 סומכים עליו? \u0003כיון\u0004 שאדם כזה, במקרה \u0003דאיכא התירא ואיסורא\u0004 \u0005[שיש היתר ואיסור\u0006 לפניו\u0005],\u0006 \u0003לא שביק התירא ואכיל איסורא\u0004 \u0005[אינו מניח היתר ואוכל איסור]\u0006 בכוונה. ובמקרה זה, שיש בידו סכין בדוקה, ואנו מניחים כי כל המצוי אצל שחיטה יודע לשחוט כראוי — אין חוששים שמא קלקל בכוונה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אנו מניחים, \u0003כי לא בדק נמי\u0004 \u0005[כאשר אין\u0006 הישראל הכשר \u0005בודק\u0006 את הסכין \u0005גם כן]\u0006 יהיה מותר לאכול משחיטתו, שמן הסתם בדק את הסכין! ומשיבים: אם ימצא המשומד שהסכין שבידו אינה כשרה, \u0003מיטרח לא טרח\u0004 \u0005[לא יטרח]\u0006 להביא סכין כשרה.","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא, תניא דמסייע לך\u0004 \u0005[שנויה\u0006 ברייתא \u0005שמסייעת לך],\u0006 ששנינו: \u0003חמצן של עוברי עבירה\u0004 שאין מבערים את החמץ לפני הפסח, \u0003אחר הפסח\u0004"],["\u0003מותר מיד, מפני שהן מחליפין\u0004 מיד לאחר הפסח את החמץ שהיה בידיהם, שהוא אסור בהנאה, בחמץ של גוים, ולכן מותר לאכול משלהם.","ומסבירים: \u0003סברוה\u0004 \u0005[סברו]\u0006 החכמים שהביאו ראיה זו, \u0003כי\u0004 \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר: חמץ\u0004 של ישראל \u0003אחר הפסח,\u0004 אם לא ביערוהו בתוך החג, אסור \u0003דאורייתא\u0004 \u0005[מן התורה];\u0006 \u0003וקתני\u0004 \u0005[והוא שונה\u0006 שם\u0005]:\u0006 \u0003מפני שהן מחליפין, אלמא\u0004 \u0005[מכאן]\u0006 שאפילו מי שחשוד על עבירה \u0003לא שביק התירא ואכיל איסורא\u0004 \u0005[אינו מניח היתר ואוכל איסור]\u0006 אם אין בכך טירחה, וכדברי רבא.","ודוחים: \u0003ממאי\u0004 \u0005[ממה,\u0006 כיצד\u0005]\u0006 אתה מוכיח? \u0003דלמא\u0004 \u0005[שמא]\u0006 ברייתא זו כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: חמץ אחר הפסח\u0004 אסור רק \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003וכי מקילינן\u0004 \u0005[וכאשר אנו מקילים]\u0006 לסמוך שעובר עבירה אינו מניח היתר ואוכל איסור, הרי זה \u0003בדרבנן\u0004 \u0005[ב\u0006איסור שמ \u0005דברי סופרים],\u0006 אבל \u0003בדאורייתא\u0004 \u0005[ב\u0006איסור ש\u0005מדברי תורה],\u0006 כגון אכילת נבילה (בהמה שלא נשחטה כראוי) — \u0003לא מקילינן\u0004 \u0005[אין אנו מקילים]\u0006 לסמוך על הנחה זו!","ומשיבים: \u0003ותיהוי נמי\u0004 \u0005[ושתהיה גם כן]\u0006 ברייתא זו כשיטת \u0003ר' שמעון, מי קתני\u0004 \u0005[האם\u0006 התנא \u0005שונה]:\u0006 \u0003\"שאני אומר החליפו\",\u0004 בדרך השערה? והלוא בלשון \u0003\"מפני שמחליפין\" קתני\u0004 \u0005[הוא שונה],\u0006 כלומר, \u0003ודאי מחליפין\u0004 בחמץ מותר, \u0003ו\u0004לכן אפשר ללמוד מכאן: \u0003מה ב\u0004דבר שהוא רק איסור \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 אנו מניחים כי העבריין \u0003לא שביק התירא ואכיל איסורא\u0004 \u0005[אינו מניח היתר ואוכל איסור],\u0006 \u0003בדאורייתא\u0004 \u0005[ב\u0006דבר האסור מדברי \u0005תורה],\u0006 כגון שחיטה, \u0003לא כל שכן\u0004 שאינו מניח היתר ועושה באיסור?","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר שמסייע לו]\u0006 לרבא מה ששנינו: \u0003הכל שוחטין, ואפילו כותי ואפילו ערל ואפילו ישראל משומד.\u0004 ויש לשאול: \u0003האי ערל היכי דמי\u0004 \u0005[ערל זה כיצד הוא בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שאינו נימול משום ש\u0003מתו אחיו מחמת מילה,\u0004 ויש חשש סכנה שיימול, מדוע הוצרך לומר שהוא שוחט? והרי \u0003האי ישראל מעליא הוא\u0004 \u0005[ישראל מעולה,\u0006 כשר \u0005הוא זה]!\u0006 \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כאן במי ש\u0003משומד לערלות,\u0004 שאינו רוצה להימול, \u0003וקא סבר\u0004 \u0005[וסבור הוא]\u0006 איפוא התנא: \u0003משומד לדבר אחד לא הוי\u0004 \u0005[אינו\u0006 נחשב\u0005]\u0006 ל\u0003משומד לכל התורה כולה,\u0004 ושחיטתו כשרה.","אם כן, \u0003אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של הברייתא\u0005]:\u0006 \u0003ואפילו ישראל משומד,\u0004 ונברר: \u0003האי משומד היכי דמי\u0004 \u0005[משומד זה כיצד הוא בדיוק]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 הוא \u0003משומד לדבר אחר,\u0004 שלא לענין שחיטה — \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003משומד לערלות\u0004 ששנה בתחילת הברייתא, ומה הוסיף על ידי כך? \u0003אלא לאו\u0004 \u0005[האם אין]\u0006 הכוונה למי שהיה \u0003משומד לאותו דבר,\u0004 כלומר, לשחיטה, שהוא אוכל נבלות לתיאבון, \u0003ו\u0004הרי זו הוכחה \u0003כ\u0004דברי \u0003רבא,\u0004 שלמרות שהוא משומד לענין אכילת נבילות, הריהו שוחט לכתחילה (כשנותנים לו סכין בדוקה)!","ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003משומד לאותו דבר לא\u0004 סומכים עליו, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כיון דדש ביה\u0004 \u0005[שדש בו,\u0006 שהתרגל בעבירה זו\u0005]\u0006 \u0003כהתירא דמי ליה\u0004 \u0005[כהיתר\u0006 היא \u0005נחשבת לו],\u0006 ויש לחשוש שאינו מקפיד כלל לשחוט כראוי. \u0003אלא\u0004 משומד שהוזכר כאן הוא \u0003משומד לעבודה זרה, וכ\u0004דברי \u0003רב ענן,\u0004 ש\u0003אמר רב ענן אמר שמואל: ישראל משומד לעבודה זרה\u0004 — \u0003מותר לאכול משחיטתו.\u0004","\u0003גופא\u0004 \u0005[לגופה]\u0006 של מימרה זו, \u0003אמר רב ענן, אמר שמואל: ישראל משומד לעבודה זרה\u0004 — \u0003מותר לאכול משחיטתו,\u0004 וראיה לדבר, \u0003שכן מצינו ביהושפט מלך יהודה שנהנה מסעודת אחאב,\u0004 כלומר, ממה ששחט עבורו אחאב, שהיה משומד לעבודה זרה, \u0003שנאמר: \"ויזבח לו אחאב צאן ובקר לרוב ולעם אשר עמו ויסיתהו לעלות אל רמות גלעד\"\u0004 (דברי הימים ב יח, ב).","ושואלים: \u0003ודלמא מיזבח זבח\u0004 \u0005[ושמא\u0006 אחאב \u0005שחט\u0006 לו\u0005],\u0006 אבל יהושפט עצמו \u0003מיכל\u0004 \u0005[לאכול]\u0006 \u0003לא אכל\u0004 מן הבשר הזה! ומשיבים: \u0003\"ויסיתהו\" כתיב\u0004 \u0005[נאמר\u0006 שם\u0005],\u0006 משמע שהיה צד של פיתוי בדבר, שהאכילו. ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 היתה זו הסתה \u0003בדברים\u0004 (בדיבור) בלבד! ודוחים: \u0003אין\u0004 לשון \u0003הסתה\u0004 שבמקרא \u0003בדברים\u0004 בלבד, אלא תמיד יש בה פיתוי חומרי כלשהו.","ותוהים: \u0003ולא?\u0004 וכי אין \u0003הסתה בדברים?\u0004 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"כי יסיתך אחיך...\u0004 נלכה ונעבדה אלהים אחרים\" (דברים יג, ז)! ומשיבים: גם שם צריך לפרש שמסיתו \u0003באכילה ובשתיה.\u0004 ומקשים, \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 שאמר הקדוש ברוך הוא לשטן שקיטרג על איוב: \u0003\"ותסיתני בו לבלעו חנם\"\u0004 (איוב ב, ג), ובוודאי אצל הקדוש ברוך הוא אי אפשר לדבר על אכילה ושתיה! ומשיבים: \u0003למעלה שאני\u0004 \u0005[שונה],\u0006 שכלפי הקדוש ברוך הוא ודאי אין מקום לדבר על אכילה, ושם הוא בדרך השאלה, אבל ביחס לבני אדם מדובר בפיתוי חומרי.","ומקשים עוד: \u0003ודלמא משתא אשתי\u0004 \u0005[ושמא לשתות\u0006 יין \u0005שתה\u0006 עימו\u0005]\u0006 יהושפט עם אחאב, אבל \u0003מיכל\u0004 \u0005[לאכול]\u0006 \u0003לא אכל!\u0004 ודוחים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003שתיה\u0004 שאתה מניח שהיה יכול לשתות איתו יין — מפני \u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003משומד לעבודה זרה לא הוי\u0004 \u0005[אינו\u0006 נחשב\u0005]\u0006 ל\u0003משומד לכל התורה כולה,\u0004 שדינו כגוי גמור, ויינו אסור. אם כן לגבי \u0003אכילה\u0004 (כלומר, לענין שחיטה) \u0003נמי\u0004 \u0005[גם כן]\u0006 נאמר כי \u0003משומד לעבודה זרה לא הוי\u0004 \u0005[אינו]\u0006 \u0003משומד לכל התורה כולה,\u0004 ששחיטתו פסולה כשחיטת גוי, אלא היה יכול לסמוך על שחיטתו.","ומקשים על כך: \u0003הכי השתא\u0004 \u0005[כך אתה משווה את הדברים]?\u0006 לגבי \u0003שתיה,\u0004 הרי יין זה כ\u0003סתם יינן\u0004 של גוים \u0003הוא,\u0004 \u0003ועדיין לא נאסר יינן של גוים\u0004 באותם הדורות, אלא רק לאחר דורות רבים. \u0003אבל\u0004 לגבי \u0003אכילה\u0004 — \u0003אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003משומד לעבודה זרה הוי\u0004 \u0005[הרי הוא]\u0006 \u0003משומד לכל התורה כולה,\u0004 ואסור לאכול משחיטתו. ואם כן, ייתכן שיהושפט שתה משל אחאב, ולא אכל משחיטתו!","ומשיבים, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחד: \u0003לאו אורחיה דמלכא משתיא בלא מיכלא\u0004 \u0005[אין דרכו של מלך לשתות\u0006 יין \u0005בלא לאכול].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003\"ויזבח... ויסיתהו\" כתיב\u0004 \u0005[נאמר],\u0006 כלומר, \u0003במה הסיתו\u0004 — \u0003בזביחה\u0004 (בשחיטה).","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003עובדיה\u0004 שהיה ממונה על בית אחאב \u0003זבח\u0004 \u0005[שחט],\u0006 ועובדיה היה איש כשר (ראה שם יח, ג), ואפשר היה לסמוך על שחיטתו! ומשיבים: \"ויזבח צאן ובקר \u0003לרוב\" כתיב\u0004 \u0005[נאמר],\u0006 ו\u0003עובדיה לא הוה ספיק\u0004 \u0005[לא היה מספיק]\u0006 לבדו לשחוט עבור כולם.","ומקשים עוד: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 מאותם \u0003שבעת אלפים\u0004 אנשים כשרים שהוזכרו בכתוב \u0003זבוח\u0004 \u0005[שחטו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והשארתי בישראל שבעת אלפים כל הברכים אשר לא כרעו לבעל\" וגו'\u0004 (מלכים א יט, יח)! ומשיבים: האנשים הללו \u0003טמורי הוו מיטמרי\u0004 \u0005[מתחבאים היו]\u0006 \u0003מ\u0004פני אימתה של \u0003איזבל,\u0004 ובוודאי לא היו שם כדי לשחוט.","ושואלים בדרך אחרת: \u0003ודלמא גברי\u0004 \u0005[ושמא אנשיו]\u0006 של \u0003אחאב הוו מעלו\u0004 \u0005[היו מעולים\u0006 וכשרים\u0005],\u0006 שאמנם אחאב עצמו עבד עבודה זרה, אבל האנשים שאיתו לא עשו כן, ומשחיטתם אכל יהושפט! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מושל מקשיב על דבר שקר\u0004 — \u0003כל משרתיו רשעים\"\u0004 (משלי כט, יב).","ושואלים מצד אחר: \u0003ודלמא גברי\u0004 \u0005[ושמא אנשיו]\u0006 של \u0003יהושפט נמי לא הוו מעלו\u0004 \u0005[גם כן לא היו מעולים],\u0006 שגם הם היו רשעים, ולכן \u0003זבוח גברי\u0004 \u0005[\u0006ממה ש\u0005שחטו אנשיו]\u0006 של \u0003אחאב אכול גברי\u0004 \u0005[אכלו אנשיו]\u0006 של \u0003יהושפט, זבוח\u0004 \u0005[\u0006וממה ש\u0005שחט]\u0006 \u0003עובדיה אכל יהושפט\u0004 עצמו!","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 שאנשיו של יהושפט היו רשעים, שכן \u0003מ\u0004מה שנאמר \u0003\"מושל מקשיב על דבר שקר כל משרתיו רשעים\",\u0004 אנו יכולים ללמוד לצד השני: \u0003הא\u0004 \u0005[הרי]\u0006 אם מושל מקשיב \u0003לדבר אמת\u0004 — \u0003משרתיו צדיקים.\u0004","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 כך עשו, \u0003זבוח גברי\u0004 \u0005[\u0006ממה ש\u0005שחטו אנשיו]\u0006 של \u0003אחאב\u0004 — \u0003אכל\u0004 \u0003אחאב וגבריה\u0004 \u0005[ואנשיו],\u0006 \u0003זבוח גברי\u0004 \u0005[\u0006ממה ש\u0005שחטו אנשיו]\u0006 של \u0003יהושפט אכל יהושפט וגבריה\u0004 \u0005[ואנשיו]!\u0006"],["ודוחים: יהושפט \u0003לא הוה מפליג נפשיה מיניה\u0004 \u0005[לא היה מחלק עצמו ממנו]\u0006 מאחאב, לשחוט ולאכול בפני עצמו, שהרי רצה להיות קרוב ומחובר אליו. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003אילימא מדכתיב\u0004 \u0005[אם תאמר ממה שנאמר]\u0006 שאמר לו יהושפט לאחאב: \u0003\"כמוני כמוך כעמי כעמך\"\u0004 (מלכים א כב, ד), \u0003אלא מעתה,\u0004 כשאמר \u0003\"כסוסי כסוסיך\"\u0004 (שם) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יכול אתה לפרש במשמעות זו?! \u0003אלא\u0004 הכוונה היא: \u0003מה דהוי אסוסיך תהוי אסוסי\u0004 \u0005[מה שיהיה על סוסיך יהיה גם על סוסי],\u0006 שנלך יחד למלחמה, \u0003הכא נמי\u0004 \u0005[כך גם כן]\u0006 אתה צריך לפרש \"כמוני כמוך כעמי כעמך\" — \u0003מאי דהוי עלך ועילוי עמך תיהוי עלי ועילוי עמי\u0004 \u0005[מה שיהיה עליך ועל עמך יהיה עלי ועל עמי],\u0006 שגורל אחד יהיה לשנינו!","\u0003אלא\u0004 הראיה שרצה יהושפט להיות קרוב ומחובר עם אחאב היא \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"ומלך ישראל ויהושפט מלך יהודה יושבים איש על כסאו מלובשים בגדים בגורן פתח שער שומרון\"\u0004 (שם י), ויש לשאול: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003גורן? אילימא\u0004 \u0005[אם תאמר]\u0006 שישבו ב\u0003גורן ממש, אטו\u0004 \u0005[וכי]\u0006 \u0003שער שומרון גורן הוה\u0004 \u0005[היה]?\u0006 ודאי לא היה גורן בשער, שהוא המקום שבו יושבים זקני העיר ושופטיה! \u0003אלא\u0004 הכוונה היא: \u0003כי\u0004 \u0005[כמו]\u0006 \u0003גורן\u0004 היו יושבים, בעיגול, כשפניהם זה לזה, בידידות, וכמו \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003סנהדרין היתה\u0004 יושבת \u0003כחצי גורן עגולה, כדי שיהו\u0004 החכמים \u0003רואין זה את זה,\u0004 ואף כאן ישבו מלך יהודה ומלך ישראל באופן שיהיו רואים זה עם זה, כאות לידידות.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם לומר שאפשר לסייע לו]\u0006 לרב ענן שאמר ששחיטת המשומד לעבודה זרה כשרה, ממה שנאמר באליהו: \u0003\"והעורבים מביאים לו לחם ובשר בבקר ולחם ובשר בערב\"\u0004 (שם יז, ו), \u0003ואמר רב יהודה, אמר רב:\u0004 את האוכל היו מביאים \u0003מבי טבחי\u0004 \u0005[מבית המטבחיים]\u0006 של \u0003אחאב,\u0004 ובוודאי לא היה אליהו אוכל מבשר זה אילולא השחיטה בבית אחאב היתה כשרה! ומשיבים: \u0003על פי הדבור שאני\u0004 \u0005[שונה],\u0006 שאליהו עשה כך על פי דבר ה' המפורש, ואין להביא מכאן ראיה.","אגב הזכרת פסוק זה שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003עורבים? אמר רבינא: עורבים ממש. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר מניומי: ודלמא תרי גברי דהוי שמייהו\u0004 \u0005[ושמא\u0006 היו אלו \u0005שני אנשים שהיה שמם]\u0006 \u0003עורבים! מי לא כתיב\u0004 \u0005[האם לא נאמר]:\u0006 \u0003\"ויהרגו את עורב בצור עורב ואת זאב\u0004 הרגו ביקב זאב\" (שופטים ז, כה)? משמע שיש שם פרטי \"עורב\"! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא בדחיה: \u0003איתרמאי מילתא דתרוייהו הוה שמייהו\u0004 \u0005[\u0006וכי \u0005הזדמן הדבר ששניהם היה שמם]\u0006 \u0003עורבים?\u0004 אלא ודאי היו אלה עורבים ממש.","ומקשים עוד: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003על שם מקומן\u0004 נקראו \"עורבים\"! \u0003מי לא כתיב\u0004 \u0005[האם לא נאמר]:\u0006 \u0003\"וארם יצאו גדודים וישבו מארץ ישראל נערה קטנה\"\u0004 (מלכים ב ה, ב), \u0003וקשיא לן\u0004 \u0005[והיה קשה לנו]\u0006 בהבנת הפסוק: \u0003קרי\u0004 \u0005[קורא]\u0006 \u0003לה \"נערה\"\u0004 שהיא כמעט בוגרת, \u0003וקרי\u0004 \u0005[וקורא]\u0006 \u0003לה\u0004 והיא \u0003\"קטנה\"\u0004 שאינה בוגרת! \u0003ואמר ר' פדת:\u0004 כוונת הפסוק היא ל\u0003קטנה\u0004 ש\u0003מן\u0004 המקום \u0003נעורן.\u0004 וכשם שקראו לשפחת נעמן \"נערה\" על שם מקומה — שמא קראו לאלה \"עורבים\" על שם מקומם! ודוחים: \u0003אם כן, \"עורביים\" מיבעי ליה\u0004 \u0005[צריך היה לו לומר],\u0006 וכיון שאמר עורבים הכוונה לעורבים ממש.","ועוד מציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם אפשר לסייע לו]\u0006 לרב ענן, שאמר שמשומד לעבודה זרה אינו נחשב משומד לכל התורה, ושחיטתו כשרה, ממה ששנינו: \u0003הכל שוחטין, ואפילו כותי ואפילו ערל ואפילו ישראל משומד.\u0004 ונברר: \u0003האי ערל היכי דמי\u0004 \u0005[ערל זה כיצד הוא בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שמתו אחיו מחמת מילה,\u0004 ומחמת הסכנה אינו נימול, הלוא \u0003האי ישראל מעליא\u0004 \u0005[זה ישראל מעולה,\u0006 כשר\u0005]\u0006 לגמרי \u0003הוא,\u0004 ואין כל חשש לגבי שחיטתו! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שהכוונה היא ל\u0003משומד לערלות,\u0004 שאינו רוצה למול עצמו.","ומעתה \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של ההלכה: \u0003ואפילו ישראל משומד,\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 הכוונה \u0003למשומד לדבר אחד\u0004 מן התורה — \u0003היינו\u0004 \u0005[הרי הוא]\u0006 דין \u0003משומד לערלות\u0004 ששנינו כבר! \u0003אלא לאו\u0004 \u0005[האם אין]\u0006 הכוונה ל\u0003משומד לעבודה זרה, וכ\u0004דברי \u0003רב ענן,\u0004 שמשומד כזה מותר לאכול משחיטתו?","ודוחים: \u0003לא,\u0004 \u0003לעולם אימר\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003משומד לעבודה זרה לא\u0004 שוחט, וכפי ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003חמורה עבודה זרה, שכל הכופר בה כמודה בכל התורה כולה,\u0004 ומכאן שהמשומד לעבודה זרה נחשב ככופר בכל התורה, ונדון כגוי, ששחיטתו פסולה.","\u0003אלא\u0004 הכוונה היא ל\u0003משומד לאותו דבר,\u0004 כלומר, לענין שחיטה, שאוכל גם בהמות שלא נשחטו כראוי. \u0003וכ\u0004דברי \u0003רבא\u0004 שאמר שהמשומד לאכול נבילות לתיאבון נותנים לו סכין בדוקה ושוחט.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת רב ענן, שמותר לאכול משחיטתו של משומד לעבודה זרה, ממה ששנינו בברייתא: נאמר \"אדם כי יקריב מכם קרבן לה' מן הבהמה\" (ויקרא א, ב), ומדייקים: \u0003\"מכם\"\u0004 — \u0003ולא כולכם, להוציא את המשומד,\u0004 שאין מקבלים ממנו קרבן. ועוד: \u0003\"מכם\"\u0004 — \u0003בכם\u0004 בבני ישראל \u0003חלקתי\u0004 בין משומד לאחר, \u0003ולא באומות,\u0004 שמהם מקבלים קרבן מכל אדם, גם אם הוא עובד עבודה זרה. ועוד דרשו: \"מכם \u0003מן הבהמה\"\u0004 (שם) — \u0003להביא\u0004 (לרבות) \u0003בני אדם שדומים לבהמה,\u0004 כלומר, אנשים שאינם מקיימים את מצוות התורה, שאף מהם מקבלים קרבן. \u0003מכאן אמרו\u0004 חכמים: \u0003מקבלין קרבנות מפושעי ישראל כדי שיחזרו בהן בתשובה, חוץ מן המשומד, ומנסך את היין\u0004 לעבודה זרה, \u0003ומחלל שבתות בפרהסיא.\u0004","ותחילה מבררים את לשון הברייתא: \u0003הא גופא קשיא\u0004 \u0005[\u0006ברייתא \u0005זו עצמה קשה],\u0006 \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 מתחילה \u0003\"מכם\"\u0004 — \u0003ולא כולכם, להוציא את המשומד,\u0004 שאין מקבלים ממנו קרבן, \u0003והדר תני\u0004 \u0005[וחוזר ושונה]:\u0006 \u0003מקבלין קרבנות מפושעי ישראל!\u0004","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 \u0003רישא\u0004 \u0005[בתחילה]\u0006 שאין מקבלים מן המשומד, הכוונה ל\u0003משומד לכל התורה כולה,\u0004 ואילו \u0003מציעתא\u0004 \u0005[\u0006בהלכה ה\u0005אמצעית]\u0006 שמקבלים קרבן מפושעי ישראל, הכוונה היא ל\u0003משומד לדבר אחד.\u0004","ומעתה, \u0003אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של הברייתא\u0005]:\u0006 \u0003חוץ מן המשומד ומנסך את היין ומחלל שבת בפרהסיא\u0004 שאין מקבלים מהם קרבן, ונברר: \u0003האי משומד היכי דמי\u0004 \u0005[משומד זה כיצד הוא בדיוק]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משומד לכל התורה כולה\u0004 — \u0003היינו רישא\u0004 \u0005[הרי זה\u0006 מה שכבר שנינו ב\u0005תחילת\u0006 הברייתא\u0005],\u0006 \"מכם\" — להוציא את המשומד! \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר ב\u0003משומד לדבר אחד\u0004 — \u0003קשיא מציעתא\u0004 \u0005[קשה\u0006 ההלכה \u0005האמצעית],\u0006 משם עולה שמקבלים קרבן ממשומד לדבר אחד!","\u0003אלא לאו הכי קאמר\u0004 \u0005[\u0006האם \u0005לא כך הוא אומר]:\u0006 \u0003חוץ מן המשומד לנסך את היין\u0004 לעבודה זרה, \u0003ולחלל שבתות בפרהסיא. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003משומד לעבודה זרה הוה\u0004 \u0005[הרי הוא]\u0006 נחשב \u0003משומד לכל התורה כולה,\u0004 ששחיטתו פסולה כשחיטת הגוי, \u0003ותיובתא\u0004 \u0005[וקושיה חמורה]\u0006 על דברי \u0003רב ענן,\u0004 שאמר ששחיטתו כשרה! ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה היא],\u0006 ונדחו דבריו.","אגב כך שואלים: \u0003והא\u0004 \u0005[וזה]\u0006 שאין מקבלים קרבן מן המשומד \u0003מהכא נפקא\u0004 \u0005[מכאן,\u0006 מפסוק זה \u0005הוא יוצא]?\u0006 הלוא \u0003מהתם נפקא\u0004 \u0005[משם, הוא יוצא],\u0006 ממה שנאמר בענין קרבן חטאת:"],["\"ואם נפש אחת תחטא בשגגה \u0003מעם הארץ...\u0004 והביא קרבנו\" (ויקרא ד, כז—כח) — \"מעם\" הריהו מיעוט, לומר: לא כל עם הארץ, אלא \u0003פרט למשומד,\u0004 שאין מקבלים ממנו קרבן.","\u0003ר' שמעון בן יוסי אומר משום\u0004 (בשם) \u0003ר' שמעון:\u0004 דין זה נלמד ממה שנאמר \"בעשותה אחת ממצוות ה' \u0003אשר לא תעשינה בשגגה ואשם\u0004 או הודע אליו חטאתו וכו' והביא קרבנו\" (שם כב), ללמדנו: \u0003השב מידיעתו\u0004 מי שחוזר בתשובה מפני שנודע לו שחטא, שאם היה יודע מתחילה שיש בכך עבירה לא היה חוטא — הוא \u0003מביא קרבן\u0004 חטאת \u0003על שגגתו,\u0004 אבל מי ש\u0003אינו שב מידיעתו,\u0004 שגם אם היה יודע שזו עבירה היה חוטא — \u0003אינו מביא קרבן על שגגתו.\u0004 משמע שמשומד, שאינו שב מידיעתו, אינו מביא קרבן על השגגה.","\u0003ואמרינן\u0004 \u0005[ואומרים היינו]:\u0006 \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל להלכה \u0005ביניהם]\u0006 בין התנא הראשון ור' שמעון? \u0003ואמר רב המנונא: משומד לאכול חלב והביא קרבן על הדם\u0004 ששגג בו \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל, שלדעת התנא הראשון אינו מביא קרבן, שהרי על כל פנים משומד הוא (לאכול חלב). ולדעת ר' שמעון, כיון שלענין דם אינו משומד, והוא שב מידיעתו, הריהו מביא קרבן על שגגתו. על כל פנים, מכתוב זה למדנו שאין מקבלים קרבן מן המשומד, ולשם מה הוצרך הדיוק מ\"מכם\" כפי ששנינו בברייתא בעמוד הקודם?","ומשיבים: \u0003חדא\u0004 \u0005[\u0006ברייתא \u0005אחת]\u0006 עוסקת \u0003ב\u0004קרבן \u0003חטאת\u0004 שמביא המשומד, \u0003וחדא\u0004 \u0005[ואחת]\u0006 \u0003בעולה\u0004 שמביא כנדבה. ומוסיפים: \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 שני הדברים להיאמר, \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ב\u0003חטאת,\u0004 הייתי אומר שאין מקבלים אותה מן המשומד \u0003משום\u0004 ש\u0003לכפרה הוא,\u0004 ואין משומד ראוי לכפרה, \u0003אבל עולה\u0004 ש\u0003דורון\u0004 (מתנה) בלבד \u0003הוא\u0004 — \u0003אימא לקבל מיניה\u0004 \u0005[אמור שיקבלו ממנו].\u0006 ולהיפך, \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק ב\u0003עולה,\u0004 היינו אומרים שאין מקבלים אותה ממנו \u0003משום דלאו חיובא הוא\u0004 \u0005[שאין היא חיוב]\u0006 אלא מתנה מרצון, ואין המשומד ראוי להביאה. \u0003אבל חטאת דחיובא הוא\u0004 \u0005[שחובה היא],\u0006 ועליו להביא חטאת לכפרת חטאו — \u0003אימא לקבל מיניה\u0004 \u0005[אמור שיקבלו ממנו],\u0006 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר.","בברייתא שבעמוד הקודם דרשו חכמים ש\"מן הבהמה\" כוונתו לאנשים שדומים לבהמה, שאינם מקיימים מצוות, ומשם למדו שמקבלים קרבנות מפושעי ישראל. ושואלים: \u0003וכל היכא דכתיב\u0004 \u0005[וכל מקום שנאמר]\u0006 \u0003בהמה,\u0004 ואנו דורשים אותו כמתייחס לאדם, \u0003גריעותא היא\u0004 \u0005[חסרון הוא]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"אדם ובהמה תושיע ה' \"\u0004(תהלים לו, ז), \u0003ואמר רב יהודה אמר רב\u0004 שיש לפרש את הכתוב כך: \u0003אלו בני אדם שהן\u0004 באמת \u0003ערומין בדעת\u0004 כאדם, \u0003ו\u0004למרות חכמתם \u0003משימין עצמן כבהמה\u0004 בענוה ושפלות! ומשיבים: \u0003התם כתיב\u0004 \u0005[שם נאמר]\u0006 יחד \u0003\"אדם ובהמה\", הכא\u0004 \u0005[כאן]\u0006 שנאמר \"מן הבהמה\" — \u0003בהמה לחודיה כתיב\u0004 \u0005[לעצמו נאמר].\u0006","ושואלים: \u0003וכל היכא דכתיב\u0004 \u0005[וכל מקום שנאמר]\u0006 יחד \u0003\"אדם ובהמה\",\u0004 בהמה לשון \u0003מעליותא\u0004 \u0005[מעלה]\u0006 \u0003היא? והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וזרעתי את בית ישראל\u0004 ואת בית יהודה \u0003זרע אדם וזרע בהמה\"\u0004 (ירמיהו לא, כו), ופירשו חכמים ש\"זרע בהמה\" האמור שם עניינו אנשים פחותים, בורים! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003הא חלקיה קרא\u0004 \u0005[הרי חילק אותם הכתוב],\u0006 \u0003זרע אדם לחוד וזרע בהמה לחוד,\u0004 לומר שכל אחד עומד בפני עצמו.","ושבים לדון בשחיטת כותי \u0003(סימן\u0004 לרשימת החכמים שלהלן \u0003נקלף:\u0004 ח \u0003נ\u0004 ן, יע \u0003ק\u0004 ב, בן \u0003ל\u0004וי, בר ק \u0003פ\u0004 רא","\u0003). אמר רב חנן אמר ר' יעקב בר אידי אמר ר' יהושע בן לוי משום\u0004 (בשם) \u0003בר קפרא: רבן גמליאל ובית דינו נמנו\u0004 (עמדו למנין, הצביעו) \u0003על שחיטת כותי ואסרוה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' יעקב בר אידי: שמא לא שמע רבי\u0004 שאסרוה \u0003אלא בשאין ישראל עומד על גביו\u0004 ורואה את שחיטתו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דמי האי מרבנן כדלא גמירי אינשי שמעתא\u0004 \u0005[דומה חכם זה כאנשים שלא למדו הלכה],\u0006 \u0003בשאין ישראל עומד על גביו למימרא בעי\u0004 \u0005[צריך לומר]\u0006 שהוא אסור? אלא ודאי אסרו שחיטת כותי בכל אופן.","ומבררים: \u0003קבלה\u0004 ר' זירא \u0003מיניה\u0004 \u0005[ממנו]\u0006 מר' יעקב בר אידי תשובה זו, \u0003או לא קבלה מיניה\u0004 \u0005[ממנו],\u0006 שלדעתו שחיטת הכותי כשרה כשישראל עומד על גביו? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ש\u0003אמר רב נחמן בר יצחק\u0004 ש\u0003אמר ר' אסי: אני ראיתי את ר' יוחנן שאכל משחיטת כותי,\u0004 ו\u0003אף ר' אסי\u0004 עצמו \u0003אכל משחיטת כותי. ותהי בה\u0004 \u0005[והיה תוהה בכך]\u0006 \u0003ר' זירא:\u0004 האם \u0003לא שמיעא להו\u0004 \u0005[לא שמעו\u0006 את ההלכה \u0005הזו]\u0006 שלפיה נאסרה שחיטת כותי, \u0003דאי הוה שמיעא להו הוו מקבלי לה\u0004 \u0005[שאם היו שומעים אותה היו מקבלים אותה],\u0006 \u0003או דלמא שמיע להו ולא קבלוה\u0004 \u0005[שמא שמעו אותה ולא קיבלו אותה]?\u0006","\u0003הדר פשיט לנפשיה\u0004 \u0005[חזר ופתר לעצמו]:\u0006 \u0003מסתברא דשמיע להו ולא קבלוה\u0004 \u0005[מסתבר ששמעו\u0006 את ההלכה \u0005ולא קיבלו אותה],\u0006 \u0003דאי סלקא דעתך לא שמיע להו\u0004 \u0005[שאם עולה על דעתך\u0006 ש\u0005לא שמעו]\u0006 הלכה זו, \u0003ואי הוה שמיע להו הוו מקבלי לה\u0004 \u0005[ואם היו שומעים אותה היו מקבלים אותה],\u0006 \u0003היכי מסתייעא מילתא למיכל איסורא\u0004 \u0005[איך יסתייע הדבר\u0006 שאנשים גדולים אלה \u0005יאכלו איסור]?\u0006 \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003בהמתן של צדיקים אין הקדוש ברוך הוא מביא תקלה על ידן\u0004 שיאכלו מן האסור (חולין ז,א), \u0003צדיקים עצמן לא כל שכן\u0004 שאין מגיעים לידי תקלה! אלא ודאי חכמים אלה חולקים על ההלכה הזו, וסוברים ששחיטת כותי מותרת."],["\u0003ואי סלקא דעתיך לא קבלה מיניה\u0004 \u0005[ואם עולה על דעתך\u0006 לומר ש\u0005לא קיבל אותה ממנו]\u0006 ר' זירא מר' יעקב, שרבן גמליאל אסר את שחיטת הכותי רק כשישראל אינו עומד על גביו, \u0003לישני ליה\u0004 \u0005[שיתרץ לו,\u0006 לעצמו\u0005]\u0006 באופן אחר: \u0003כאן כשישראל עומד על גביו\u0004 מותרת שחיטת כותי, ובמקרה זה אכל ר' יוחנן, \u0003כאן\u0004 כשאסר רבן גמליאל — \u0003כשאין ישראל עומד על גביו! אלא לאו שמע מינה קבלה מיניה\u0004 \u0005[האם לא תלמד מכאן שקיבל אותה ממנו]\u0006 שרב גמליאל אסר את שחיטת כותי בכל מקרה? ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ולעצם הענין מסבירים: \u0003ומאי טעמא גזרו בהו רבנן\u0004 \u0005[ומה טעם גזרו בהם חכמים,\u0006 רבן גמליאל ובית דינו\u0005]\u0006 בכותים, לאסור את שחיטתם כגויים? \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003ר' שמעון בן אלעזר שדריה\u0004 \u0005[שלח אותו]\u0006 \u0003ר' מאיר לאתויי חמרא מבי כותאי\u0004 \u0005[להביא יין ממקום הכותיים],\u0006 \u0003אשכחיה ההוא סבא\u0004 \u0005[מצא אותו זקן אחד],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"ושמת סכין בלועך אם בעל נפש אתה\"\u0004 (משלי כג, ב), לרמוז לו שיתרחק מהם, ולא ישתה משלהם, משום שאין לסמוך עליהם. \u0003הלך ר' שמעון בן אלעזר וספר דברים\u0004 אלו \u0003לפני ר' מאיר, וגזר עליהן\u0004 ר' מאיר שיהא יינם אסור כדין יינם של גויים.","ושאלו: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 מה היה הפגם שמצאו בהם? \u0003אמר רב נחמן בר יצחק: דמות יונה מצאו להן בראש הר גריזים שהיו\u0004 היושבים בהר גריזים \u0003עובדין אותה, ור' מאיר לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003דחייש למיעוטא\u0004 \u0005[שהוא חושש\u0006 גם \u0005למיעוט]\u0006 ואינו סומך על הרוב, \u0003וגזר רובא אטו מיעוטא\u0004 \u0005[ו\u0006גם במקרה זה \u0005גזר\u0006 על ה\u0005רוב משום המיעוט],\u0006 שעובדים עבודה זרה זו. \u0003ורבן גמליאל ובית דינו\u0004 שגזרו על שחיטתם \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר סבירא להו\u0004 \u0005[סבורים הם].\u0006","ושואלים: \u0003פשטיה דקרא\u0004 \u0005[פשוטו של אותו מקרא]\u0006 \"ושמת סכין בלועך\" וגו' \u0003במאי כתיב\u0004 \u0005[במה נאמר]?\u0006 ומשיבים: \u0003בתלמיד היושב לפני רבו\u0004 שצריך להיזהר בדבריו, \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא\u0004 ברייתא זו: נאמר, \u0003\"כי תשב ללחום את מושל בין תבין את אשר לפניך ושמת סכין בלועך אם בעל נפש אתה\"\u0004 (שם, א— ב), ונדרש הכתוב בכך:","\u0003אם יודע תלמיד ברבו שיודע להחזיר לו טעם\u0004 (תשובה) לשאלתו — \u0003בין,\u0004 כלומר, שאל ממנו בינה, \u0003ואם לאו\u0004 שסבור אתה שאינו יודע להשיב — \u0003תבין את אשר לפניך ושמת סכין בלועך,\u0004 הימנע מלשאול, כדי שלא יבוא הרב לידי בושה. ומוסיף הכתוב, \u0003אם בעל נפש אתה\u0004 ורצונך לקבל תשובה לשאלתך — \u0003פרוש\u0004 (היבדל) \u0003הימנו,\u0004 ומצא לך רב שיוכל להשיב על שאלה זו.","מסופר, \u0003ר' יצחק בן יוסף שדריה\u0004 \u0005[שלח אותו]\u0006 \u0003ר' אבהו לאתויי חמרא מבי כותאי\u0004 \u0005[להביא יין ממקום הכותיים],\u0006 \u0003אשכחיה ההוא סבא\u0004 \u0005[מצא אותו זקן אחד],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לית\u0004 \u0005[אין]\u0006 \u0003כאן\u0004 במקום הזה \u0003שומרי תורה,\u0004 ואין לסמוך על בני המקום! \u0003הלך רבי יצחק וספר דברים\u0004 אלה \u0003לפני ר' אבהו, והלך ר' אבהו וספר דברים\u0004 אלה \u0003לפני ר' אמי ור' אסי,\u0004 ודנו בדבר, \u0003ולא זזו משם עד שעשאום גויים גמורין.\u0004","ושואלים: \u0003למאי\u0004 \u0005[למה]\u0006 לאיזה ענין עשאום כגויים גמורים? \u0003אי\u0004 \u0005[אם]\u0006 תאמר \u0003ל\u0004ענין \u0003שחיטה\u0004 שאין סומכים על שחיטתם, \u0003ו\u0004שיינם \u0003יין נסך,\u0004 הלוא \u0003מהתם גזרו בהו רבנן\u0004 \u0005[משם,\u0006 מזמנו של ר' מאיר ורבן גמליאל, כבר \u0005גזרו בהם חכמים]!\u0006 ומשיבים: \u0003אינהו גזור ולא קבלו מינייהו\u0004 \u0005[הם\u0006 הראשונים \u0005גזרו ולא קיבלו מהם],\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 \u0003ר' אמי ור' אסי\u0004 וחזרו ו\u0003גזרו\u0004 גזירה זו \u0003וקבלו מינייהו\u0004 \u0005[מהם].\u0006","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות של הביטוי \u0003\"גויים גמורין\"? אמר רב נחמן בר יצחק:\u0004 לענין \u0003לבטל רשות\u0004 שיש לו בחצר משותפת בשבת, \u0003ו\u0004כן \u0003ליתן רשות\u0004 בחצר, שיידונו הכותים לענין זה כגויים.","\u0003וכדתניא\u0004 \u0005[וכמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ישראל\u0004 שהיה \u0003משומד\u0004 לחלל שבת, אבל היה \u0003משמר שבתו בשוק,\u0004 שבפני רבים נזהר מלחלל שבת, אם לא עירב עירובי חצירות לפני השבת — דינו כישראל כשר, \u0003מבטל\u0004 את ה\u0003רשות\u0004 שלו בחצר המשותפת, \u0003ו\u0004כן \u0003נותן\u0004 את ה\u0003רשות\u0004 שלו לשאר בני החצר, ומותר לשאר הישראלים שעשו עירוב לטלטל בחצר. \u0003ו\u0004אולם מי \u0003שאינו משמר שבתו\u0004 גם \u0003בשוק\u0004 — \u0003אינו מבטל רשות ונותן רשות.\u0004","וטעם הדבר, \u0003מפני שאמרו\u0004 חכמים: \u0003ישראל נותן רשות ומבטל רשות\u0004 בדיבור בלבד, \u0003ובגוי\u0004 אין מועיל \u0003עד שישכור\u0004 ממנו את רשותו בכסף, ומחלל שבת בפרהסיא דינו כגוי. והוא הדין לכותי.","ומוסיפים, \u0003כיצד\u0004 הוא האופן של נתינת רשות, או ביטול רשות (על ידי ישראל)? אם \u0003אמר לו\u0004 לשכנו: \u0003\"רשותי קנויה לך\"\u0004 או \u0003\"רשותי מבוטלת לך\"\u0004 — \u0003קנה\u0004 את הרשות, \u0003ואינו צריך לזכות\u0004 לו את רשותו באחת מדרכי הקנין הקבועות.","ושבים לדון בענין שהוזכר בעמוד הקודם, שצדיקים אין הקדוש ברוך הוא מביא תקלה של חטא על ידם. מסופר, \u0003ר' זירא ורב אסי איקלעו לפונדקא\u0004 \u0005[הזדמנו לפונדק]\u0006 של המקום \u0003יאי, אייתו לקמייהו\u0004 \u0005[הביאו לפניהם]\u0006 \u0003ביצים המצומקות\u0004 (שבושלו הרבה עד שהצטמקו) \u0003ב\u0004תוך \u0003יין, ר' זירא לא אכל\u0004 לפי שחשש שמא לא הפרישו מעשר מן היין, \u0003ורב אסי אכל. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לרב אסי: ולא חייש מר\u0004 \u0005[ו\u0006כי \u0005אין אדוני חושש]\u0006 \u0003לתערובת\u0004 יין \u0003דמאי\u0004 (יבול שספק אם הופרש ממנו מעשר) שיש בביצים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו אדעתאי\u0004 \u0005[לא\u0006 עלה הדבר \u0005בדעתי].\u0006","\u0003אמר ר' זירא\u0004 בליבו: \u0003אפשר גזרו\u0004 חכמים \u0003על התערובת\u0004 של \u0003דמאי\u0004 שתהיה אסורה, \u0003ומסתייעא מילתא\u0004 \u0005[ויסתייע הדבר,\u0006 יקרה בפועל\u0005]\u0006 ל\u0003רב אסי למיכל איסורא\u0004 \u0005[לאכול איסור]?\u0006 \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003בהמתן של צדיקים אין הקדוש ברוך הוא מביא תקלה על ידן, צדיקים עצמן לא כל שכן?\u0004 ולכן צריך לבדוק אם יש בכך איסור.","\u0003נפק\u0004 \u0005[יצא]\u0006 \u0003רבי זירא דק ואשכח\u0004 \u0005[דקדק ומצא],\u0006 שאכן לא נכשל רב אסי, \u0003דתנן\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הלוקח\u0004 (הקונה) בשוק \u0003יין לתת לתוך המורייס\u0004 (ציר של דגים) \u0003או לתוך האלונתית\u0004 (משקה מעורב ביין), או שקנה \u0003כרשינין לעשות מהן טחינין\u0004 (מאכל שמעורבים בו כרשינים טחונים) או \u0003עדשים לעשות מהן רסיסין\u0004 (מאכל שמעורבים בו עדשים), אם ספק לו אם עושרו — \u0003חייב\u0004 לעשר אותם \u0003משום דמאי, ואין צריך לומר\u0004 שאם ברור לו שלא עושרו שחייב לעשרם \u0003משום ודאי.\u0004","\u0003והן עצמן,\u0004 המורייס והאלונתית, הטחינין והרסיסין, כשקונה אותם מעם הארץ כשהם מוכנים — \u0003מותרין, מפני שהן תערובת.\u0004 משמע, איפוא, שאין איסור בתערובת דמאי.","ותוהים: \u0003ו\u0004האם \u0003לא גזרו על תערובת דמאי? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הנותן לשכנתו\u0004 שהיא מעמי הארץ \u0003עיסה לאפות\u0004 ונתן עמה שאור לצורך האפיה, \u0003וקדירה לבשל\u0004 ותבלין עמה — \u0003אינו חושש לשאור ותבלין שבה,\u0004 בעיסה או בתבשיל שהכינה, \u0003לא משום שביעית\u0004 שמא אינה שומרת שביעית והחליפה בתבלינים שלה שהם של שביעית, \u0003ולא משום מעשר, ו\u0004אולם","\u0003אם אמר לה\u0004 במפורש \u0003\"עשי לי משליכי\u0004 (משלך)\", מן השאור או התבלין שלך — \u0003חושש לשאור ותבלין שבה משום שביעית ומשום מעשר,\u0004 למרות שמדובר בתערובת דמאי!","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 ש\u0003כיון דקאמר\u0004 \u0005[שהוא אומר]\u0006 \u0003לה \"עשי לי משליכי\"\u0004 — \u0003כמאן דעריב בידים דמי\u0004 \u0005[כמי שמערב בידיו\u0006 הוא \u0005נחשב],\u0006 כאילו מכניס בעצמו דמאי, ובאופן זה ודאי אינו רשאי לאכול עד שיעשר. \u0003רפרם אמר\u0004 תירוץ אחר: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003שאור ותבלין, דלטעמא עביד\u0004 \u0005[שלטעם הוא עשוי],\u0006 \u0003וטעמא לא בטיל\u0004 \u0005[וטעם לא בטל],\u0006 אף על פי שהוא בתערובת.","ותוהים: \u0003ולחלופי לא חיישינן\u0004 \u0005[ולהחלפה אין אנו חוששים]\u0006 שמא תחליף השכנה את מה שהביא לה בשלה? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנותן לחמותו\u0004 שהיתה חשודה על המעשרות, עיסה לאפות — הרי הוא \u0003מעשר\u0004 תחילה \u0003את\u0004 מה \u0003שהוא נותן לה,\u0004 כדין כל מי שנותן מאכל לעם הארץ, \u0003ו\u0004כן מעשר גם \u0003את\u0004 מה \u0003שהוא נוטל ממנה\u0004 בחזרה, \u0003מפני שחשודה\u0004 שהיא \u0003מחלפת\u0004 את הדבר \u0003המתקלקל,\u0004 שאם נתן לה דבר והתקלקל, היא מחליפה בשלה! ומשיבים: \u0003התם כדתניא טעמא\u0004 \u0005[שם\u0006 יש דין מיוחד, \u0005כמו ששנוי הטעם],\u0006 \u0003אמר ר' יהודה: רוצה היא בתקנת בתה,\u0004 כלומר, היא מעוניינת בטובת בתה שתאכל מאכל משובח, ו\u0003בושה\u0004 (מתביישת) \u0003מחתנה,\u0004 ואינה אומרת לו במפורש שהיא מחליפה את מה שהתקלקל, אלא מחליפה בחשאי."],["ומוסיפים ושואלים: \u0003ולעלמא לא חיישינן\u0004 \u0005[ובכלל,\u0006 במקום שאין סיבה מיוחדת, \u0005אין אנו חוששים]\u0006 שעם הארץ יחליף את הניתן לו? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנותן\u0004 עיסה או קדירה \u0003לפונדקית שלו\u0004 שתאפה או תבשל לו — \u0003מעשר\u0004 תחילה \u0003את שהוא נותן לה ואת שהוא נוטל הימנה\u0004 (ממנה), \u0003מפני שחשודה\u0004 ש\u0003מחלפת!\u0004 ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 יש טעם מיוחד בדבר, משום שאשת עם הארץ \u0003מוריא ואמרה\u0004 \u0005[מורה\u0006 לעצמה היתר להחליף \u0005ואומרת]:\u0006 \u0003בר בי רב ליכול חמימא ואנא איכול קרירא\u0004 \u0005[התלמיד חכם יאכל חם ואני אוכל קר],\u0006 ולכן היא מחליפה לו, אבל במקרה אחר אין חוששים להחלפה.","ושואלים: \u0003ולחלופי לא חיישינן\u0004 \u0005[ולחילוף אין אנו חוששים]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אשת חבר טוחנת עם אשת עם הארץ\u0004 בתבואת עם הארץ \u0003בזמן שהיא\u0004 (אשת החבר) \u0003טמאה,\u0004 כגון שהיא נדה. ואין חשש שתאכל מן התבואה שאינה מעושרת, שכיון שהיא טמאה היא נזהרת ואינה נוגעת בתבואה, כדי שלא תטמא אותה, \u0003אבל לא בזמן שהיא טהורה,\u0004 שמא תכניס לפיה תבואה שאינה מעושרת.","\u0003ר' שמעון בן אלעזר אומר: אף בזמן שהיא טמאה לא תטחון\u0004 עם אשת עם הארץ, \u0003מפני שחבירתה\u0004 (אשת עם הארץ) \u0003נותנת לה\u0004 מן התבואה \u0003ואוכלת.\u0004","ומעתה, \u0003השתא מיגזל גזלה\u0004 \u0005[עכשיו,\u0006 הרי, אנו מניחים שאשת עם הארץ \u0005גוזלת]\u0006 ולוקחת משל בעלה ונותנת לחברותיה, וכי \u0003חלופי מיבעיא\u0004 \u0005[להחליף צריך\u0006 לומר\u0005]\u0006 שהיא חשודה על כך? \u0003אמר רב יוסף, התם נמי\u0004 \u0005[שם גם כן]\u0006 יש טעם מיוחד בדבר, ש\u0003מוריא ואמרה\u0004 \u0005[שמורה\u0006 לעצמה היתר \u0005ואומרת]:\u0006 \u0003תורא מדישיה קאכיל\u0004 \u0005[השור מדישו הוא אוכל],\u0006 וסבורה שמותר לה לעשות כן.","ומביאים מעשה הקשור למה שהוזכר לעיל, שאין צדיקים מגיעים לידי מכשול אפילו בשגגה. מסופר, \u0003העיד ר' יהושע בן זרוז, בן חמיו של ר' מאיר, לפני רבי, על ר' מאיר שאכל עלה של ירק בבית שאן\u0004 מבלי להפריש ממנו תרומה ומעשר, שסבר שאין בית שאן מארץ ישראל ואינה קדושה בקדושת הארץ, \u0003והתיר רבי את בית שאן כולה על ידו,\u0004 על סמך עדות זו.","\u0003חברו עליו\u0004 על רבי \u0003אחיו ובית אביו, אמרו לו: מקום שאבותיך ואבות אבותיך נהגו בו איסור, אתה תנהוג בו היתר?\u0004","\u0003דרש להן\u0004 רבי \u0003מקרא זה\u0004 שנאמר במלך חזקיהו: \u0003\"וכתת נחש הנחשת אשר עשה משה כי עד הימים ההמה היו בני ישראל מקטרים לו ויקרא לו נחושתן\"\u0004 (מלכים ב יח, ד), ויש לתמוה: \u0003אפשר\u0004 (ייתכן) שקיטרו לנחש זה ו\u0003בא אסא\u0004 שהיה מלך צדיק \u0003ולא ביערו\u0004 מהעולם, ולאחריו \u0003בא יהושפט ולא ביערו\u0004 עד ימי חזקיה? \u0003והלא כל עבודה זרה שבעולם אסא ויהושפט ביערום!\u0004"],["\u0003אלא\u0004 צריך אתה לומר ש\u0003מקום הניחו לו אבותיו\u0004 לחזקיה בענין זה \u0003להתגדר\u0004 (להתגדל) \u0003בו\u0004 שיתחדש על ידו. \u0003אף אני,\u0004 הוסיף רבי — \u0003מקום הניחו לי אבותי להתגדר בו.\u0004","ומוסיפים: \u0003מכאן\u0004 יש ללמוד \u0003לתלמיד חכם שאמר דבר הלכה\u0004 חדש, \u0003שאין מזיחין אותו, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בלשון: \u0003אין מזניחין אותו, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בלשון: \u0003אין מזחיחין אותו.\u0004","ומסבירים את שינוי הלשונות: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \"אין \u0003מזיחין\"\u0004 — \u0003כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"ולא יזח החשן\u0004 מעל האפוד\" (שמות כח, כח), כלומר, אין מזיזים אותו מדבריו; \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003\"אין מזניחין\"\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי לא יזנח לעולם ה' \"\u0004(איכה ג, לא), לומר שאין מתעלמים מדעתו; \u0003ומאן דאמר\u0004 \u0005[ומי שאמר]\u0006 \"אין \u0003מזחיחין\"\u0004 — כמו \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003משרבו זחוחי הלב, רבו מחלוקות בישראל,\u0004 שאין אומרים לו שבגלל גאוה הוא מחדש דברים.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על עיקרה של הלכה זו, \u0003יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי: ומי איכא למאן דאמר\u0004 \u0005[והאם יש מי שאומר]\u0006 ש\u0003בית שאן לאו מארץ ישראל היא? והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ולא הוריש מנשה את בית שאן ואת בנותיה ואת תענך ואת בנותיה\"\u0004 (שופטים א, כז), אלא הניחום למס עובד והיו יושבים ביניהם, ומכאן משמע שהיא מארץ ישראל!","ומשיבים: \u0003אישתמיטתיה הא דאמר\u0004 \u0005[נשמטה ממנו,\u0006 שכח שמועה \u0005זו שאמר]\u0006 \u0003ר' שמעון בן אליקים משום ר' אלעזר בן פדת שאמר משום ר' אלעזר בן שמוע: הרבה כרכים כבשום עולי מצרים\u0004 וקידשום בכניסתם לארץ בימי יהושע בן נון, \u0003ולא כבשום עולי בבל\u0004 בשיבת ציון בימי עזרא, ובכללם בית שאן.","\u0003וקסבר\u0004 \u0005[וסבור הוא]:\u0006 \u0003קדושה ראשונה\u0004 שנתקדשה ארץ ישראל בימי יהושע בן נון לענין קיום המצוות התלויות בה, \u0003קדשה לשעתה ולא קדשה לעתיד לבא,\u0004 אלא פקעה לאחר שנעזבה הארץ בחורבן הבית הראשון. \u0003ו\u0004כשעלו עולי בבל וחזרו וקידשו את הארץ \u0003הניחום\u0004 לאותם מקומות ולא קידשום, \u0003כדי שיסמכו עליהן עניים בשביעית,\u0004 כשאין תבואה מצויה בארץ. שהואיל ואינם קדושים בקדושת הארץ מותר לזרוע שם בשביעית, וכך יוכלו העניים להתפרנס משם. וכיון שהתברר לרבי שבית שאן היא מאותן ערים — התיר אותה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא:\u0004 כיצד סמך רבי על עדותו של ר' יהושע בן זירוז לפטור ירק מתרומות ומעשרות בבית שאן? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' מאיר עלה בעלמא הוא דאכיל\u0004 \u0005[\u0006עלה \u0005בלבד הוא שאכל],\u0006 ואכילת ארעי מותרת גם במקום שחייב בתרומה ומעשר! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאגודה אכליה\u0004 \u0005[אכל אותו],\u0006 \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003ירק הנאגד,\u0004 שדרך לאוגדו יחד, מתחייב בתרומה ומעשר \u0003משיאגד,\u0004 ושוב אין לאכול ממנו אף אכילת ארעי עד שיעשר.","ושואלים: \u0003ודלמא לאו אדעתיה\u0004 \u0005[ושמא לא על דעתו]\u0006 כלומר, בהיסח הדעת אכל ר' מאיר את העלה! ומשיבים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003בהמתן של צדיקים אין הקדוש ברוך הוא מביא תקלה על ידן, צדיקים עצמן לא כל שכן?\u0004 ואין לייחס לו שגגה כזו.","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003עישר עליהם מ\u0004ירק שהיה לו ב\u0003מקום אחר!\u0004 ומשיבים: \u0003לא נחשדו חברים\u0004 המקפידים על תרומה ומעשר \u0003לתרום שלא מן המוקף\u0004 (הסמוך). ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003נתן עיניו בצד זה\u0004 של הירק, חישב לעשותו תרומה ומעשר, \u0003ואכל בצד אחר! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזי מאן גברא רבה קמסהיד עליה\u0004 \u0005[ראה מי האדם הגדול שמעיד עליו],\u0006 ואדם גדול כר' יהושע בן זרוז, וודאי התבונן והיטיב לראות מה עשה ר' מאיר.","ומבררים: \u0003מאי\u0004 \u0005[מהו]\u0006 ענין זה של \u0003בהמתן של צדיקים\u0004 שהזכרנו כמה פעמים, שאין הקדוש ברוך הוא מביא תקלה על ידן? כפי המסופר ש\u0003ר' פנחס בן יאיר הוה קאזיל\u0004 \u0005[היה הולך]\u0006 \u0003לפדיון שבויין, פגע ביה\u0004 \u0005[פגש בו]\u0006 \u0003בגינאי נהרא\u0004 \u0005[הנהר]\u0006 בתוך דרכו,","\u0003אמר ליה\u0004 \u0005[לו]\u0006 לנהר: \u0003גינאי, חלוק לי מימך\u0004 לכאן ולכאן \u0003ואעבור בך. אמר ליה\u0004 \u0005[לו]\u0006 הנהר: \u0003אתה הולך לעשות רצון קונך,\u0004 לקיים מצות פדיון שבויים, \u0003ו\u0004גם \u0003אני הולך לעשות רצון קוני,\u0004 שאני זורם באפיקי כפי שנבראתי לכך, \u0003אתה\u0004 — \u0003ספק עושה\u0004 שספק אם אתה מצליח בפדיון השבויים \u0003ספק אי אתה עושה, אני\u0004 — \u0003ודאי עושה\u0004 את רצון קוני. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' פנחס בן יאיר: \u0003אם אי\u0004 \u0005[אין]\u0006 \u0003אתה חולק\u0004 מימיך, \u0003גוזרני עליך שלא יעברו בך מים לעולם! חלק ליה\u0004 \u0005[לו]\u0006 הנהר מימיו ועבר בו.","\u0003הוה ההוא גברא דהוה דארי חיטי לפיסחא\u0004 \u0005[היה\u0006 איתו \u0005אדם אחד שהיה נושא חיטים ל\u0006צורך מצות של \u0005פסח],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' פנחס לנהר: \u0003חלוק ליה נמי להאי\u0004 \u0005[חלוק לו גם כן\u0006 מימיך \u0005לזה],\u0006 ש\u0003במצוה עסיק\u0004 \u0005[הוא עוסק],\u0006 \u0003חלק ליה\u0004 \u0005[לו]\u0006 מימיו. \u0003הוה ההוא טייעא דלווה בהדייהו\u0004 \u0005[היה ערבי אחד שהיה מתלווה עימם],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' פנחס לנהר: \u0003חלוק ליה נמי להאי\u0004 \u0005[חלוק לו\u0006 מימיך \u0005גם כן לזה],\u0006 \u0003דלא לימא\u0004 \u0005[שלא יאמר]:\u0006 \u0003כך עושים לבני לויה? חלק ליה\u0004 \u0005[לו].\u0006","\u0003אמר רב יוסף: כמה נפיש גברא\u0004 \u0005[גדול אדם\u0006 זה\u0005]\u0006 ר' פנחס בן יאיר \u0003ממשה ושתין רבוון\u0004 \u0005[וששים ריבוא מישראל],\u0006 \u0003דאילו התם חד זימנא\u0004 \u0005[שאילו שם\u0006 נבקע הים רק \u0005פעם אחת],\u0006 \u0003והכא תלתא זימנין\u0004 \u0005[וכאן\u0006 נבקע הנהר \u0005שלוש פעמים].\u0006 ותמהים: \u0003ודלמא הכא נמי חדא זימנא\u0004 \u0005[ושמא כאן גם כן היה פעם אחת],\u0006 שהנהר לא חזר לזרום עד שעברו שלושתם! \u0003אלא\u0004 הכוונה היא צריך לומר שכוחו גדול \u0003כמשה ושתין רבוון\u0004 \u0005[וששים ריבוא].\u0006","לאחר שעבר ר' פנחס בן יאיר את הנהר \u0003אקלע לההוא אושפיזא\u0004 \u0005[הזדמן לפונדק אחד],\u0006 \u0003רמו ליה שערי לחמריה\u0004 \u0005[השליכו שעורים לפני חמורו]\u0006 על מנת שיאכל, \u0003לא אכל,\u0004"],["\u0003חבטינהו\u0004 \u0005[ניפו אותן\u0006 את השעורים\u0005]\u0006 לנקותן ו\u0003לא אכל, נקרינהו\u0004 \u0005[בררו אותן]\u0006 ביד מן הפסולת ו\u0003לא אכל,\u0004 ותהו למה אין החמור אוכל. \u0003אמר להו\u0004 \u0005[להם]\u0006 ר' פנחס בן יאיר למארחיו: \u0003דלמא לא מעשרן\u0004 \u0005[שמא אינן מעושרות]?\u0006 \u0003עשרינהו\u0004 \u0005[עישרו אותן]\u0006 \u0003ואכל\u0004 החמור. \u0003אמר\u0004 להם: בהמה \u0003ענייה\u0004 (מסכנה) \u0003זו הולכת לעשות רצון קונה\u0004 בדרך של מצוה, לפדיון שבויים, \u0003ואתם מאכילין אותה טבלים?\u0004 והוא מה שנאמר לעיל, שבהמתן של צדיקים אין הקדוש ברוך הוא מביא תקלה על ידן.","ותוהים: \u0003ומי מיחייבא\u0004 \u0005[והאם\u0006 התבואה \u0005חייבת]\u0006 במקרה זה במעשר מן הספק? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הלוקח\u0004 (הקונה) מן השוק תבואה \u0003ל\u0004שם \u0003זרע\u0004 או \u0003ל\u0004מאכל \u0003בהמה,\u0004 או \u0003קמח ל\u0004עיבוד \u0003עורות,\u0004 או \u0003שמן\u0004 להדליק בו את ה\u0003נר, ו\u0004כן \u0003שמן לסוך בו את הכלים,\u0004 ואינו יודע אם נתעשרו, כל שאינו למאכל אדם — \u0003פטור מהדמאי,\u0004 שלא חייבוהו חכמים לעשרו מן הספק!","ומשיבים: \u0003התם הא אתמר עלה\u0004 \u0005[שם הרי נאמר על כך],\u0006 \u0003אמר ר' יוחנן: לא שנו אלא שלקחן מתחלה לבהמה,\u0004 או לשאר צרכים שאינם מאכל אדם, \u0003אבל לקחן מתחלה לאדם ונמלך עליהם\u0004 לתתן \u0003לבהמה\u0004 — \u0003חייב לעשר;\u0004 \u0003והתניא\u0004 \u0005[וכן שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הלוקח פירות מן השוק לאכילה, ונמלך עליהן לבהמה\u0004 — \u0003הרי זה לא יתן לא לפני בהמתו ולא לפני בהמת חברו אלא אם כן עישר.\u0004 ושעורים אלו שניתנו לפני האתון נלקחו מתחילה למאכל אדם.","\u0003שמע רבי\u0004 שהגיע ר' פנחס בן יאיר לעירו, \u0003נפק לאפיה\u0004 \u0005[יצא לקראתו]\u0006 לקבל פניו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רצונך\u0004 ל\u0003סעוד אצלי? אמר לו\u0004 ר' פנחס: \u0003הן. צהבו\u0004 (האירו) \u0003פניו של רבי\u0004 מחמת שמחה, שנתכבד בדבר זה, שהיה הדבר מפורסם שאין ר' פנחס בן יאיר סועד אצל אחרים.","\u0003אמר לו\u0004 ר' פנחס: \u0003כמדומה אתה שמודר הנאה מישראל אני?\u0004 \u0003ישראל קדושים הן,\u0004 אלא ש\u0003יש רוצה\u0004 להכניס אורחים \u0003ואין לו,\u0004 ואיני רוצה ליהנות מסעודה שאינה מספקת לבעליה, \u0003ויש שיש לו ואינו רוצה\u0004 שיאכלו אצלו, \u0003ו\u0004ביחס לאדם כזה \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"אל תלחם\u0004 (תאכל) את \u0003לחם רע עין ואל תתאו למטעמותיו כי כמו שער בנפשו כן הוא אכול ושתה יאמר לך ולבו בל עמך\"\u0004 (משלי כג ו-ז), ולכן אני חושש לסעוד אצל אחרים. \u0003ואתה רוצה\u0004 לארחני \u0003ו\u0004גם \u0003יש לך,\u0004 ולכן אליך אני מוכן לבוא.","\u0003מיהא השתא מסרהיבנא\u0004 \u0005[אולם עכשיו אני ממהר],\u0006 \u0003דבמלתא דמצוה קא טרחנא\u0004 \u0005[\u0006משום \u0005שבדבר של מצוה אני טורח],\u0006 \u0003כי הדרנא אתינא עיילנא לגבך\u0004 \u0005[כאשר אחזור ואבוא\u0006 לעירכם \u0005אכנס אליך].\u0006 וכך אכן עשה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 לביתו של רבי, \u0003איתרמי על בההוא פיתחא דהוו קיימין ביה כודנייתא חוורתא\u0004 \u0005[הזדמן שנכנס בפתח אחד שהיו עומדות בו פרדות לבנות],\u0006 \u0003אמר\u0004 ר' פנחס: \u0003מלאך המות בביתו של זה ואני אסעוד אצלו?\u0004 משום שפרדות ממין זה היו מפורסמות כמזיקות בבעיטותיהן.","\u0003שמע רבי נפק לאפיה\u0004 \u0005[יצא לקראתו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מזבנינא להו\u0004 \u0005[מוכר אני אותן].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' פנחס: והרי בכך תעבור על \u0003\"ולפני עור לא תתן מכשול\"\u0004 (ויקרא יט, יד), שהרי לכל אחד מישראל נאסר להחזיק חיות מזיקות בביתו.","אמר לו: \u0003מפקרנא להו\u0004 \u0005[אפקיר אותם].\u0006 אמר לו: אם כן, \u0003מפשת היזקא\u0004 \u0005[אתה מרבה את ההיזק],\u0006 שעכשיו לא יהיו להם בעלים שישמרו עליהן, ויזיקו לכל. אמר לו: \u0003עקרנא להו\u0004 \u0005[אני מעקר את\u0006 פרסותיהן \u0005שלא יזיקו].\u0006 ענה לו: \u0003איכא\u0004 \u0005[יש\u0006 בכך\u0005]\u0006 \u0003צער בעלי חיים.\u0004 אמר לו: \u0003קטילנא להו\u0004 \u0005[אהרוג אותן].\u0006 אמר לו: \u0003איכא\u0004 \u0005[יש\u0006 בכך\u0005]\u0006 איסור של \u0003\"בל תשחית\"\u0004 (דברים כ, יט).","\u0003הוה קא מבתש ביה טובא\u0004 \u0005[היה\u0006 רבי \u0005מפציר בו הרבה]\u0006 שייכנס לביתו, \u0003גבה טורא בינייהו\u0004 \u0005[הר ביניהם],\u0006 ולא יכול היה רבי להמשיך ולדבר עמו. \u0003בכה רבי ואמר: מה בחייהן\u0004 של צדיקים \u0003כך\u0004 הם גדולים, \u0003במיתתן על אחת כמה וכמה!\u0004 ומסבירים: והוא כפי ש\u0003אמר ר' חמא בר חנינא: גדולים צדיקים במיתתן יותר מבחייהן, שנאמר: \"ויהי הם קוברים איש והנה ראו\u0004 את \u0003הגדוד וישליכו את האיש בקבר אלישע\u0004 (הנביא) \u0003וילך ויגע האיש בעצמות אלישע ויחי ויקם על רגליו\"\u0004 (מלכים ב יג, כא).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי:\u0004 מה הראיה מכאן שצדיק גדול במותו יותר מבחייו? \u0003ודילמא לקיומי ביה ברכתא\u0004 \u0005[ושמא\u0006 נעשה הדבר באלישע \u0005כדי לקיים בו את ברכת]\u0006 \u0003אליהו, דכתיב\u0004 \u0005[שנאמר]\u0006 שאלישע ביקש ממנו: \u0003\"ויהי נא פי שנים ברוחך אלי\"\u0004 (שם ב, ט), שאליהו החיה מת אחד ואלישע החיה שנים! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי בתמיהה: \u0003אי הכי\u0004 \u0005[אם\u0006 משום \u0005כך],\u0006 \u0003היינו דתניא\u0004 \u0005[\u0006וכי \u0005זהו ששנויה\u0006 ברייתא\u0005]:\u0006 \"ויקם על רגליו\" — \u0003על רגליו עמד\u0004 אבל \u0003לביתו לא הלך\u0004 (אלא מת מיד)?! ומשמע שלא היתה כאן תחיית מתים ממש, ואם כן לא נתקיימה בכך ברכת אליהו.","ושואלים: \u0003אלא במה איקיים\u0004 \u0005[במה התקיימה]\u0006 הברכה של \"פי שנים\"? ומשיבים: \u0003כ\u0004מו ש\u0003אמר ר' יוחנן: שריפא\u0004 אלישע \u0003צרעת נעמן, שהיא\u0004 (צרעת) \u0003שקולה כמת.\u0004 ומנין שצרעת שקולה כמיתה — \u0003שנאמר\u0004 במרים שנצטרעה: \u0003\"אל נא תהי כמת\"\u0004 (במדבר יב, יב).","אגב שהוזכרו פרדות לבנות (\"מלאך הבית בביתו של זה\"), מביאים מה ש\u0003אמר ר' יהושע בן לוי: למה נקרא שמן\u0004 של פרדים \u0003\"ימים\"\u0004 (ראה בראשית לו, כד) — מלשון אימה, משום \u0003שאימתם מוטלת על הבריות,\u0004 ש\u0003אמר ר' חנינא\u0004 שהיה רופא: \u0003מימי לא שאלני אדם על מכת פרדה לבנה וחיה\u0004 (ונשאר חי) ממכה זו, משמע שהם מסוכנים ביותר. ותוהים: \u0003והא קחזינא דחיי\u0004 \u0005[והרי אנו רואים שאנשים חיים]\u0006 מבעיטות אלה! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן בלשון \u0003\"וחיית\"\u0004 \u0005[והבריאה]\u0006 המכה, שהפצע מבעיטה זו אינו מבריא. ומקשים: \u0003והא קחזינא דמיתסי\u0004 \u0005[והרי רואים אנו\u0006 שהפצעים הללו \u0005מבריאים]!\u0006 ומשיבים: לא בכל הפרדות הלבנות מדובר, אלא באלה \u0003דחיוורן ריש כרעייהו\u0004 \u0005[שלבנים ראשי רגליהם]\u0006 \u0003קא אמרינן\u0004 \u0005[אומרים אנו].\u0006 אגב שהוזכרו דברי ר' חנינא מביאים עוד מדבריו.","על הנאמר \u0003\"אין עוד מלבדו\"\u0004 (דברים ד, לה) — \u0003אמר רבי חנינא: ואפילו כשפים,\u0004 שאין כשפים יכולים לפעול נגד רצון שמים. ומסופר, \u0003ההיא איתתא דהות קא מהדרא למישקל עפרא מתותיה כרעיה\u0004 \u0005[אשה אחת היתה מחזרת,\u0006 משתדלת \u0005לקחת עפר מתחת רגליו]\u0006 של \u0003ר' חנינא\u0004 כדי לעשות לו כישוף, \u0003אמר לה: שקולי\u0004 \u0005[קחי],\u0006 \u0003לא מסתייעא מילתיך\u0004 \u0005[לא יסתייע הדבר שלך,\u0006 מה שאת רוצה לעשות\u0005],\u0006 \u0003\"אין עוד מלבדו\" כתיב\u0004 \u0005[נאמר],\u0006 והוא מגן עלי. ומקשים: \u0003והאמר\u0004 \u0005[והרי נאמר]\u0006 \u0003ר' יוחנן: למה נקרא שמן \"כשפים\"\u0004 — הרי זה כעין נוטריקון — \u0003שמכחישין פמליא של מעלה,\u0004 ומשמע שלכאורה הם פועלים גם כנגד רצון של מעלה! ומשיבים: אכן כך, ואולם \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003ר' חנינא, דנפישא זכותיה\u0004 \u0005[שמרובה זכותו],\u0006 ואין כשפים שולטים בו.","\u0003ו\u0004עוד \u0003אמר\u0004 בשם \u0003ר' חנינא: אין אדם נוקף\u0004 (מכה, פוצע) \u0003אצבעו מלמטה אלא אם כן מכריזין עליו מלמעלה\u0004 שהוא צריך להיפצע, \u0003שנאמר: \"מה' מצעדי גבר כוננו ואדם מה יבין דרכו\"\u0004 (ראה תהלים לז, כג. משלי כ, כד). בענין זה \u0003אמר ר' אלעזר: דם ניקוף\u0004 (מכה) \u0003מרצה\u0004 ומכפר לאדם \u0003כ\u0004אילו היה זה \u0003דם עולה. אמר רבא:\u0004 מדובר פה \u0003בגודל\u0004 (בוהן) \u0003ימין,\u0004 שאדם משתמש בו בכח, והמכה חזקה יותר, \u0003ובניקוף\u0004 (מכה) \u0003שני\u0004 באותו מקום קודם שהתרפאה המכה הראשונה, \u0003והוא דקאזיל\u0004 \u0005[כשהיה הולך]\u0006 באותה שעה \u0003לדבר מצוה,\u0004 שאז הניקוף מרצה.","בקשר למסופר לעיל על ר' פנחס בן יאיר מעירים כי \u0003אמרו עליו על ר' פנחס בן יאיר: מימיו לא בצע\u0004 (חתך, פתח באכילה) \u0003על פרוסה שאינה שלו, ומיום שעמד על דעתו לא נהנה\u0004 אפילו \u0003מסעודת אביו,\u0004 שלא רצה ליהנות כלל משל אחרים."],["\u0003אמר ר' זירא אמר שמואל: ליבן סכין\u0004 חימם אותה עד שנעשתה לוהטת \u0003ושחט בה\u0004 — \u0003שחיטתו כשרה,\u0004 ואין אומרים שהסימנים (הקנה והושט) נשרפו תחילה בחוד הסכין, ובכך נעשתה הבהמה טריפה עוד קודם שנגמרה שחיטתה. אלא \u0003חידודה\u0004 החיתוך שנעשה בחוד הסכין \u0003קודם\u0004 \u0003ל\u0004כויה שגורם \u0003ליבונה.\u0004 ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003צדדין\u0004 של הסכין שהם שורפים את צדדי מקום השחיטה! ומשיבים: \u0003בית השחיטה מירווח רווח\u0004 \u0005[נעשה מרווח],\u0006 שדפנות החתך מתרחקות זו מזו על ידי החיתוך, ואין הסכין שורפת את הצדדים.","ומעירים: דברי ר' זירא הובאו כדי לפתור שאלה אחרת ש\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים: \u0003ליבן שפוד\u0004 של מתכת \u0003והכה בו\u0004 אדם, ולאחר שנרפאה המכה עלה בו נגע צרעת, האם נגע זה \u0003משום\u0004 צרעת ה\u0003שחין נדון או משום\u0004 צרעת ה\u0003מכוה נדון?\u0004","ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה\u0006 להלכה\u0005]\u0006 אם הוא נדון משום שחין או מכוה \u0003—\u0004 \u0003לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 ברייתא\u0005]:\u0006 צרעת ה\u0003שחין ו\u0004צרעת ה\u0003מכוה מטמאין בשבוע אחד\u0004 של הסגר, ו\u0003בשני סימנין\u0004 — \u0003בשער לבן\u0004 שצומח בנגע, \u0003ובפסיון\u0004 (אם הנגע מתפשט), \u0003ולמה חלקן הכתוב\u0004 לשתי פרשיות נפרדות, אף שדינם שווה? \u0003לומר שאין מצטרפין זה עם זה\u0004 לטמא, ואם לא היה בכל אחד מהם שיעור נגע (שהוא כגודל גריס) אינו מיטמא.","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003איזהו שחין ואיזהו מכוה?\u0004 אם \u0003לקה\u0004 (הוכה, נפצע) \u0003בעץ,\u0004 או \u0003באבן,\u0004 או \u0003בגפת\u0004 (פסולת הזיתים), או \u0003בחמי טבריא\u0004 מי מעיינות חמים, \u0003ובכל דבר שלא בא מחמת האור\u0004 (האש), ומסבירה הגמרא: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003אבר מעיקרו\u0004 שכורה עופרת ממקומה, ופעמים היא לוהטת — הרושם הנשאר בעור \u0003זהו שחין. ואיזהו מכוה?\u0004 כל ש\u0003נכוה בגחלת, ברמץ, בסיד רותח, בגפסית רותח, ובכל דבר הבא מחמת האור,\u0004 ומסבירים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003חמי האור\u0004 (מים שנתחממו באש) — \u0003זו היא מכוה.\u0004","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003שחין ומכוה\u0004 באותו מקום, ועלה שם נגע — הולכים אחר האחרון, ולכן \u0003אם שחין קודם למכוה\u0004 — \u0003בטל\u0004 ה\u0003מכוה את השחין,\u0004 והנגע העולה באותו מקום נדון משום צרעת המכוה, \u0003ואם\u0004 ה\u0003מכוה קודמת לשחין\u0004 — \u0003בטל שחין את המכוה.\u0004","\u0003והכא\u0004 \u0005[וכאן],\u0006 שנשאלה השאלה האם נדון משום צרעת שחין או משום צרעת מכוה, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003כגון דהוה ביה\u0004 \u0005[שהיה בו]\u0006 שיעור \u0003חצי גריס\u0004 צרעת ה\u0003שחין מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003וליבן שפוד והכה בו, ונפק ביה\u0004 \u0005[ויצא בו]\u0006 \u0003חצי גריס אחר,\u0004 והשאלה היא:","\u0003מאי\u0004 \u0005[מה]\u0006 דינו? האם \u0003חבטא קדים\u0004 \u0005[החבטה קודמת\u0006 לכויה\u0005],\u0006 \u0003ואתי הבלא ומבטל ליה לחבטא\u0004 \u0005[ובא ההבל,\u0006 החום, \u0005ומבטל את החבטה],\u0006 \u0003והוה ליה\u0004 \u0005[והרי זה]\u0006 חצי גריס צרעת \u0003ה\u0004\u0003שחין ו\u0004חצי גריס צרעת ה\u0003מכוה,\u0004 \u0003ולא מצטרפין. או דלמא הבלא קדים\u0004 \u0005[שמא ההבל,\u0006 החום, \u0005קודם],\u0006 \u0003ואתי חבטא ומבטל ליה להבלא\u0004 \u0005[ובאה החבטה ומבטלת את החום],\u0006 \u0003והוה ליה\u0004 \u0005[והרי זה]\u0006 \u0003שחין ושחין, ומצטרף?\u0004","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ש\u0003אמר ר' זירא אמר שמואל: ליבן סכין ושחט בה\u0004 — \u0003שחיטתו כשירה,\u0004 מפני ש\u0003חידודה קודם לליבונה, אלמא חבטא קדים\u0004 \u0005[מכאן שהחבטה קודמת לחום]!\u0006 ומשיבים: אין מכאן הוכחה, ויש לומר כי \u0003חדוד\u0004 (חוד הסכין) \u0003שאני\u0004 \u0005[שונה],\u0006 שמפני שהוא חד — החיתוך קודם לכויה, ואין ללמוד מכאן למכה של שפוד.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לשאלה ממה ששנינו בברייתא: אם \u0003ליבן שפוד והכה בו,\u0004 ונרפא הפצע ועלה בו נגע — \u0003נדון משום מכות אש, אלמא חבטא קדים\u0004 \u0005[מכאן שהחבטה קודמת],\u0006 שהרי אנו הולכים אחר האחרון! ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 יש לומר \u0003דברזייה מיברז\u0004 \u0005[שנעץ אותו]\u0006 בבשר, ולא היכה בו, \u0003דהיינו\u0004 \u0005[שהוא אותו\u0006 דין\u0005]\u0006 שיש ב\u0003חדוד,\u0004 ואין מכאן ראיה לענין מכה סתם.","\u0003אמר רב נחמן אמר רבה בר אבוה: סכין של עבודה זרה\u0004 ששימשה לצורך עבודה זרה, והיא אסורה בהנאה — \u0003מותר לשחוט בה,\u0004 אבל \u0003אסור לחתוך בה בשר.\u0004 ומסבירים: \u0003מותר לשחוט בה\u0004 — משום ששחיטה בגדר \u0003מקלקל הוא,\u0004 שבחייה הבהמה שווה יותר, ונמצא שלא נהנה מן הסכין. \u0003ואסור לחתוך בה בשר\u0004 — משום שאחר השחיטה \u0003מתקן הוא,\u0004 שחותך אותה לחתיכות ראויות לשימוש.","\u0003אמר רבא: פעמים שהשוחט\u0004 בסכין של עבודה זרה \u0003אסור\u0004 — \u0003ב\u0004בהמה \u0003מסוכנת,\u0004 העומדת למות, שאם אינו שוחטה תמות מאליה, ויפסיד. \u0003ומחתך מותר\u0004 — \u0003באטמי דקיימין לקורבנא\u0004 \u0005[בירכים שעומדות למתנה]\u0006 לאדם חשוב, כמות שהן, ומי שחותך אותן לחתיכות קטנות מפסיד מערכן.","ומקשים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 ההלכה שאסור לחתוך בשר בסכין של עבודה זרה, לא משום איסור ההנאה, אלא \u0003משום שמנונית דאיסורא\u0004 \u0005[שמנונית של איסור]\u0006 הדבוקה בסכין!"],["ודוחים: כאן מדובר \u0003ב\u0004סכין \u0003חדשה\u0004 שעדיין לא השתמשו בה.","ותוהים: אם סכין \u0003חדשה\u0004 היא, הרי \u0003בין לר' ישמעאל בין לר' עקיבא\u0004 שנחלקו האם עבודה זרה נאסרת משעה שעשאה, או משעה שעובדים אותה, סכינים אלו רק \u0003משמשי עבודה זרה הן, ומשמשי עבודה זרה אינן אסורין\u0004 בהנאה \u0003עד שיעבדו\u0004 בהם לעבודה זרה! ומשיבים, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר במקרה \u0003דפסק ביה גווזא\u0004 \u0005[שחתך בה ענף]\u0006 \u0003לעבודה זרה,\u0004 שאין שם שמנונית, אבל כבר עבד בה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003ב\u0004סכין \u0003ישנה\u0004 ולאחר \u0003שליבנה באור\u0004 (באש), שלא נותרה עליה שמנונית.","\u0003אתמר\u0004 \u0005[נאמר]:\u0006 \u0003השוחט בסכין של גוים, רב אמר: קולף\u0004 את מקום השחיטה, ששם נגעה הסכין בבשר, ונבלע בו מן השמנונית האסורה שעל הסכין, \u0003ורבה בר בר חנה אמר:\u0004 רק \u0003מדיח\u0004 (רוחץ) את המקום. ומציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר\u0006 שבנושא \u0005זה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 רבה בר בר חנה, \u0005סבור]:\u0006 \u0003בית השחיטה צונן\u0004 הוא ואינו בולע, ולכן די לו בהדחה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רב, \u0005סבור]:\u0006 \u0003בית השחיטה רותח,\u0004 ולכן בולע?","ומשיבים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003בית השחיטה רותח הוא; מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003קולף\u0004 — \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן הדבר\u0005]\u0006 משום השמנונית שנבלעה בבית השחיטה. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003מדיח,\u0004 לדעתו, \u0003איידי דטרידי\u0004 \u0005[מתוך שטרודים,\u0006 עסוקים\u0005]\u0006 ה\u0003סימנין\u0004 כלומר, דופני בית השחיטה, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003דם\u0004 — \u0003לא בלעי\u0004 \u0005[אין\u0006 הם \u0005בולעים]\u0006 באותה שעה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003בית השחיטה צונן, מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003מדיח\u0004 — \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן הדבר\u0005],\u0006 שהרי הצונן אינו בולע. \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003קולף\u0004 — \u0003אגב דוחקא דסכינא בלע\u0004 \u0005[מתוך דוחק הסכין\u0006 — הבשר \u0005בולע]\u0006 את השמנונית שעליו.","\u0003סכין\u0004 ששחט בה בהמה שהיתה \u0003טריפה, פליגי בה\u0004 \u0005[חלוקים בכך]\u0006 \u0003רב אחא ורבינא\u0004 כיצד להכשיר סכין זו, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 מגעילים את הסכין \u0003ב\u0004מים \u0003חמין, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: בצונן.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]:\u0006 \u0003אפילו בצונן. ואי איכא בליתא דפרסא למיכפריה\u0004 \u0005[ואם יש\u0006 מטלית \u0005ב\u0006\u0005לויה של וילון לקנח אותו]\u0006 \u0003לא צריך\u0004 אפילו זה.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ולמי שאומר]\u0006 שצריך להגעיל \u0003בחמין\u0004 סכין ששחט בה טריפה, \u0003מאי טעמא\u0004 \u0005[מה טעם הדבר]?\u0006 אם \u0003משום דקא בלעה איסורא\u0004 \u0005[שהיא בולעת מן האיסור]\u0006 בשעת שחיטה — הרי \u0003דהיתירא נמי בלעה\u0004 \u0005[\u0006סכין \u0005של היתר,\u0006 ששוחט בה בהמה כשרה, \u0005גם כן בולעת]\u0006 שמנונית אבר מן החי, קודם שנגמרה השחיטה, ותיאסר! ומשיבים: שמנונית של \u0003אבר מן החי אימת בלעה\u0004 \u0005[מתי\u0006 יש לחשוש שהסכין \u0005בולעת]\u0006 — \u0003לכי חיימא\u0004 \u0005[כאשר היא נעשית חמה],\u0006 ואולם \u0003אימת קא חיימא\u0004 \u0005[מתי היא נעשית חמה]\u0006 — \u0003לכי גמרה\u0004 \u0005[כאשר נגמרת]\u0006 ה\u0003שחיטה,\u0004 והרי \u0003ההיא שעתא היתירא הוה\u0004 \u0005[באותה שעה\u0006 כבר \u0005היתר הוא],\u0006 שכבר אין זה עוד אבר מן החי.","\u0003אמר רב יהודה אמר רב, הטבח\u0004 (השוחט) \u0003צריך שלשה סכינין: אחת ששוחט בה, ואחד שמחתך בה בשר, ואחד שמחתך בה חלבים,\u0004 שאי אפשר לחתוך בה בשר לאחר שחתך בה חלבים אסורים באכילה, משום שמנונית החלב שנשארה עליה.","ושואלים: \u0003וליתקן ליה חדא\u0004 \u0005[ושיתקן לו סכין אחת]\u0006 לחיתוך, \u0003וליחתוך\u0004 \u0005[ושיחתוך]\u0006 \u0003בה\u0004 קודם \u0003בשר והדר ליחתוך\u0004 \u0005[ואחר כך יחתוך]\u0006 \u0003בה חלבים!\u0004 ומשיבים: \u0003גזירה\u0004 היא \u0003שמא יחתוך\u0004 בה \u0003חלבים ואחר כך בשר,\u0004 ויישאר החלב דבוק לבשר, ויידבק בבשר. ושואלים: \u0003השתא נמי מיחלף ליה\u0004 \u0005[עכשיו גם כן,\u0006 שיש לו שתים, נחשוש שמא \u0005יתחלפו לו]!\u0006 ומשיבים: \u0003כיון דאצרכינהו תרי\u0004 — \u0003אית ליה היכרא\u0004 \u0005[כיון שהצריכוהו שתים —\u0006 \u0005יש לו היכר],\u0006 וייחד כל אחת לעניינה.","\u0003ואמר רב יהודה אמר רב: הטבח צריך שני כלים של מים, אחד שמדיח בו בשר, ואחד שמדיח בו חלבים,\u0004 שאם ידיח בשר לאחר חלבים יידבק בבשר מן החלב האסור. ושואלים: \u0003וניתקן ליה חדא\u0004 \u0005[ושיתקין לו רק כלי אחד],\u0006 \u0003ונדיח\u0004 \u0005[ושידיח]\u0006 \u0003בו בשר והדר נדיח\u0004 \u0005[ואחר כך שידיח]\u0006 \u0003בו חלבים!\u0004 ומשיבים: \u0003גזירה שמא ידיח\u0004 בו \u0003חלבים ואחר כך בשר.\u0004 ושואלים: \u0003השתא נמי מיחלפי ליה\u0004 \u0005[עכשיו גם כן\u0006 יש לחשוש שמא \u0005יתחלפו לו]\u0006 הכלים, וידיח בשר בכלי שהיה בו חלב! ומשיבים: \u0003כיון דאצרכיניה תרתי אית ליה היכרא\u0004 \u0005[שהצריכו אותו שני\u0006 כלים \u0005יש לו היכר]\u0006 ויזכור.","\u0003אמר אמימר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב פפא: לא ליסחוף איניש כפלי עילוי בישרא\u0004 \u0005[לא יניח אדם את הכסלים,\u0006 בשר המתניים של בהמה, \u0005על גבי בשר אחר],\u0006 כאשר חלב הכסלים האסור למטה, משום \u0003דדאיב תרבא ובלע בישרא\u0004 \u0005[שזב החלב\u0006 \u0005ובולע\u0006 אותו \u0005הבשר\u0006 שהניחו עליו את הכסלים\u0005].\u0006","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאתה חושש שהחלב זב ונבלע בבשר, \u0003כי תריצי נמי דאיב תרבא ובלע בשרא\u0004 \u0005[כאשר הכסלים מונחים כדרכם גם כן,\u0006 כשהחלב מלמעלה, \u0005זב החלב ובולע בשר\u0006 הכסלים עצמו מן החלב\u0005]!\u0006 ומשיבים: \u0003קרמא מפסיק מתתאי\u0004 \u0005[הקרום\u0006 שבין החלב לבשר \u0005מפסיק מלמטה].\u0006 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר,"],["\u0003מעילאי נמי קרמא איכא\u0004 \u0005[מלמעלה,\u0006 מצידו החיצוני של החלב, \u0005גם כן\u0006 הרי \u0005יש קרום],\u0006 שכל חלב מכוסה בקרום דק, וכשמניח את הכסלים על בשר הוא מונע מן החלב שיזוב על הבשר! ומשיבים: קרום זה, \u0003איידי דממשמשא ידא דטבחא מפתת\u0004 \u0005[מתוך שממשמשת בו יד הטבח הוא מתפורר],\u0006 והחלב זב על הבשר שתחתיו.","\u0003ואמר רב יהודה אמר רב, תלמיד חכם צריך שילמוד\u0004 לאמן ידיו ל\u0003שלשה דברים: כתב,\u0004 שיוכל לכתוב את הדברים הצריכים כתיבה, \u0003שחיטה, ומילה. ורב חנניא בר שלמיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמר: אף\u0004 צריך ללמוד לעשות \u0003קשר של תפילין, ו\u0004לומר \u0003ברכת חתנים\u0004 בעל פה ובנעימה, \u0003ו\u0004לקשור \u0003ציצית.\u0004 ומעירים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 רב יהודה, מדוע אינו מונה את אלה? הוא סבור ש\u0003הני שכיחן\u0004 \u0005[אלה מצויים\u0006 יותר\u0005],\u0006 ואין צורך ללימוד מיוחד כדי לדעת איך הם נעשים.","\u0003ואמר רב יהודה אמר שמואל: כל טבח\u0004 (שוחט) \u0003שאינו יודע הלכות שחיטה אסור לאכול משחיטתו,\u0004 כששחט בינו לבין עצמו. \u0003ואלו הן הלכות שחיטה,\u0004 כלומר, דברים הפוסלים את השחיטה: \u0003שהייה, דרסה, חלדה, הגרמה, ועיקור.\u0004","ותוהים: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו]\u0006 ברשימה זו? והרי \u0003כולהו תנינהו\u0004 \u0005[את כולם\u0006 כבר \u0005שנינו]\u0006 במשנה במסכת זו, ובוודאי שאם אינו יודע אותן אי אפשר לאכול משחיטתו! ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 אלא במקרה \u0003ששחט לפנינו שתים ושלש פעמים, ושחט שפיר\u0004 \u0005[יפה];\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מדאידך\u0004 \u0005[מכיון שאת האחרות]\u0006 \u0003שחט שפיר\u0004 \u0005[יפה],\u0006 \u0003האי נמי\u0004 \u0005[זו גם כן]\u0006 ששחט בינו לבין עצמו \u0003שחט שפיר\u0004 \u0005[יפה],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003כיון דלא גמר\u0004 \u0005[שלא למד],\u0006 \u0003זימנין דשהי ודריס ולא ידע\u0004 \u0005[פעמים שהוא שוהה\u0006 או \u0005דורס ואינו יודע]\u0006 שקלקל.","\u0003ואמר רב יהודה אמר שמואל: הטבח צריך שיבדוק בסימנים\u0004 (קנה וושט) \u0003לאחר שחיטה,\u0004 שמא לא שחט את רוב הסימן, ושחיטה פסולה היא. \u0003אמר רב יוסף: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 במשנתנו דבר זה, \u0003ר' שמעון אומר: אם שהה\u0004 השוחט \u0003כדי ביקור\u0004 (בדיקה); \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה היא \u0003כדי ביקור\u0004 של \u0003סימנין?\u0004 ומכאן שצריך לבדוק!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: לא,\u0004 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן\u0004 בהסבר הדבר: \u0003כדי ביקור חכם,\u0004 כדי הזמן שהולך להראות לחכם את הסכין, כפי שתיקנו חכמים (להלן י,ב). אמר לו: \u0003אם כן, נתת דברים לשיעורים,\u0004 שפעמים החכם קרוב פעמים רחוק, ואין זה שיעור מוגדר! \u0003אלא\u0004 הכוונה היא: \u0003כדי ביקור טבח חכם,\u0004 כלומר, כדי משך הזמן שלוקח לטבח מומחה (שאינו צריך ללכת לחכם) לבדוק את סכינו. ומכל מקום אין ראיה מכאן שצריך לבדוק את הסימנים.","ושואלים: אם \u0003לא בדק\u0004 את הסימנים כדברי רב יהודה, ואין אפשרות לברר את הדבר, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? \u0003ר' אליעזר בן אנטיגנוס משום\u0004 (בשם) \u0003ר' אלעזר בר' ינאי אמר:\u0004 דין \u0003טרפה\u0004 יש לבהמה \u0003ו\u0004היא \u0003אסורה באכילה,\u0004 ואילו \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 שהבהמה נחשבת \u0003נבלה ו\u0004אף \u0003מטמאה במשא.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]\u0006 מה היסוד העקרוני של מחלוקת זו? ומשיבים: \u0003ב\u0004פירוש דברי \u0003רב הונא,\u0004 ש\u0003אמר: בהמה בחייה בחזקת איסור עומדת,\u0004 שהרי אסור לאכול את בשרה בחייה, ולפיכך אם יש לך ספק אם נשחטה כראוי הריהי אסורה, כחזקתה, \u0003עד שיודע לך במה נשחטה,\u0004 האם נשחטה כראוי. אבל כאשר \u0003נשחטה\u0004 כראוי, ויש לך ספק האם היתה טריפה — \u0003הרי היא בחזקת היתר עד שיודע לך במה נטרפה.\u0004","ובכך נחלקו, \u0003מר סבר\u0004 \u0005[חכם זה\u0006 שבברייתא \u0005סבור]:\u0006 בהמה זו שלא בדק בה את הסימנים לאחר שחיטה, ואינך יודע אם נשחטה כראוי — \u0003בחזקת איסור קיימא\u0004 \u0005[עומדת],\u0006 \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 \u0003מתה היא\u0004 לפנינו, ויש לדון עליה ככל בהמה שלא נשחטה כראוי, והיא נבלה, ומטמאה במשא. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר בן אנטיגנוס, \u0005סבור]:\u0006 \u0003בחזקת איסור אמרינן\u0004 \u0005[אומרים אנו\u0006 שנשארה\u0005],\u0006 אבל \u0003בחזקת טומאה לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 שהרי לא היתה לה חזקת טומאה לפני כן.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה הלכה, \u0003אמר רב הונא: בהמה בחייה בחזקת איסור עומדת עד שיודע לך במה נשחטה. נשחטה\u0004 — \u0003בחזקת היתר עומדת עד שיודע לך במה נטרפה.\u0004 ושואלים: מדוע אמר נשחטה \"בחזקת היתר עומדת\"? \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 \u0003נשחטה\u0004 — \u0003הותרה!\u0004 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו],\u0006 \u0003דאף על גב דאיתיליד בה ריעותא\u0004 \u0005[שאף על פי שנולד בה פגם\u0006 המעורר ספק\u0005],\u0006 עדיין עומדת היא בחזקת היתר.","\u0003כדבעא מיניה\u0004 \u0005[כמו ששאל אותו]\u0006 \u0003ר' אבא מרב הונא:\u0004 אם \u0003בא זאב ונטל בני מעים\u0004 של בהמה שנשחטה \u0003מהו\u0004 דינה?","ותמהים: \u0003נטל?! הא ליתנהו\u0004 \u0005[הרי אינם],\u0006 ומה יש לשאול בזה! \u0003אלא\u0004 השאלה היא בכגון ש\u0003נקב בני מעיים, מהו?\u0004 ותמהים: אם הזאב \u0003נקב?! הא קא חזינן דהוא נקבינהו\u0004 \u0005[הרי\u0006 אנו \u0005רואים שהוא ניקב אותם]!\u0006 \u0003אלא\u0004 הכוונה היא: אם \u0003נטלן והחזירן כשהן נקובין, מהו? מי חיישינן\u0004 \u0005[האם חוששים אנו]\u0006 \u0003שמא במקום נקב\u0004 שכבר היה בה \u0003נקב,\u0004 והיתה הבהמה טריפה מתחילה, \u0003או לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין חוששין שמא במקום נקב נקב,\u0004 אלא סומכים אנו על חזקת ההיתר.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו: \u0003ראה צפור המנקר בתאנה, ועכבר המנקר באבטיחים,\u0004"],["\u0003חוששין שמא במקום נקב\u0004 של נחש \u0003נקב\u0004 הציפור או העכבר, ואסור לאוכלם מחשש סכנה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003מי קא מדמית איסורא לסכנתא\u0004 \u0005[האם אתה מדמה איסור לסכנה]?\u0006 \u0003סכנה שאני\u0004 \u0005[שונה]\u0006 וצריך לחשוש לה במקום ספק. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מאי שנא ספק סכנתא לחומרא\u0004 \u0005[במה שונה ספק סכנה\u0006 שהולכים בו \u0005להחמיר]?\u0006 \u0003ספק איסורא נמי לחומרא\u0004 \u0005[ספק איסור גם כן\u0006 נלך בו \u0005להחמיר]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ו\u0004כי \u0003לא שאני\u0004 \u0005[שונה]\u0006 הדין \u0003בין איסורא לסכנתא\u0004 \u0005[איסור לסכנה]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אילו ספק טומאה ברשות הרבים\u0004 — \u0003ספיקו טהור, ואילו ספק מים מגולין\u0004 כלומר, מים שהיו מגולים בלילה, שיש ספק שמא הטיל בה נחש את ארסו ויש סכנה בשתייתם — \u0003אסורין!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003התם\u0004 \u0005[שם]\u0006 ספק טומאה ברשות הרבים הוא דין מיוחד, שכן \u0003הלכתא גמירי לה\u0004 \u0005[הלכה אנו למדים אותה]\u0006 \u0003מ\u0004דין \u0003סוטה\u0004 ששהתה בסתר עם איש זר ונאסרה מספק שמא נבעלה לו ונטמאה, (במדבר ה, יג) \u0003מה סוטה\u0004 — \u0003ברשות היחיד\u0004 הדברים אמורים, שהרי רשות הרבים אינה מקום סתר, \u0003אף\u0004 ספק \u0003טומאה\u0004 — \u0003ברשות היחיד\u0004 הוא טמא, ולא ברשות הרבים. אבל בכל ספק איסור הולכים אנו להחמיר, כמו בספק סכנה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 גם \u0003רב שימי\u0004 על דברי רבא ממה ששנינו: היה \u0003שרץ\u0004 מת \u0003בפי חולדה, ו\u0004אותה \u0003חולדה\u0004 היתה \u0003מהלכת על גבי ככרות של תרומה, ספק נגע\u0004 השרץ בככרות \u0003ספק לא נגע\u0004 — הרי \u0003ספיקו טהור,\u0004ואפילו ברשות היחיד, \u0003ואילו ספק מים מגולין\u0004 — \u0003אסורין!\u0004","ומשיבים: \u0003התם נמי הלכתא גמירי לה\u0004 \u0005[שם גם כן\u0006 \u0005הלכה אנו למדים אותה]\u0006 \u0003מסוטה:\u0004 \u0003מה סוטה\u0004 היא \u0003דבר שיש בה דעת לישאל,\u0004 שיש אפשרות לשאול אותה אם נטמאה — \u0003אף הכא נמי\u0004 \u0005[אף כאן גם כן]\u0006 ספק טומאה ברשות היחיד טמא רק ב\u0003דבר שיש בו דעת לישאל,\u0004 ומה שאין בו דעת להישאל, וכגון הככרות שספק לנו אם נטמאו — ספיקו טהור, אבל בספק איסור יש להחמיר.","\u0003אמר רב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת שסכנה חמורה מאיסור, ממה ששנינו: \u0003צלוחית\u0004 ובה מי חטאת \u0003שהניחה מגולה ובא ומצאה מכוסה\u0004 — הרי היא \u0003טמאה, שאני אומר: אדם טמא נכנס לשם וכיסה\u0004 אותה, ואגב כן טימא אותה ואת המים שבתוכה.","\u0003הניחה מכוסה ובא ומצאה מגולה, אם\u0004 היא במקום ש\u0003יכולה חולדה לשתות ממנה, או נחש לדברי רבן גמליאל, או\u0004 שיש לחשוש \u0003שירד בה טל בלילה\u0004 — הרי זו \u0003פסולה,\u0004 שאין להזות ממי החטאת שבתוכה על טמא מת, שמא נתערב בהם רוק החולדה או טל, שאינם כשרים להזאה, ופסלוה, אבל אינה טמאה.","\u0003ואמר רבי יהושע בן לוי: מה טעם\u0004 אין חוששים שאדם טמא גילה אותה ונטמאה?"],["\u0003מפני שדרכן של שרצים לגלות\u0004 כלי כדי לשתות ממנו, ולכן אנו תולים ששרץ או אדם טהור גילו את הצלוחית, ולא אדם טמא. ודווקא במקרה שהניחה מגולה ומצאה מכוסה אנו חוששים שאדם טמא הוא שכיסה אותה, הואיל \u0003ואין דרכן\u0004 של שרצים \u0003לכסות.\u0004 הרי שלענין איסור (וטומאה) יש מקרים בהם אנו מקילים בספק.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש לדייק מן הברייתא כך: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא] במקרה ש\u0003הניחה מגולה ובא ומצאה מכוסה,\u0004 או שהניחה \u0003מכוסה ובא ומצאה מגולה,\u0004 הריהי טמאה או פסולה, \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003מצאה כמה שהניחה\u0004 — \u0003לא טומאה איכא\u0004 \u0005[יש כאן]\u0006 \u0003ולא פסולה איכא\u0004 \u0005[יש כאן].\u0006","\u0003ואילו\u0004 לענין סכנה \u0003ספק מים מגולים\u0004 \u0003אסורין\u0004 בכל אופן. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 איפוא כי \u0003חמירא סכנתא מאיסורא\u0004 \u0005[חמורה הסכנה מהאיסור].\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","אגב כך מביאים מה ש\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת תרומות, \u0003שלשה משקין אסורין משום גלוי: מים, ויין, וחלב.\u0004 ו\u0003כמה ישהו\u0004 כשהם מגולים \u0003ויהיו אסורין\u0004 — \u0003כדי\u0004 הזמן \u0003שיצא הרחש\u0004 (נחש) \u0003ממקום קרוב וישתה. וכמה\u0004 הוא \u0003מקום קרוב? אמר ר' יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה:\u0004 אפילו \u0003כדי שיצא מתחת אוזן כלי וישתה.\u0004","ותוהים: כדי שיצא ו\u0003ישתה? הא קא חזי ליה\u0004 \u0005[הרי הוא רואה אותו]\u0006 שותה, ואין כאן ספק אלא ודאי! \u0003אלא\u0004 הכוונה היא לשיעור זמן כדי ש\u0003ישתה ויחזור לחורו,\u0004 שמא שתה ולא ראהו.","ושבים לדון בספיקות שמתעוררים לאחר השחיטה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה הבאה: \u0003השוחט בסכין\u0004 בדוקה \u0003ו\u0004לאחר זמן \u0003נמצאת\u0004 הסכין \u0003פגומה,\u0004 \u0003אמר רב הונא: אפילו שיבר בה\u0004 בסכין \u0003עצמות כל היום\u0004 לאחר השחיטה — \u0003פסולה\u0004 הבהמה לאכילה, ומדוע? \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא בעור\u0004 הצואר \u0003נפגמה\u0004 הסכין, בתחילת השחיטה, ובגלל הפגימה נקרעו הסימנים (הקנה והושט) ושחיטה פסולה היא. \u0003ורב חסדא אמר: כשרה,\u0004 \u0003שמא בעצם\u0004 ששיבר לאחר השחיטה \u0003נפגמה\u0004 הסכין.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003רב הונא כשמעתיה\u0004 \u0005[\u0006הולך \u0005כשיטתו]\u0006 לעיל (ט,א), שבהמה הריהי בחזקת איסור עד שייוודע לך כיצד נשחטה, \u0003אלא רב חסדא\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הכשיר? ומשיבים, \u0003אמר לך\u0004 \u0005[יכול לומר לך]:\u0006 \u0003עצם\u0004 — \u0003ודאי פוגם\u0004 סכין, \u0003עור\u0004 — \u0003ספק פוגם ספק לא פוגם,\u0004 ואם כן \u0003הוי\u0004 \u0005[הרי זה]\u0006 \u0003ספק וודאי, ואין ספק מוציא מידי ודאי.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 על רב חסדא \u0003לסיועיה\u0004 \u0005[לסייע]\u0006 \u0003ל\u0004שיטת \u0003רב הונא,\u0004 ממה ששנינו: מי ש\u0003טבל\u0004 במקוה \u0003ועלה, ו\u0004לאחר זמן \u0003נמצא עליו דבר חוצץ, אף על פי שנתעסק באותו המין כל היום כולו\u0004 לאחר הטבילה — \u0003לא עלתה לו טבילה, עד שיאמר: ברי לי שלא היה עלי\u0004 הדבר החוצץ \u0003קודם לכן,\u0004 לפני הטבילה. \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003ודאי טבל,\u0004 ו\u0003ספק\u0004 אם \u0003הוה עליה\u0004 \u0005[היה עליו]\u0006 הדבר החוצץ לפני הטבילה \u0003ספק לא הוה עליה\u0004 \u0005[לא היה עליו],\u0006 \u0003וקאתי\u0004 \u0005[ובא]\u0006 \u0003ספק ומוציא מידי ודאי!\u0004","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דאיכא למימר\u0004 \u0005[שיש מקום לומר]:\u0006 \u0003העמד\u0004 את האיש ה\u0003טמא על חזקתו\u0004 שהוא טמא, \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\u0003לא טבל\u0004 כראוי.","ומקשים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בענין הסכין יש לומר: \u0003העמד בהמה על חזקתה,\u0004 שהיא בחזקת איסור עד שייוודע במה נשחטה, \u0003ואימר\u0004 \u0005[ואמור]\u0006 ש\u0003לא נשחטה\u0004 כראוי! ומשיבים: אינך יכול לומר זאת, ש\u0003הרי\u0004 היא \u0003שחוטה לפניך,\u0004 ואין בה פגם, ורוב הבהמות השחוטות כשרות הן","\u0003.\u0004 ומקשים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003הרי\u0004 אדם ש\u0003טבל לפניך!\u0004 ומשיבים: \u0003הא איתילידא ביה ריעותא\u0004 \u0005[הרי נולדה בו ריעות,\u0006 פגם\u0005],\u0006 שנמצא עליו דבר חוצץ.","ומקשים: \u0003הכא נמי איתילידא בה ריעותא\u0004 \u0005[כאן גם כן,\u0006 בבהמה, \u0005נולדה בה ריעות],\u0006 שיש פגימה בסכין שנשחטה בה! ומשיבים: בכל זאת יש לחלק, ה\u0003סכין איתרעאי\u0004 \u0005[הורעה],\u0006 אבל ה\u0003בהמה\u0004 עצמה \u0003לא איתרעאי\u0004 \u0005[לא הורעה],\u0006 ואותה אנו באים להכשיר.","עוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב חסדא ממה ששנינו בברייתא: עוף שנשחט בו אחד מן הסימנים (הקנה או הוושט) שחיטתו כשרה, ולכן אם \u0003שחט את הושט ואחר כך נשמטה\u0004 (נעקרה ממקומה) \u0003הגרגרת\u0004 — \u0003כשרה,\u0004 אבל אם \u0003נשמטה הגרגרת ואחר כך שחט את הושט\u0004 — \u0003פסולה,\u0004 מפני שכשנשמטה הגרגרת נעשה העוף טריפה.","\u0003שחט את הושט ונמצא הגרגרת שמוטה, ואינו יודע אם קודם שחיטה נשמטה אם לאחר שחיטה נשמטה\u0004 — \u0003זה היה מעשה\u0004 שנשאלו עליו חכמים, \u0003ואמרו: כל ספק בשחיטה\u0004 — \u0003פסול.\u0004","ומציעים: הלשון הכללית \u0003\"כל ספק בשחיטה\" לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 היא באה? \u0003לאו לאתויי כהאי גוונא\u0004 \u0005[האם לא להביא\u0006 גם מקרה \u0005כמו זה\u0006 שלנו\u0005],\u0006 שיש ספק בסכין האם נפגמה לפני השחיטה או לאחריה? ודוחים: \u0003לא, לאתויי\u0004 \u0005[להביא]\u0006 \u0003ספק שהה\u0004 באמצע השחיטה, או \u0003ספק דרס\u0004 בסכין על הסימנים וכך שחט, ששני אלה פוסלים את השחיטה."],["ומקשים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]?\u0006 מדוע מחלקים? הרי שניהם בגדר ספק! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 כשספק אם שהה או ספק דרס — \u0003איתילידא בה ריעותא\u0004 \u0005[נולדה בה ריעות,\u0006 פגם\u0005]\u0006 \u0003בבהמה\u0004 עצמה, \u0003הכא\u0004 \u0005[כאן]\u0006 ה\u0003סכין איתרעאי\u0004 \u0005[הורעה,\u0006 נפל בה פגם\u0005],\u0006 ה\u0003בהמה לא איתרעאי\u0004 \u0005[לא הורעה].\u0006","ומסכמים: \u0003והילכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב הונא,\u0004 שסכין שנמצאה פגומה פוסלת את השחיטה — \u0003כשלא שיבר בה עצם\u0004 לאחר שחיטה, ויש מקום לחשש שמא בעור נפגמה מתחילה. \u0003והילכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב חסדא\u0004 שאין חוששים שנפגמה מתחילה בעור — \u0003כששיבר בה עצם\u0004 לאחר מכן. ושואלים: \u0003מכלל\u0004 שפסקו הלכה כרב הונא כשלא שיבר בה עצם, אתה למד ש\u0003רב חסדא\u0004 חולק ומכשיר \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא שיבר בה עצם,\u0004 ואינו חושש שנפגמה בעור? \u0003אלא במאי איפגים\u0004 \u0005[במה נפגמה]\u0006 הסכין אם לא בעור? ומשיבים: \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003בעצם\u0004 של ה\u0003מפרקת\u0004 (הצואר) של אותה בהמה \u0003איפגים\u0004 \u0005[נפגמה],\u0006 שהמשיך בחיתוך הצואר עד שהגיע למפרקת.","עוד מסופר בענין זה: \u0003הוה עובדא וטרף\u0004 \u0005[היה מעשה והטריף]\u0006 \u0003רב יוסף עד תליסר חיותא\u0004 \u0005[עד שלוש עשרה בהמות],\u0006 כאשר מצאו שהסכין פגומה לאחר שחיטת האחרונה. ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 פסק כן? האם \u0003כ\u0004דעת \u0003רב הונא, ואפילו בקמייתא\u0004 \u0005[ב\u0006בהמה ה\u0005ראשונה]\u0006 הטריף, מחשש שמא בעור נפגמה הסכין קודם השחיטה? ודוחים: \u0003לא,\u0004 יש לומר שפסק \u0003כרב חסדא, ו\u0004הטריף את כולן \u0003לבר מקמייתא\u0004 \u0005[חוץ מן\u0006 הבהמה \u0005הראשונה],\u0006 שלשיטת רב חסדא תולים את הפגימה במפרקת הבהמה, ולא בעור.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 תפרש שרב יוסף הטריף את כולן ואף את הראשונה, \u0003ו\u0004\u0003כ\u0004דעת \u0003רב הונא\u0004 דווקא. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003כ\u0004דעת \u0003רב חסדא, מכדי מתלא תלינן\u0004 \u0005[הואיל\u0006 ולשיטתו \u0005אנו תולים\u0006 במפרקת להקל\u0005],\u0006 \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין לנו\u0005]\u0006 ש\u0003בעצם\u0004 ה\u0003מפרקת דקמייתא איפגים\u0004 \u0005[של הראשונה נפגם]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003בעצם\u0004 ה\u0003מפרקת דבתרייתא איפגים\u0004 \u0005[של\u0006 האחרונה נפגם]!","ועוד בענין זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: רב כהנא מצריך בדיקותא\u0004 \u0005[בדיקה]\u0006 של הסכין \u0003בין כל חדא וחדא\u0004 \u0005[אחת ואחת]\u0006 מן הבהמות ששוחט. ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 פסק? האם \u0003כ\u0004דעת \u0003רב הונא, ולמיפסל קמייתא\u0004 \u0005[ולפסול את הראשונה]\u0006 ששחט זה עתה, אם תימצא הסכין פגומה? ודוחים: \u0003לא,\u0004 אפשר לומר שפסק \u0003כ\u0004שיטת \u0003רב חסדא,\u0004 שתולה את הפגם בעצם המפרקת, \u0003ו\u0004לדעתו יש לבדוק את הסכין כדי \u0003לאכשורי\u0004 \u0003בתרייתא\u0004 \u0005[להכשיר את הבאה אחריה].\u0006","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שמדובר בבדיקה שלפני שחיטה, \u0003תיבעי נמי\u0004 \u0005[תצטרך גם כן]\u0006 הסכין \u0003בדיקת חכם,\u0004 שהצריכו חכמים את השוחט להראות סכינו לחכם לפני שחיטה! ודוחים: לשם זה אין צורך להראות את הסכין לחכם, שהרי \u0003עד אחד\u0004 (ובענייננו, השוחט) \u0003נאמן באיסורין.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מעיקרא נמי\u0004 \u0005[מתחילה גם כן],\u0006 בבהמה הראשונה ששוחט, \u0003לא\u0004 יראה את הסכין לחכם! ומשיבים, \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רבי יוחנן: לא אמרו להראות סכין לחכם אלא מפני כבודו של חכם,\u0004 ולא משום שאין סומכים על השוחט, וכיון שחלקו כבוד לחכם בתחילת השחיטה — שוב אין צורך בכך.","אגב דברי רב הונא שבהמה בחזקת איסור עומדת, ולכן יש להחמיר כשיש ספק אם נשחטה כראוי, שואלים: \u0003מנא הא מלתא דאמור רבנן\u0004 \u0005[מנין,\u0006 מהיכן בתורה נלמד \u0005דבר זה שאמרו חכמים]\u0006 \u0003אוקי מילתא אחזקיה\u0004 \u0005[העמד דבר על חזקתו]?\u0006","\u0003אמר רבי שמואל בר נחמני אמר ר' יונתן, אמר קרא\u0004 \u0005[הכתוב]\u0006 בצרעת הבתים כי לאחר שהכהן רואה את הנגע \u0003\"ויצא הכהן מן הבית אל פתח הבית והסגיר את הבית שבעת ימים\"\u0004 (ויקרא יד, לח). ויש לשאול: איך הוא יכול להסגיר את הבית? \u0003דלמא אדנפיק ואתא בצר ליה שיעורא\u0004 \u0005[שמא עד שהוא יוצא ובא\u0006 מן הבית \u0005נחסר לו שיעור]\u0006 הנגע, קודם שהסגיר את הבית, והוא טהור! \u0003אלא לאו משום דאמרינן אוקי אחזקיה\u0004 \u0005[האם לא משום שאנו אומרים העמד\u0006 דבר \u0005על חזקתו]?\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אחא בר יעקב: ודילמא\u0004 \u0005[ושמא]\u0006 מדובר \u0003כגון שיצא דרך אחוריו\u0004 (כשהוא הולך אחורנית), \u0003דקא חזי ליה כי נפק\u0004 \u0005[שהוא רואה אותו,\u0006 את הנגע, \u0005בשעה שהוא יוצא]\u0006 שהוא עומד בעינו, ורק באופן זה יכול להסגיר אותו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי, שתי תשובות בדבר\u0004 להוכיח שלא כדבריך: \u0003חדא\u0004 \u0005[אחת],\u0006 שאינו יכול לעשות כן, שהרי \u0003יציאה דרך אחוריו לא שמה\u0004 \u0005[אינה נקראת]\u0006 \u0003יציאה\u0004 בכתוב, ולא מתקיים בכך הכתוב \"ויצא מן הבית\". \u0003ועוד,\u0004 אם נמצא הנגע \u0003אחורי הדלת מאי איכא למימר\u0004 \u0005[מה אתה יכול לומר]?\u0006 הרי אינו יכול לראותו גם אם יוצא דרך אחוריו! \u0003וכי תימא דפתח ביה כוותא\u0004 \u0005[ואם תאמר שפותח בו חלון]\u0006 בדלת, כדי שיוכל לראות את הנגע בשעה שהוא יוצא — \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003בית אפל\u0004 שהיה בו חשש צרעת, \u0003אין פותחין בו חלונות לראות את נגעו!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לאביי: \u0003דקאמרת\u0004 \u0005[\u0006מה \u0005שאתה אומר]\u0006 ש\u0003יציאה דרך אחוריו לא שמה יציאה\u0004 — אין זה נכון, \u0003כהן גדול\u0004 כשהוא יוצא מקודש הקדשים \u0003ביום הכפורים יוכיח, דכתיב ביה\u0004 \u0005[שנאמרה בו]\u0006 לשון \u0003יציאה\u0004 (ויקרא טז, יח), \u0003ותנן\u0004 \u0005[ושנינו]:\u0006 \u0003יצא\u0004 הכהן \u0003ובא לו דרך כניסתו,\u0004 כלומר, אחורנית כשפניו לקודש, כדרך שנכנס. \u0003ודקאמרת\u0004 \u0005[ו\u0006מה \u0005שאתה אומר]:\u0006 \u0003בית אפל אין פותחין בו חלונות לראות את נגעו\u0004 — \u0003הני מילי היכא דלא איתחזק\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום שלא הוחזק]\u0006 כלל בנגע, ולכן אין פותחים חלונות כדי למצוא בו נגע, \u0003אבל היכא דאיתחזק\u0004 — \u0003איתחזק\u0004 \u0005[במקום ש\u0006כבר \u0005הוחזק,\u0006 שיש בו נגע — \u0005הוחזק],\u0006 ואז ניתן לפתוח חלון כדי לראותו.","ומעירים: \u0003תניא\u0004 \u0005[שנויה ברייתא]\u0006 ש\u0003לא כ\u0004דעת \u0003רב אחא בר יעקב,\u0004 שהציע להעמיד את הכתוב בכהן ההולך דרך אחוריו. נאמר \u0003\"ויצא הכהן מן הבית\"\u0004 (ויקרא יד, לא) — \u0003יכול ילך לתוך ביתו ו\u0004שם \u0003יסגיר\u0004 את הבית? \u0003תלמוד לומר: \"אל פתח הבית\"\u0004 (שם) — הבית שנראה בו הנגע;","\u0003אי\u0004 \u0005[אם]\u0006 נאמר \u0003\"פתח הבית\", יכול יעמוד\u0004 הכהן \u0003תחת המשקוף\u0004 של פתח הבית \u0003ויסגיר? תלמוד לומר:\u0004 \"ויצא \u0003מן הבית\"\u0004 — \u0003עד שיצא מן הבית כולו, הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 הוא עושה? \u0003עומד\u0004 מחוץ לבית המנוגע \u0003בצד המשקוף ומסגיר.\u0004","\u0003ומנין שאם הלך\u0004 הכהן \u0003לתוך ביתו והסגיר, או שעמד בתוך הבית\u0004 המנוגע \u0003והסגיר, ש\u0004בדיעבד \u0003הסגרו מוסגר? תלמוד לומר: \"והסגיר את הבית\", מכל מקום.\u0004 הרי שהסגרו הסגר למרות שאינו רואה את הנגע, ומעמידים דבר על חזקתו!","ומעירים: \u0003ורב אחא בר יעקב\u0004 מעמיד ברייתא זו לשיטתו"],["\u0003כגון דקיימי דרא דגברי ואמרי\u0004 \u0005[שעומדת שורה של אנשים\u0006 מן הבית עד למקום שהכהן עומד, \u0005ואומרים]\u0006 זה לזה: \u0003כדקאי קאי\u0004 \u0005[כמו שהיה\u0006 הנגע מתחילה \u0005כך הוא\u0006 עכשיו\u0005].\u0006","ועוד שואלים: \u0003מנא הא מילתא דאמור רבנן: זיל בתר רובא\u0004 \u0005[מנין דבר זה שאמרו חכמים: לך אחר הרוב]?\u0006 ותוהים: \u0003מנלן\u0004 \u0005[מנין לנו]?!\u0006 מתוך \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במפורש: \u0003\"אחרי רבים להטות\"\u0004 (שמות כג, ב)!","ומסבירים: \u0003רובא דאיתא קמן\u0004 \u0005[רוב שנמצא לפנינו],\u0006 שאנו יכולים למנות אותו, \u0003כגון\u0004 שהיו בעיר \u0003תשע חנויות\u0004 שמוכרות בשר כשר, ואחת שמוכרת בשר טריפה, ונמצא בשר ברחוב ולא ברור מהיכן בא, שהולכים אחר הרוב. \u0003ו\u0004כן בהצבעה של \u0003סנהדרין,\u0004 שמונים את הדיינים והולכים בהכרעת הדין אחר הרוב — \u0003לא קא מיבעיא לן\u0004 \u0005[לא נשאלה לנו].\u0006","אלא \u0003כי קא מיבעיא לן\u0004 \u0005[כאשר נשאלה לנו]\u0006 השאלה הרי זה ביחס ל\u0003רובא דליתיה קמן\u0004 \u0005[רוב שאינו לפנינו],\u0006 אלא שהוא ידוע באופן כללי, \u0003כגון קטן וקטנה,\u0004 שאנו מתירים ליבם קטן שבא על יבמתו הקטנה לקיימה, ואין חוששים שמא יימצא הקטן סריס או הקטנה איילונית, שאינם ראויים ליבום, ונמצא בא על אשת אחיו שלא במקום מצוה, אלא סומכים על כך שרוב הקטנים מגיעים לבגרות מינית, דבר זה \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006","\u0003אמר ר' אלעזר (סימן\u0004 לשמות החכמים שמביאים מקור לדבר: \u0003זמן שבח מכנש\u0004 — ר' אלע\u0003ז\u0004ר, \u0003מ\u0004ר בריה דרבינא, רב \u0003נ\u0004חמן בר יצחק, רב \u0003ש\u0004שת, ר\u0003ב\u0004ה בר רב שילא, רב א\u0003ח\u0004א בר יעקב, רב \u0003מ\u0004רי, רב \u0003כ\u0004הנא, רבי\u0003נ\u0004א, רב א\u0003ש\u0004י):","\u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו \u0003מרישא\u0004 \u0005[מהראש]\u0006 \u0003של\u0004 קרבן ה\u0003עולה,\u0004 שחותכים אותו מגוף העולה, אבל אין מנתחים אותו לחלקים קטנים יותר, \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \u0003\"ונתח אותה לנתחיה\"\u0004 (ויקרא א, ו), ואנו למדים מכאן: \u0003אותה\u0004 מנתחים \u0003לנתחיה, ולא\u0004 את \u0003נתחיה לנתחים;\u0004 \u0003ו\u0004כיון שאין מנתחים את הראש, \u0003ניחוש\u0004 \u0005[נחשוש]\u0006 \u0003שמא ניקב\u0004 ה\u0003קרום של\u0004 ה\u0003מוח,\u0004 ובהמה זו טריפה היא, ופסולה להקרבה! \u0003אלא לאו\u0004 \u0005[האם אין\u0006 זה\u0005]\u0006 \u0003משום דאמרינן זיל בתר רובא\u0004 \u0005[שאומרים אנו לך אחר הרוב],\u0006 ורוב הבהמות אינן טריפה?","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח זאת? \u0003דילמא דפלי ליה ובדק ליה\u0004 \u0005[שמא\u0006 מדובר \u0005שמבקע אותו\u0006 את הראש \u0005ובודק אותו,\u0006 את קרום המוח\u0005],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום\u0004 מה שנאמר \u0003\"אותה לנתחיה\" ולא נתחיה לנתחים\u0004 — \u0003הני מילי היכא דחתיך ליה\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום שחותך אותו]\u0006 \u0003לגמרי,\u0004 \u0003אבל היכא דלייף לית לן בה\u0004 \u0005[במקום שעדיין מחובר בחלקו, אין לנו בה\u0006 חשש\u0005],\u0006 ולכן אין להוכיח מכאן.","\u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא אמר: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 ההלכה שהולכים אחר הרוב \u0003מ\u0004איסור \u0003שבירת עצם בפסח, דאמר רחמנא\u0004 \u0005[שאמרה התורה]:\u0006 \u0003\"ועצם לא תשברו בו\"\u0004 (שמות יב, מו); \u0003ו\u0004כיון שאי אפשר לשבור את עצם הגולגולת, \u0003ניחוש\u0004 \u0005[נחשוש]\u0006 \u0003שמא ניקב קרום של מוח\u0004 של הפסח, והוא טריפה! \u0003אלא לאו\u0004 \u0005[האם אין זה]\u0006 \u0003משום דאמרינן זיל בתר רובא\u0004 \u0005[שאומרים אנו לך אחר הרוב],\u0006 ורוב בהמות אינן טריפה?","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח? \u0003דלמא דמנח גומרתא עליה\u0004 \u0005[שמא\u0006 מדובר \u0005שמניח גחלת עליו]\u0006 על עצם הגולגולת \u0003וקלי ליה\u0004 \u0005[ושורף אותו],\u0006 וכך נחשף הקרום של מוח, \u0003ובדיק ליה\u0004 \u0005[ובודק אותו],\u0006 ובמקרה כזה אין איסור, כפי \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003המחתך בגידים והשורף בעצמות\u0004 — \u0003אין בו משום שבירת עצם!\u0004 ונמצא שגם מכאן אין הוכחה שהולכים אחר הרוב.","\u0003רב נחמן בר יצחק אמר: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו שהולכים אחר הרוב \u0003מ\u0004דין \u0003אליה\u0004 (הזנב) של כבש השלמים, \u0003דאמר רחמנא\u0004 \u0005[שאמרה התורה]\u0006 שצריך להקריב את \u0003\"חלבו האליה תמימה\"\u0004 (ויקרא ג, ט) כלומר, כשהיא שלמה, שאסור לחתוך אותה; \u0003ו\u0004לכאורה \u0003ליחוש\u0004 \u0005[נחשוש]\u0006 \u0003שמא\u0004 קודם השחיטה \u0003נפסקה\u0004 (נחתכה) \u0003חוט השדרה\u0004 בחלקו המצוי באליה, ומקריבים טריפה! \u0003אלא לאו\u0004 \u0005[האם אין\u0006 זה\u0005]\u0006 \u0003משום דאמרינן זיל בתר רובא\u0004 \u0005[שאומרים אנו לך אחר הרוב],\u0006 ורוב בהמות אינן טריפה?","\u0003וכי תימא דמתתאי פסיק לה\u0004 \u0005[ואם תאמר שמלמטה הוא חותך אותה],\u0006 את האליה, במקום שאם נפסק חוט השדרה אינו עושה טריפה — הלוא \u0003\"לעומת העצה\u0004 יסירנה\" (שם) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 ביחס לאליה, והוא \u0003מקום שהכליות יועצות,\u0004 ואם נפסק שם חוט השדרה הריהו עושה טריפה.","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח? \u0003דלמא דפתח לה ובדיק לה\u0004 \u0005[שמא\u0006 מדובר באופן \u0005שפותח אותה,\u0006 עושה חתך באליה \u0005ובודק אותה],\u0006 אם חוט השדרה שבתוכה אינו חתוך. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום\u0004 שנאמר \"האליה \u0003תמימה\",\u0004 שצריך להשאיר אותה שלמה — \u0003הני מילי היכא דחתכה\u0004 \u0005[דברים אלה\u0006 אמורים \u0005כאשר חתך אותה]\u0006 \u0003לגמרי\u0004 לשני חלקים, \u0003אבל היכא דלייף לית לן בה\u0004 \u0005[במקום שרק פותחים אותה\u0006 \u0005אין לנו בה\u0006 איסור\u0005].\u0006 ואם כן גם מכאן אין ראיה שסומכים על הרוב.","\u0003רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו שהולכים אחר הרוב \u0003מעגלה ערופה, דאמר רחמנא\u0004 \u0005[שאמרה התורה]:\u0006 \"וכל זקני העיר היא... ירחצו את ידיהם על העגלה הערופה\" (דברים כא, ו), ודייקו חכמים: \u0003\"הערופה\"\u0004 — \u0003כשהיא שלמה\u0004 בכל איבריה \u0003תיהוי\u0004 \u0005[תהיה]\u0006 באותה שעה. \u0003ו\u0004אם אין הולכים אחר הרוב \u0003ליחוש דלמא\u0004 \u0005[נחשוש שמא]\u0006 \u0003טרפה היא!\u0004 \u0003אלא לאו\u0004 \u0005[האם אין\u0006 זה\u0005]\u0006 \u0003משום דאמרינן זיל בתר רובא\u0004 \u0005[שאומרים אנו לך אחר הרוב],\u0006 ורוב בהמות אינן טריפה?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאין מכאן ראיה, מפני שאין צורך כלל בבדיקה, שהרי \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 אם טריפה היא או לא, הרי ממילא אינה נאכלת או קריבה! על כך יש להשיב, \u0003הא אמרי דבי\u0004 \u0005[הרי אמרו מבית\u0006 מדרשו\u0005]\u0006 של \u0003רבי ינאי:\u0004 לשון \u0003כפרה כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה\u0004 בעגלה ערופה (\"כפר לעמך ישראל\". שם ח) לומר שהריהי \u0003כקדשים,\u0004 ולכן טריפה פסולה בה, כמו בקדשים.","\u0003רבה בר רב שילא אמר: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 ההלכה שהולכים אחר הרוב \u0003מפרה אדומה, דאמר רחמנא\u0004 \u0005[שאמרה התורה]:\u0006 \u0003\"ושחט... ושרף\"\u0004 (במדבר יט, ג— ה), ולמדו מכאן: \u0003מה שחיטתה\u0004 נעשית \u0003כשהיא שלמה\u0004 באיבריה — \u0003אף שריפתה\u0004 נעשית \u0003כשהיא שלמה, ו\u0004אם אין הולכים אחר הרוב \u0003ליחוש דילמא\u0004 \u0005[נחשוש שמא]\u0006 \u0003טרפה היא! אלא לאו\u0004 \u0005[האם אין\u0006 זה\u0005]\u0006 \u0003משום דאמרינן זיל בתר רובא\u0004 \u0005[שאומרים אנו לך אחר הרוב],\u0006 ורוב הפרות אינן טריפה?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאין מכאן ראיה, שהרי \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 אם היא טריפה או לא? על כך יש להשיב: \u0003\"חטאת\" קרייה רחמנא\u0004 \u0005[קראה אותה התורה],\u0006 שנאמר \"חטאת היא\" (שם ט), ולכן היא צריכה להיות כשרה כקרבן חטאת.","\u0003רב אחא בר יעקב אמר: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 ההלכה שהולכים אחר הרוב \u0003משעיר המשתלח, דרחמנא אמר\u0004 \u0005[שהתורה אמרה]:\u0006 \u0003\"ולקח את שני השעירים\"\u0004 (ויקרא טז, ז), ודייקו חכמים: \u0003שיהו שניהם שוים,\u0004 השעיר לשם הקרב על המזבח, והשעיר המשתלח. \u0003ו\u0004לכאורה כיצד נדע שהם שווים? \u0003ליחוש\u0004 \u0005[נחשוש]\u0006"],["\u0003דילמא חד מינייהו\u0004 \u0005[שמא אחר מהם]\u0006 השעיר המשתלח לעזאזל \u0003טריפה הוא,\u0004 ואינם שווים! \u0003אלא לאו\u0004 \u0005[האם אין\u0006 זה\u0005]\u0006 \u0003משום דאמרינן זיל בתר רובא\u0004 \u0005[שאומרים אנו לך אחר הרוב],\u0006 ורוב השעירים אינם טריפה?","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003מאי נפקא לן מינה\u0004 \u0005[מה יוצא לנו מזה]\u0006 אם הוא טריפה או לא? הרי השעיר לעזאזל אינו קרבן כלל! על כך יש להשיב כי \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אין\u0004 ה\u0003גורל\u0004 שעושה הכהן הגדול ביום הכיפורים \u0003קובע\u0004 את השעיר \u0003לעזאזל אלא בדבר\u0004 (בשעיר) \u0003הראוי לשם,\u0004 לקרבן, ואם לא — אינו ראוי לשילוח. \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאין מכאן ראיה שהולכים אחר הרוב, מפני \u0003דבדקינן ליה\u0004 \u0005[שאנו בודקים אותו]\u0006 לאחר ששלחוהו לעזאזל, אם הוא טריפה — אינך יכול לומר כן, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 שהיה המשלח דוחף את השעיר מראש ההר, ו\u0003לא היה\u0004 השעיר \u0003מגיע למחצית ההר עד שנעשה אברים אברים,\u0004 ולכן אי אפשר לבדוק אותו.","\u0003רב מרי אמר: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 ההלכה שהולכים אחר הרוב\u0005]\u0006 \u0003ממכה אביו ואמו, דאמר רחמנא\u0004 \u0005[שאמרה התורה]\u0006 \u0003קטליה\u0004 \u0005[הרוג אותו]\u0006 (שמות כא, טו); \u0003וליחוש דלמא לאו\u0004 \u0005[ונחשוש שמא אין]\u0006 \u0003אביו הוא\u0004 ונולד לאמו מאיש אחר! \u0003אלא לאו\u0004 \u0005[האם אין\u0006 זה\u0005]\u0006 \u0003משום דאמרינן זיל בתר רובא\u0004 \u0005[שאומרים אנו לך אחר הרוב],\u0006 \u0003ורוב בעילות\u0004 באשה נשואה אנו מייחסים אותן \u0003אחר הבעל,\u0004 ולכן אנו מניחים שהוא אביו?","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח זאת? \u0003דלמא\u0004 \u0005[שמא]\u0006 עוסק הכתוב במקרים שאין בהם ספק, \u0003כגון שהיו אביו ואמו חבושים בבית האסורין\u0004 לבדם בשעה שנתעברה אמו, ולא יכול להיות שאדם אחר יהיה אביו! ודוחים: \u0003אפילו הכי\u0004 \u0005[כך],\u0006 \u0003אין אפוטרופוס לעריות,\u0004 כלומר, לעולם אין ודאות בענייני עריות.","\u0003רב כהנא אמר: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 ההלכה שהולכים אחר הרוב \u0003מהורג את הנפש, דאמר רחמנא\u0004 \u0005[שאמרה התורה]:\u0006 \u0003קטליה\u0004 \u0005[הרוג אותו]\u0006 (שם יב); \u0003וליחוש דלמא\u0004 \u0005[ונחשוש שמא]\u0006 ההרוג \u0003טרפה הוה\u0004 \u0005[היה],\u0006 וההורג את הטריפה פטור (מפני שהוא נחשב כמת)! \u0003אלא לאו\u0004 \u0005[האם אין\u0006 זה\u0005]\u0006 \u0003משום דאמרינן זיל בתר רובא\u0004 \u0005[שאומרים אנו לך אחר הרוב],\u0006 ורוב האנשים אינם טריפה?","\u0003וכי תימא דבדקינן ליה\u0004 \u0005[ואם תאמר]\u0006 שאין הולכים אחר הרוב, אלא את ההרוג, האם היה טריפה — \u0003הא קא מינוול\u0004 \u0005[הרי הוא מתנוול]\u0006 על ידי בדיקה זו! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאכן \u0003משום\u0004 חשש \u0003איבוד נשמה\u0004 \u0003דהאי\u0004 \u0005[של זה]\u0006 הרוצח, אכן נבדוק את הנרצח ו\u0003נינווליה\u0004 \u0005[ננוול אותו]\u0006 — לא היה הדבר מועיל, \u0003ו\u0004עדיין \u0003ניחוש\u0004 \u0005[נחשוש]\u0006 \u0003שמא במקום\u0004 שפגע בו ב\u0003סייף נקב הוה\u0004 \u0005[היה]\u0006 קודם לכן, וטריפה היה, ודבר זה אי אפשר לבדוק.","\u0003רבינא אמר: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 ההלכה שהולכים אחר הרוב \u0003מעדים זוממין, דאמר רחמנא\u0004 \u0005[שאמרה התורה]:\u0006 \u0003\"ועשיתם לו כאשר זמם\u0004 לעשות לאחיו\" (דברים יט, יט), וכגון שאם העידו באיש שהרג את חבירו — דינם במיתה; \u0003וליחוש דלמא הך דאסהידו ביה\u0004 \u0005[ונחשוש שמא זה שהעידו עליו]\u0006 \u0003טרפה הוה\u0004 \u0005[היה],\u0006 ונמצא שזממו להרוג את הטריפה, ואין דינם במיתה! \u0003אלא לאו\u0004 \u0005[האם אין\u0006 זה\u0005]\u0006 \u0003משום דאמרינן זיל בתר רובא\u0004 \u0005[שאומרים אנו לך אחר הרוב],\u0006 ורוב האנשים אינם טריפה?","\u0003וכי תימא דבדקינן ליה\u0004 \u0005[ואם תאמר שבודקים אנו אותו]\u0006 את זה שהעידו עליו האם הוא טריפה, ורק באופן זה הורגים אותם — \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 החכם \u0003ברבי אומר:\u0004 עדים שזממו להרוג אדם בעדותם, אם עדיין \u0003לא הרגו\u0004 על פיהם — \u0003נהרגין,\u0004 אבל אם כבר \u0003הרגו\u0004 על פיהם — \u0003אין נהרגין,\u0004 ואת האיש החי אי אפשר לבדוק אם הוא טריפה. ואם כן, בהכרח אנו מסתמכים על הרוב.","\u0003רב אשי אמר: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 ההלכה שהולכים אחר הרוב \u0003משחיטה עצמה, דאמר רחמנא\u0004 \u0005[שאמרה התורה]:\u0006 \u0003שחוט ואכול; וליחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא במקום נקב\u0004 שכבר היה בבהמה או בעוף \u0003קא שחיט\u0004 \u0005[הוא שוחט],\u0006 וטריפה היתה! \u0003אלא לאו\u0004 \u0005[האם אין זה]\u0006 \u0003משום דאמרינן זיל בתר רובא\u0004 \u0005[שאומרים אנו לך אחר הרוב]\u0006 ולרוב הבהמות והעופות אין נקב במקום השחיטה?","\u0003אמר רב אשי: אמריתא לשמעתא קמיה\u0004 \u0005[אמרתי את השמועה\u0006 הזו, \u0005לפני]\u0006 \u0003רב כהנא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר אותה \u0003רב כהנא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב שימי, ואמר ליה\u0004 \u0005[לו]\u0006 החכם השומע: עדיין אין מכאן (ומשאר כל הראיות שהובאו לעיל) הוכחה שמסתמכים מן התורה על הרוב, \u0003ודלמא היכא\u0004 \u0005[ושמא במקום]\u0006 ש\u0003אפשר\u0004 לבדוק \u0003אפשר,\u0004 וצריך לבדוק, ואין סומכים על הרוב, ורק \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא אפשר\u0004 לבדוק \u0003לא אפשר,\u0004 וסומכים על הרוב.","\u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 \u0003ל\u0004דעת \u0003ר' מאיר דחייש למיעוטא\u0004 \u0005[שחושש למיעוט],\u0006 ואינו הולך אחר הרוב, \u0003הכי נמי דלא אכיל בישרא\u0004 \u0005[כך גם כן תאמר שאינו אוכל בשר]\u0006 משום שאי אפשר להוכיח שלא שחט במקום נקב? \u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך הוא גם כן],\u0006 שלדעת ר' מאיר אי אפשר לאכול בשר —"],["\u0003פסח ו\u0004שאר \u0003קדשים\u0004 שחובה לאכול מבשרם, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003אלא\u0004 בהכרח צריך לומר לשיטתו כי \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003אפשר\u0004 לחשוש למיעוט ולבדוק \u0003אפשר, היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא אפשר לא אפשר;\u0004 אם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לשיטת חכמים אפשר לומר: \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003אפשר\u0004 לבדוק \u0003אפשר, היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא אפשר לא אפשר\u0004 וסומכים על הרוב. ואם כן, אין לנו הוכחה גמורה שסומכים לכתחילה על הרוב.","\u0003אמר רב נחמן אמר רב: ראה אחד ששחט, אם ראהו מתחלה ועד סוף\u0004 — \u0003מותר לאכול משחיטתו, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אסור לאכול משחיטתו.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי דידע דגמיר\u0004 \u0005[אם\u0006 במקרה \u0005שיודע ש\u0006האיש ששחט \u0005למוד,\u0006 יודע בהלכות שחיטה\u0005],\u0006 \u0003למה לי\u0004 להצריך \u0003ש\u0004\u0003ראה\u0004 אותו ששחט? גם בלא לראות יכול לסמוך עליו! \u0003ואי דידע דלא גמיר\u0004 \u0005[ואם\u0006 בש \u0005יודע שאינו למוד],\u0006 \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שרק אם ראהו מתחילה ועד סוף ששחט כראוי — מותר לאכול משחיטתו!","\u0003ואלא\u0004 צריך לומר \u0003דלא ידע אי גמיר אי לא גמיר\u0004 \u0005[שאינו יודע אם הוא למוד או לא למוד],\u0006 ואולם במקרה זה מדוע אינו רשאי לאכול, גם אם לא ראהו? \u0003לימא\u0004 \u0005[נאמר]:\u0006 \u0003רוב\u0004 האנשים ה\u0003מצויין אצל שחיטה,\u0004 השוחטים — \u0003מומחין הן,\u0004 יודעים הלכות שחיטה, ויש לסמוך על רוב זה!","\u0003מי לא תניא\u0004 \u0005[האם לא שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הרי שמצא תרנגולת שחוטה בשוק, או שאמר לשלוחו \"צא שחוט\u0004 תרנגול\", \u0003והלך ומצא\u0004 אותו \u0003שחוט,\u0004 ואינו יודע מי שחטו — \u0003חזקתו שחוט\u0004 בכשרות,","\u0003אלמא אמרינן\u0004 \u0005[מכאן שאנו אומרים]:\u0006 \u0003רוב מצויין אצל שחיטה מומחין הן. הכא נמי\u0004 \u0005[כאן גם כן],\u0006 כשאינו יודע אם האדם שראהו שוחט יודע הלכות שחיטה, \u0003לימא\u0004 \u0005[נאמר]:\u0006 \u0003רוב מצויין אצל שחיטה מומחין הן!\u0004","ומשיבים: \u0003לעולם\u0004 תפרש \u0003דידע דלא גמיר\u0004 \u0005[ש\u0006הוא \u0005יודע שאינו למוד]\u0006 ומכל מקום הוצרך לומר שרק אם ראהו מתחילה ועד סוף מותר לאכול משחיטתו, \u0003וכגון דשחט קמן חד סימן שפיר\u0004 \u0005[ששחט לפנינו סימן אחד,\u0006 את הקנה או הוושט, \u0005כראוי],\u0006 ואת האחר שחט שלא לפנינו, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מדהאי שפיר הך נמי שפיר\u0004 \u0005[מכיון ש\u0006סימן \u0005זה\u0006 שחט \u0005כראוי, את זה,\u0006 השני \u0005גם כן\u0006 שחט \u0005כראוי],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא: \u0003האי אתרמויי איתרמי ליה\u0004 \u0005[\u0006את \u0005זה אולי הזדמן לו]\u0006 ששחט כראוי, \u0003אידך\u0004 \u0005[\u0006את הסימן \u0005האחר]\u0006 \u0003שמא שהה שמא דרס,\u0004 ולכן אינו כשר אלא אם ראהו מתחילה ועד סוף.","ובענין זה \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב דימי בר יוסף מרב נחמן: האומר לשלוחו \"צא ושחוט\u0004 תרנגול\", \u0003והלך ומצא\u0004 אותו \u0003שחוט, מהו? אמר לו: חזקתו שחוט\u0004 כראוי. ועוד שאל: \u0003האומר לשלוחו \"צא ותרום\u0004 לי תרומה\", \u0003והלך\u0004 הבעלים \u0003ומצא\u0004 שהוא \u0003תרום,\u0004 שניטלה ממנו שיעור תרומה, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003אין חזקתו תרום,\u0004 שמא לא תרם השליח.","ותהה רב דימי בר יוסף: \u0003מה נפשך\u0004 \u0005[רצונך]?\u0006 כיצד אתה מבין? \u0003אי\u0004 \u0005[אם]\u0006 \u0003חזקה\u0004 היא ש\u0003שליח עושה שליחותו\u0004 וסומכים על כך — \u0003אפילו\u0004 ב\u0003תרומה נמי\u0004 \u0005[גם כן]\u0006 תסמוך על כך, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אין חזקה\u0004 ש\u0003שליח עושה שליחותו\u0004 — \u0003אפילו שחיטה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 תסמוך על כך!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003לכי תיכול עלה כורא דמלחא\u0004 \u0005[כאשר תאכל על כך כור של מלח],\u0006 כלומר, כאשר תעיין בדבר היטב תבין, \u0003לעולם אין\u0004 אומרים \u0003חזקה\u0004 ש\u0003שליח עושה שליחותו,\u0004 אלא ספק הוא. \u0003ו\u0004לגבי \u0003שחיטה,\u0004 מדוע חזקתו שחוט כראוי? מפני ש\u0003אי נמי\u0004 \u0005[אם גם כן]\u0006 תאמר \u0003דילמא אינש אחרינא שמע ואזל שחט\u0004 \u0005[שמא אדם אחר,\u0006 שאינו שלוחו, \u0005שמע\u0006 שרוצים לשחוט \u0005והלך ושחט]\u0006 — שחיטה כשרה היא, כי בכלל \u0003רוב\u0004 ה\u0003מצויין אצל שחיטה מומחין הן.\u0004 אבל לגבי \u0003תרומה,\u0004 אנו חוששים \u0003דילמא אינש אחרינא שמע ואזל תרם\u0004 \u0005[שמא אדם אחר שמע והלך ותרם]\u0006 — \u0003הוה ליה\u0004 \u0005[הרי זה]\u0006 \u0003תורם שלא מדעת\u0004 הבעלים, \u0003והתורם שלא מדעת\u0004 הבעלים — \u0003אין תרומתו תרומה.\u0004","ובענין שהזכרנו קודם, מציעים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 שההנחה ש\u0003רוב מצויין אצל שחיטה מומחין הן תנאי\u0004 \u0005[מחלוקת תנאים]\u0006 \u0003היא\u0004 בדבר\u0003?\u0004 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003הרי שאבדו לו גדייו ותרנגוליו והלך ומצאן שחוטים\u0004 כראוי — \u0003רבי יהודה אוסר\u0004 לאוכלם, \u0003רבי חנינא בנו של רבי יוסי הגלילי מתיר. אמר רבי: נראין דברים של רבי יהודה\u0004 האוסר כ\u0003שמצאן באשפה,\u0004 שיש לחשוש שמא נפסלו בשחיטתם, ולכן זרקו אותם לאשפה. \u0003ו\u0004נראים \u0003דברי רבי חנינא בנו של ר' יוסי הגלילי\u0004 כ\u0003שמצאן בבית,\u0004 שמן הסתם נשחטו כהוגן.","\u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' חנינא בנו של ר' יוסי הגלילי המתיר, \u0005סבור]:\u0006 \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003רוב מצויין אצל שחיטה מומחין הן, ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה האוסר, \u0005סבור]:\u0006 \u0003לא אמרינן\u0004 \u0005[אין אומרים אנו]\u0006 \u0003רוב מצויין אצל שחיטה מומחין הן?\u0004","\u0003אמר רב נחמן בר יצחק: לא,\u0004 אין להוכיח מכאן, ואפשר לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003רוב מצויין אצל שחיטה מומחין הן.\u0004 ולכן, אם מצא את השחוטים \u0003בבית\u0004 \u0003—\u0004 \u0003דכולי עלמא לא פליגי דשרי\u0004 \u0005[הכל אינם חלוקים שמותר].\u0006 ומצד אחר, אם מצא אותם \u0003באשפה שבשוק\u0004 — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003אסור,\u0004 שודאי נפסלו בשחיטתם, והשליכום שם; \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003באשפה שב\u0004תוך ה\u0003בית, מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יהודה האוסר, \u0005סבור]:\u0006 \u0003אדם עשוי להטיל נבלתו באשפה שבבית,\u0004 ולכן יש לחשוש שנבילה היא. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' חנינא המתיר, \u0005סבור]:\u0006 \u0003אין אדם עשוי להטיל נבלתו באשפה שבבית,\u0004 בגלל הסירחון, אלא ודאי שחוטה היא, והניח אותה שם לפי שעה. ועל פי פירוש זה דנים בהמשך הדברים.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא, \u0003אמר רבי: נראין דברי רבי יהודה\u0004 האוסר, כ\u0003שמצאן באשפה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה,\u0006 איזו\u0005]\u0006 \u0003אשפה\u0004 זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003אשפה שבשוק\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמרת: דכולי עלמא לא פליגי\u0004 \u0005[שהכל אינם חלוקים]\u0006 שבמקרה זה \u0003אסור,\u0004 ואין זו דעת ר' יהודה בלבד! \u0003אלא לאו פשיטא\u0004 \u0005[האם לא פשוט]\u0006 שמדובר פה \u0003באשפה שבבית,\u0004 ובכך נחלקו, ופסק רבי כר' יהודה האוסר.","ומעתה \u0003אימא סיפא\u0004 \u0005[אמור את סופם]\u0006 של דברי רבי: \u0003ו\u0004נראים \u0003דברי רבי חנינא בנו של רבי יוסי הגלילי\u0004 כ\u0003שמצאן בבית.\u0004 ויש לשאול: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 שמצאן ב\u0003בית? אילימא\u0004 \u0005[אם תאמר]\u0006 ב\u0003בית ממש\u0004 — \u0003האמרת\u0004 \u0005[הרי כבר אמרת]\u0006 \u0003דכולי עלמא לא פליגי דשרי\u0004 \u0005[שהכל אינם חלוקים שמותר],\u0006 ואין זו רק דעתו של ר' חנינא! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר \u0003באשפה שבבית,\u0004 שבזה נחלקו. ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רבי\u0004 על דברי \u0003רבי,\u0004 שבתחילה הוא פוסק כר' יהודה לאסור, ובסוף הוא פוסק כר' חנינא להתיר!"],["ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 כך היא כוונת הדברים: \u0003נראין דברי רבי יהודה\u0004 האוסר, \u0003לרבי חנינא בנו של רבי יוסי הגלילי\u0004 — כשמצאם \u0003באשפה שבשוק, שאף רבי חנינא בנו של רבי יוסי הגלילי לא נחלק עליו אלא\u0004 כשמצאם \u0003באשפה שבבית, אבל\u0004 כשמצאם \u0003באשפה שבשוק מודי ליה\u0004 \u0005[מודה לו]\u0006 שאסור, \u0003ו\u0004כן \u0003נראין\u0004 דברי ר' חנינא המתיר, לר' \u0003יהודה —\u0004 כשמצאם בבית שלא באשפה, שאף הוא לא חלק עליו במקרה זה.","שנינו במשנה: הכל שוחטים ושחיטתן כשרה, \u0003חוץ מחרש שוטה וקטן,\u0004 שאין שחיטתם כשרה, ואפילו בדיעבד, \u0003שמא יקלקלו את שחיטתן.\u0004 ומדייקים: \u0003\"שמא קלקלו\u0004 את שחיטתן\" \u0003לא קתני\u0004 \u0005[אינו שונה],\u0006 \u0003אלא \"שמא יקלקלו\"\u0004 לעתיד. \u0003אמר רבא: זאת אומרת אין מוסרין להן חולין לכתחלה\u0004 לשחוט, אפילו אחרים רואים אותם.","עוד שנינו במשנה: \u0003וכולן ששחטו ואחרים רואים אותם\u0004 — \u0003שחיטתן כשרה.\u0004 ומשמע — אפילו חרש שוטה וקטן, שאין בהם דעת. ושואלים: \u0003מאן תנא דלא בעינן\u0004 \u0005[מיהו התנא\u0006 הסבור \u0005שאין אנו צריכים]\u0006 \u0003כוונה לשחיטה?\u0004","\u0003אמר רבא:\u0004 שיטת \u0003רבי נתן היא, דתני\u0004 \u0005[ששנה]\u0006 \u0003אושעיא זעירא דמן חבריא\u0004 \u0005[הקטן שבחבורת החכמים]\u0006 בברייתא: \u0003זרק סכין\u0004 כדי \u0003לנועצה בכותל והלכה\u0004 הסכין \u0003ושחטה כדרכה\u0004 בשחיטה כשרה — \u0003רבי נתן מכשיר, וחכמים פוסלין.\u0004 ומוסיפים: \u0003הוא\u0004 אושעיא \u0003תני לה\u0004 \u0005[שנה אותה],\u0006 \u0003והוא אמר לה\u0004 \u0005[עליה]:\u0006 \u0003הלכה כרבי\u0004 \u0003נתן,\u0004 שאין צורך בכוונה לשם שחיטה.","ולגופה של הברייתא שואלים: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שיהיה \u0003מוליך ומביא\u0004 את הסכין על צואר הבהמה, ולא די בהולכה בלבד בדרך מעופה! ומשיבים: הכוונה \u0003ש\u0004הסכין \u0003הלכה ו\u0004גם \u0003באה,\u0004 שחתכה במעופה, וכשפגעה בכותל ניתזה לאחור \u0003ו\u0004חזרה וחתכה \u0003כדרכה.\u0004","\u0003אמר ר' חייא בר אבא, בעי\u0004 \u0005[שאל]\u0006 \u0003רבי יוחנן:\u0004 בעניינים בהם יש צורך במחשבה וכוונה, האם \u0003קטן יש לו מחשבה,\u0004 שכוונתו מועילה, \u0003או אין לו מחשבה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי אמי\u0004 לר' חייא בר אבא: \u0003ותיבעי ליה\u0004 \u0005[ותישאל לו]\u0006 לר' יוחנן השאלה ביחס ל\u0003מעשה,\u0004 כאשר יש מעשה המוכיח את הכוונה, האם המעשה של הקטן נחשב! \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003מעשה דלא קא מבעיא ליה\u0004 \u0005[שלא נשאלה לו]\u0006 — \u0003דתנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]\u0006 במפורש: \u0003יש להן מעשה\u0004 לקטנים, אולם אם כן ב\u0003מחשבה נמי לא תיבעי ליה\u0004 \u0005[גם כן לא תישאל לו],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 באותה משנה\u0005]:\u0006 \u0003אין להן מחשבה!\u0004","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 פרי \u0003האלון, ו\u0004כן \u0003הרמון\u0004 או \u0003האגוז שחקקום תינוקות\u0004 (ילדים), שעשו בהם בית קיבול כדי \u0003למוד\u0004 (למדוד) \u0003בהן עפר, או שהתקינום ל\u0004עשות אותם \u0003כף מאזנים\u0004 — הרי הם \u0003טמאין\u0004 כלומר, ראויים לקבלת טומאה, כדין כלים גמורים. למרות שאם מצאו קליפת אגוז, שאינה מקבלת טומאה, וחשבו להשתמש בה למדידה — אינה מקבלת טומאה, כמו שהוא באדם בוגר. וטעם הדבר \u0003מפני שיש להן\u0004 לקטנים \u0003מעשה,\u0004 שאם עשו מעשה המוכיח כוונה הריהו בר תוקף,"],["\u0003ואין להן מחשבה,\u0004 שבמקום בו יש צורך במחשבה — אין מחשבתם מועילה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא בר אבא לר' אמי: \u0003מחשבה\u0004 של קטן \u0003גרידתא\u0004 \u0005[בלבד]\u0006 \u0003לא קא מיבעיא ליה\u0004 \u0005[לא נשאלה לו]\u0006 לר' יוחנן אם מועילה; \u0003כי קא מיבעיא ליה\u0004 \u0005[כאשר נשאלה לו]\u0006 האם מועילה מחשבה של קטן, הרי זה במקרה ש\u0003מחשבתו ניכרת מתוך מעשיו,\u0004 אף שהמעשה בלבד אינו מוכיח.","\u0003כגון\u0004 לענין שחיטת קרבן לשמו, וכגון \u0003דהוה קיימא\u0004 \u0005[שהיתה עומדת]\u0006 \u0003עולה בדרום\u0004 העזרה \u0003ואתיוה\u0004 \u0005[והביא אותה]\u0006 \u0003בצפון\u0004 העזרה, ששם מקום שחיטתה, \u0003ושחטה, מאי\u0004 \u0005[מה]\u0006 הדין? האם \u0003מדאתייא\u0004 \u0005[האם מכיון שהביאה]\u0006 \u0003בצפון ו\u0004שם \u0003שחט\u0004 אותה, מורה הדבר ש\u0003איכוין לה\u0004 \u0005[התכוון לה]\u0006 לשם עולה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003מקום הוא דלא איתרמי ליה\u0004 \u0005[שלא הזדמן לו]\u0006 בדרום, ולכן הביא אותה לצפון?","הקשה לו ר' אמי: \u0003הא נמי\u0004 \u0005[זו גם כן]\u0006 כבר \u0003אמרה,\u0004 התייחס אליה \u0003רבי יוחנן חדא זימנא\u0004 \u0005[פעם אחת]!\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המעלה פירותיו לגג מפני הכנימה\u0004 (חרקים), \u0003וירד עליהם טל\u0004 — \u0003אינן ב\"כי יותן\",\u0004 כלומר, אינם מוכשרים בכך לקבל טומאה, מפני שצריך שיבואו עליהם המים לרצונו. \u0003ואם\u0004 לאחר שהעלם \u0003נתכוין לכך\u0004 שיירטבו בטל — \u0003הרי הן ב\"כי יותן\".\u0004","ואם \u0003העלום חרש שוטה וקטן\u0004 מפני הכנימה, \u0003אף על פי ש\u0004לאחר מכן \u0003נתכוונו לכך\u0004 שיירטבו — \u0003אינן ב\"כי יותן\", מפני שיש להן מעשה ואין להן מחשבה;\u0004","\u0003ואמר ר' יוחנן\u0004 על כך: \u0003לא שנו\u0004 שאין מחשבתם מועילה \u0003אלא שלא היפך בהן\u0004 הקטן בפירות, \u0003אבל היפך בהן,\u0004 מתוך שניכר ממעשיו שהוא רוצה שיירטבו — \u0003הרי זה ב\"כי יותן\".\u0004 ואם כן, כבר אמר ר' יוחנן שיש לקטן מחשבה הניכרת מתוך מעשיו!","השיב לו ר' חייא בר אבא, \u0003הכי קא מיבעיא ליה\u0004 \u0005[כך נשאלה לו]\u0006 לר' יוחנן: האם דין זה, שכשמחשבתו של קטן ניכרת מתוך מעשיו מחשבתו מועילה, הוא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003או דרבנן\u0004 \u0005[מדברי חכמים].\u0006 זה היה נוסח אחד של הדיון שבין ר' חייא בר אבא ור' אמי.","\u0003רב נחמן בר יצחק מתני הכי\u0004 \u0005[\u0006היה \u0005שונה כך]:\u0006 \u0003אמר ר' חייא בר אבא, בעי\u0004 \u0005[שאל]\u0006 \u0003רבי יוחנן: קטן יש לו מעשה או אין לו מעשה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי אמי: ותיבעי ליה\u0004 \u0005[ותישאל לו]\u0006 בענין \u0003מחשבה! מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003מחשבה דלא קא מיבעיא ליה\u0004 \u0005[שלא נשאלה לו]?\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 בענין האלון והרימון והאגוז ש\u0003אין להן מחשבה,\u0004 שאם מצאו קליפה וחשבו להשתמש בה ככלי — אין מחשבה זו מועילה להחשיבה ככלי ולקבל טומאה. \u0003מעשה נמי לא תיבעי ליה\u0004 \u0005[גם כן לא תישאל לו],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 באותה משנה\u0005]\u0006 שאם חקקו באגוז על מנת למדוד בו הריהו מקבל טומאה, מפני ש\u0003יש להן מעשה!\u0004","והשיבו על כך: \u0003הכי קא מיבעיא ליה\u0004 \u0005[כך נשאלה לו]\u0006 לר' יוחנן: האם מה ששנינו שיש להם מעשה ואין להם מחשבה, \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, \u0003או דרבנן\u0004 \u0005[מדברי סופרים]?\u0006 \u0003ופשיט\u0004 \u0005[ופתר]:\u0006 \u0003יש להן מעשה ואפילו מדאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003אין להן מחשבה ואפילו מדרבנן\u0004 \u0005[מדברי חכמים],\u0006 וכאשר \u0003מחשבתו ניכרת מתוך מעשיו\u0004 — \u0003מדאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003אין לו,\u0004 אין זה מועיל, \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003יש לו.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003שמואל מרב הונא: מנין למתעסק בקדשים,\u0004 ששחט קדשים בלא להתכוון לכך, \u0003שהוא פסול?\u0004 אמר לו, \u0003שנאמר: \"ושחט את בן הבקר\u0004 לפני ה' \" (ויקרא א, ה) — \u0003שתהא שחיטה לשם בן בקר. אמר לו: זו בידינו היא\u0004 שצריך לעשות כן לכתחילה, אבל \u0003לעכב,\u0004 שאף בדיעבד לא תועיל שחיטתו, \u0003מנין? אמר ליה\u0004 \u0005[לו]:\u0006 נאמר \u0003\"לרצונכם תזבחוהו\"\u0004 (שם יט, ה), וכוונתו \u0003לדעתכם זבוחו,\u0004 במתכוון, ומה ששנה עליו הכתוב הריהו לעכב.","\u0003שחיטת נכרי\u0004 עושה את הדבר הנשחט ל\u0003נבלה, ומטמאה במשא.\u0004","מדייקים מלשון המשנה: איסור אכילה ב\u0003נבלה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 יש בה, אבל \u0003איסור הנאה\u0004 — \u0003לא.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר ר' חייא ברבי אבא אמר ר' יוחנן:\u0004 ש\u0003לא כ\u0004שיטת \u0003רבי אליעזר\u0004 היא, \u0003דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' אליעזר\u0004 — \u0003האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003סתם מחשבת נכרי לעבודה זרה,\u0004 ותקרובת עבודה זרה אסורה בהנאה.","\u0003ר' אמי אמר, הכי קתני\u0004 \u0005[כך הוא שונה],\u0006 כך יש לדייק מן המשנה: \u0003שחיטת\u0004 סתם \u0003נכרי\u0004 — \u0003נבלה, הא\u0004 \u0005[הרי]\u0006 שחיטת \u0003מין,\u0004 האדוק בעבודה זרה, ואפילו הוא ישראל — הריהי ודאי \u0003לעבודה זרה\u0004 ואוסרת בהנאה. ומעירים: לפי דרך זו, נמצא כי \u0003תנינא להא\u0004 \u0005[שנינו\u0006 במשנתנו \u0005את זו]\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 בברייתא: \u0003שחיטת מין\u0004 מישראל נחשבת כשחיטה \u0003לעבודה זרה,\u0004 שאסורה בהנאה. \u0003פיתו\u0004 אסורה \u0003כ\u0004\u0003פת כותי. יינו\u0004 נחשב \u0003יין נסך. ספריו,\u0004 תורה נביאים וכתובים שכתב, נחשבים כ\u0003ספרי קוסמין,\u0004 שמצוה לשרוף אותם. \u0003פירותיו\u0004 נחשבים ל\u0003טבלין,\u0004 למרות שהפריש מהם תרומות ומעשרות. \u0003ויש אומרים: אף\u0004"],["\u0003בניו ממזרין,\u0004 שאינו מקפיד על אשתו אם היא מזנה עם אחרים.","ושואלים: \u0003ותנא קמא\u0004 \u0005[ו\u0006ה\u0005תנא\u0006 ה\u0005ראשון]\u0006 מדוע אינו מונה דבר זה? ומשיבים: לדעתו, מין את \u0003אשתו לא מפקר\u0004 \u0005[אינו מפקיר].\u0006","על מה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 במשנה: \u0003שחיטת נכרי נבלה,\u0004 שואלים: \u0003וניחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא מין הוא,\u0004 הדבוק בעבודה זרה, ושחיטתו אסורה בהנאה, כפי ששנינו בברייתא לעיל, מפני שמן הסתם שחט לשמה! \u0003אמר רב נחמן אמר רבה בר אבוה: אין מינין באומות\u0004 העולם.","ותוהים: \u0003והא קאחזינן דאיכא\u0004 \u0005[והרי רואים אנו שיש]!\u0006 ומשיבים, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003אין רוב אומות\u0004 העולם \u0003מינין,\u0004 ולענין שחיטה הולכים אחר הרוב. ומעירים: \u0003סבר לה כי הא\u0004 \u0005[סבור הוא\u0006 רב נחמן \u0005כמו זו]\u0006 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: גוים שבחוצה לארץ לאו עובדי עבודה זרה הן,\u0004 שאף שעובדים עבודה זרה — אין זה מתוך אמונה והכרה, \u0003אלא מנהג אבותיהן בידיהן.\u0004","ומביאים מה ש\u0003אמר רב יוסף בר מניומי אמר רב נחמן: אין מינין באומות\u0004 העולם, כלומר, אין להם דין מין. ושואלים: \u0003למאי\u0004 \u0005[למה]?\u0006 לאיזה ענין נאמר הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ל\u0004ענין \u0003שחיטה, השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003שחיטת מין\u0004 שהוא \u0003ישראל אמרת אסירא\u0004 \u0005[שהיא אסורה],\u0006 שחיטת מין \u0003גוי מבעיא\u0004 \u0005[נצרכה לומר]?\u0006 \u0003אלא\u0004 תאמר ש\u0003ל\u0004ענין \u0003מורידין\u0004 לבור נאמר, שאין גורמים לו מיתה, \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 מינים של \u0003ישראל מורידין,\u0004 כפי ששנינו בברייתא (עבודה זרה יג,ב), מינים של \u0003גוים מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006","\u0003אמר רב עוקבא בר חמא:\u0004 נאמר הדבר \u0003לקבל מהן קרבן.\u0004 ובענין זה שונה דינו של מין גוי ממין ישראל. \u0003דתניא\u0004 \u0005[ששנויה ברייתא]:\u0006 נאמר \"אדם כי יקריב מכם\" (ויקרא א, ב), והדגיש הכתוב \u0003\"מכם\"\u0004 לומר — \u0003ולא כולכם, להוציא את\u0004 הישראל \u0003המשומד\u0004 שעובר עבירה באופן קבוע, וכל שכן את המין. ועוד דורשים: \u0003\"מכם\"\u0004 — \u0003בכם\u0004 בישראל \u0003חלקתי\u0004 בין משומד לשאר ישראל, \u0003ולא באומות,\u0004 אלא מקבלים מכל גוי, אפילו משומד, ואפילו מין.","ושואלים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה מסקנה זו? \u0003דלמא הכי קאמר\u0004 \u0005[שמא כך אומר\u0006 הכתוב\u0005]:\u0006 \u0003מישראל\u0004 — \u0003מצדיקי\u0004 \u0005[מצדיקים]\u0006 \u0003קבל, מרשיעי\u0004 \u0005[מרשעים]\u0006 \u0003לא תקבל, אבל\u0004 \u0003מאומות העולם\u0004 — \u0003כלל כלל לא\u0004 תקבל! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לפרש כן, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר \"איש איש מבית ישראל וכו' אשר יקריב קרבנו\" (שם כב, יח). ודי היה לומר \u0003\"איש\", מה תלמוד לומר \"איש\" \"איש\"?\u0004 הרי זה \u0003לרבות הגוים, שנודרים נדרים ונדבות כישראל,\u0004 משמע שמקבלים מהם קרבנות.","שנינו במשנה ששחיטת הנכרי נבלה ו\u0003מטמאה במשא.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, \u0003כיון\u0004 ש\u0003נבלה היא\u0004 הריהי \u0003מטמאה במשא!\u0004 \u0003אמר רבא, הכי קתני\u0004 \u0005[כך הוא שונה],\u0006 יש כאן הדגשה מיוחדת: \u0003זו\u0004 \u0003מטמאה במשא, ויש לך אחרת\u0004 דומה לה \u0003שהיא מטמאה אפילו באהל\u0004 שהנמצא עמה תחת אותו גג נטמא, למרות שאינו נוגע בה או נושא אותה, \u0003ואיזו זו?\u0004 בהמה ששחטה בתור \u0003תקרובת עבודה זרה, וכ\u0004דעת \u0003רבי יהודה בן בתירא,\u0004 הסבור שתקרובת עבודה זרה מטמאה באוהל.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת: \u0003אמר רבא, הכי קתני\u0004 \u0005[כך הוא שונה],\u0006 זאת ההדגשה: \u0003זו מטמאה במשא, ויש לך\u0004 שחיטה \u0003אחרת שהיא כזו שמטמאה במשא ואינה מטמאה באהל, ואיזו? זו תקרובת עבודה זרה, ו\u0004ש\u0003לא כר' יהודה בן בתירא.\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה בן בתירא אומר: מנין לתקרובת עבודה זרה שהיא מטמאה באהל? שנאמר: \"ויצמדו לבעל פעור ויאכלו זבחי מתים\"\u0004 (תהלים קו, כח), הרי שכינה הכתוב תקרובת עבודה זרה למת. ומכאן יש ללמוד: \u0003מה מת מטמא באהל\u0004 — \u0003אף תקרובת עבודה זרה מטמאה באהל.\u0004","\u0003השוחט בלילה, וכן הסומא ששחט\u0004 — \u0003שחיטתו כשרה.\u0004","ומדייקים בלשון המשנה: \u0003\"השוחט\u0004 בלילה\" נאמר, ולא \"שוחטין בלילה\", לומר \u0003דיעבד\u0004 \u0005[שכבר עשה]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 שחיטתו כשרה, אבל \u0003לכתחלה\u0004 — \u0003לא\u0004 ישחוט, שמא לא ישחט כראוי. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003לעולם שוחטין, בין ביום ובין בלילה, בין בראש הגג בין בראש הספינה,\u0004 ומשמע ששוחטים בלילה לכתחילה!","\u0003אמר רב פפא:\u0004 מה ששנינו ששוחטים לכתחילה בלילה הוא \u0003בשאבוקה\u0004 דולקת \u0003כנגדו. אמר רב אשי: דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר בלשון הברייתא והמשנה, \u0003דקתני התם דומיא\u0004 \u0005[שהוא שונה שם,\u0006 בברייתא, שחיטה בלילה \u0005בדומה]\u0006 ל\u0003יום\u0004 (\"בין ביום ובין בלילה\"), \u0003והכא דומיא\u0004 \u0005[וכאן,\u0006 במשנה, \u0005הוא שונה\u0006 שחיטה בלילה \u0005בדומה]\u0006 ל\u0003סומא,\u0004 שאינו רואה כלל. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא."]]};
